window.AHMED_TERMS = [{"id":1,"en":"Abnormal Spoilage","ar":"تلف غير عادي","definition_en":"Unacceptable units that are not expected to occur under an efficient production process.","definition_ar":"وحدات غير مقبولة، لا يتوقع حدوثها في ظل عمليات إنتاج ذات فعالية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":2,"en":"Absorbed Overhead","ar":"فوقيّة مُمتصة","definition_en":"That portion of factory indirect cost that has been allocated to a specific product, or saleable service. (Also called Applied Overhead.)","definition_ar":"جزئية من التكاليف الغير مباشرة في المصنع، تُخصص لمنتج محدد، أو خدمة قابلة للبيع. (يسمى أيضاً فوقية تطبيقية.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":3,"en":"Absorption Costing","ar":"احتساب التكاليف بالامتصاص","definition_en":"A costing system that assigns to inventory all types of manufacturing costs, including direct, indirect, fixed, and variable. (Also called Full Absorption Costing.)","definition_ar":"نظام لاحتساب التكاليف، يُكلّف به المخزون بجميع أنواع تكاليف التصنيع، تشمل التكاليف المباشرة، و غير المباشرة، و الثابتة، و المتغيرة. (يسمى أيضاً احتساب التكاليف بالامتصاص التام.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":4,"en":"Accelerated Depreciation","ar":"اهتلاك مُتسارع","definition_en":"A pattern of depreciation in which the amount of depreciation computed in the early years is greater than the amounts computed in the later years.","definition_ar":"نمط من أنماط الاهتلاك، يُحسب به الاهتلاك في السنوات الأولى بمبلغ أكبر من المبلغ الذي يحسب في السنوات اللاحقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":5,"en":"Accounting","ar":"محاسبة","definition_en":"The process of identifying, classifying, measuring, recording and communicating in monetary terms transactions and events of an economic entity that are of a financial character.","definition_ar":"عملية تعريف، و تصنيف، و قياس، و تسجيل، و تواصل لمعاملات و أحداث في كيان اقتصادي، تكون ذات صفة مالية في ظل أحكام النقد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":6,"en":"Accounting Cycle","ar":"دورة المحاسبة","definition_en":"The steps an accountant follows to analyze and record business transactions, prepare financial statements, and prepare for the next accounting period.","definition_ar":"خطوات، يتّبعها المحاسب لتحليل و تسجيل معاملات الأعمال، و لتحضير القوائم المالية، و للتحضير لفترة المحاسبة التالية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":7,"en":"Accounting Information System","ar":"نظام معلومات المحاسبة","definition_en":"A system that collects, stores, and processes data to provide information to an organization’s decision makers.","definition_ar":"نظام، يُجمّع، و يُخزّن، و يُعالج البيانات لتوفير المعلومات لصنّاع القرار في الوحدة المنظمة","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":8,"en":"Accounting Profit","ar":"ربح المحاسبة","definition_en":"Revenue less all expenses included in the entity’s income statement.","definition_ar":"الإيراد ناقص جميع المصاريف و كلاهما تشمله قائمة الدخل في الكيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":9,"en":"Accounting Standards","ar":"معايير المحاسبة","definition_en":"Principles and procedures to be followed by accountants as formulated by an authoritative body. (Also called Accounting Principles.)","definition_ar":"مبادئ و إجراءات، يتّبعها المحاسبون إذ جرت صياغتها من قبل جهة مصرّحة. (يسمى أيضاً مبادئ المحاسبة.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":10,"en":"Accounting System","ar":"نظام المحاسبة","definition_en":"Methods, procedures, and standards followed in accumulating, classifying, recording and reporting business events and transactions.","definition_ar":"طرق، و إجراءات، و معايير، تُتبع لتراكم، و تصنيف، و تسجيل، و إعداد التقارير عن أحداث و معاملات الأعمال.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":11,"en":"Accounts Payable","ar":"حسابات دائنة","definition_en":"Monies that are due to a vendor (supplier) for merchandise or services rendered.","definition_ar":"أموال، تُستحق لبائع (مورّد) نظير ما أسدى من بضائع أو خدمات.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":12,"en":"Accounts Payable Turnover","ar":"دوران الحسابات الدائنة","definition_en":"A financial ratio used to measure the rate at which an entity pays off its suppliers.","definition_ar":"نسبة مالية، تُستخدم في قياس معدل دفعات الكيان لمورديه.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":13,"en":"Accounts Receivable","ar":"حسابات مدينة","definition_en":"Monies due to an entity from customers who have bought merchandise or received services on account.","definition_ar":"أموال، تُستحق للكيان من الزبائن الذين اشتروا بضائع أو استلموا خدمات على الحساب.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":14,"en":"Accounts Receivable Turnover","ar":"دوران الحسابات المدينة","definition_en":"A financial ratio used to measure asset utilization and a company’s ability to collect cash from credit sales to its customers.","definition_ar":"نسبة مالية، تُستخدم في قياس الاستنفاع من الأصول و مقدرة الشركة على تحصيل النقد من زبائن مبيعات الائتمان.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":15,"en":"Accrual Accounting","ar":"محاسبة الاستحقاق","definition_en":"The method of recognizing and recording (a) revenues when earned, and (b) expenses when incurred, both irrespective of the time when cash is received or paid.","definition_ar":"طريقة للاعتراف و تسجيل (أ) الإيرادات عندما تُجنى، و(ب) المصاريف عندما تُتكبد، بغض النظر عن وقت استلام أو دفع النقد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":16,"en":"Accrued","ar":"مستحق","definition_en":"The accumulation of income that is due but has not been received or a cost that is incurred but has not been paid by an entity during the accounting period.","definition_ar":"المتراكم من دخل أُستحقّ و لكن لم يُستلم، أو تكلفة تُكُبّدت و لكن لم تدفع و ذلك أثناء فترة المحاسبة في الكيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":17,"en":"Accumulated Depreciation","ar":"اهتلاك متراكم","definition_en":"The amount of depreciation expense related to a fixed asset that has been recognized as an expense from the date of acquisition of that asset.","definition_ar":"مبلغ مصاريف الاهتلاك ذي العلاقة بأصل ثابت، يُعترف به كمصاريف منذ تاريخ استحواذ ذلك الأصل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":18,"en":"Acid-Test Ratio","ar":"نسبة السيولة السريعة","definition_en":"A ratio that measures an entity’s ability to pay off short-term obligations using the most liquid current assets (excluding inventory). (Also called Quick Ratio.)","definition_ar":"نسبة لقياس مقدرة الكيان على دفع الالتزامات القصيرة المدة باستخدام أكثر الأصول الجارية سيولة (باستبعاد المخزون). (يسمى أيضاً النسبة السريعة.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":19,"en":"Acquisition Cost","ar":"تكلفة الاستحواذ","definition_en":"The value of cash or other resources given up in exchange for goods or services. It includes all costs necessary to get the asset ready for its intended use. (Also called Historical Cost or Original Cost.)","definition_ar":"قيمة النقد أو الموارد الأخرى، يُتخلّى عنها كاستبدال لبضاعة أو خدمات. تشمل جميع التكاليف الضرورية لجعل الأصل جاهز للاستخدام المنشود. (يسمى أيضاً التكلفة التاريخية أو التكلفة الأصلية.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":20,"en":"Activity Driver (Cost Driver)","ar":"محرك النشاط (محرك التكلفة)","definition_en":"A factor used to assign cost from an activity to a cost object. A measure of the frequency and intensity of use of an activity by a cost object.","definition_ar":"عامل، يُستخدم في تكليف تكلفة من نشاط ما على مادة التكلفة. و هو قياس لتكرار و كثافة استخدام نشاط ما من قبل مادة التكلفة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":21,"en":"Activity-Based Budgeting","ar":"إعداد الموازنة على أساس النشاط","definition_en":"An approach to budgeting that involves quantifying activities and processes and forecasting their costs in order to achieve strategic goals and improve performance.","definition_ar":"نهج لإعداد الموازنة، يَتضمن قياس كمي للأنشطة و العمليات و إعداد توقّعات للتكاليف من أجل إنجاز الأهداف الاستراتيجية و تحسين الأداء.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":22,"en":"Activity-Based Costing (ABC)","ar":"احتساب التكاليف على أساس النشاط (ABC)","definition_en":"A costing system that (a) identifies the relationship between the incurrence of cost and activities, (b) determines the underlying “driver” of the activities, (c) establishes cost pools related to individual “drivers,” (d) develops costing rates, and (e) applies cost to product on the basis of resources consumed (drivers).","definition_ar":"نظام لاحتساب التكاليف به (أ) تُعرف العلاقة بين تكبّد التكلفة و الأنشطة، و (ب) يُحدد “المحرك” مُرتكز الأنشطة، و (ج) تُؤسس تجمّعات التكلفة ذات العلاقة بـ “محركات” فردية، و (د) تُطوّر معدلات احتساب التكاليف، و (هـ) تُطبّق التكلفة على المنتج حسب أسس الموارد المستهلكة (المحركات).","topic":"Cost Management","difficulty":"Intermediate"},{"id":23,"en":"Activity-Based Management","ar":"إدارة على أساس النشاط","definition_en":"Management and decision making method using activity based costing information in an effort to improve customer satisfaction and profits by enhancing activities that add value and reducing activities that do not add value to the customer.","definition_ar":"طريقة في الإدارة و صنع القرار، يُستخدم فيها معلومات من احتساب التكاليف على أساس النشاط كجهد لتحسين رضا الزبائن و الأرباح و ذلك بتعزيز الأنشطة التي تضيف قيمة و تخفيض الأنشطة التي لا تضيف قيمة للزبون.","topic":"Cost Management","difficulty":"Intermediate"},{"id":24,"en":"Actual Cost","ar":"تكلفة فعلية","definition_en":"Acquisition cost, historical cost, or original cost.","definition_ar":"تكلفة الاستحواذ، أو التكلفة التاريخية، أو التكلفة الأصلية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":25,"en":"Additional Paid-in Capital","ar":"رأس مال إضافي مدفوع","definition_en":"The amount received by a company from its shareholders for purchase of shares of stock above the par or stated value of the stock.","definition_ar":"مبلغ، تستلمه الشركة من أصحاب الحصص لشراء حصص من الأسهم و هو أعلى من القيمة الوُجهيّة أو القيمة التي وردت للسهم.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":26,"en":"Administrative Expense","ar":"مصاريف إدارة الموارد","definition_en":"Costs incurred for the general operation of an enterprise as a whole, as contrasted with costs related to a more specific function such as manufacturing or selling. (Also called General and Administrative Expense.)","definition_ar":"تكاليف، تُتكبد من مُجمل التشغيل العام في المؤسسة (enterprise)، و تتباين مع التكاليف المتعلقة بمسارات عمل أكثر تحديداً، كالتصنيع أو البيع. (يسمى أيضاً مصاريف عامة و إدارية.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":27,"en":"Aging Schedule","ar":"جدول التقادم","definition_en":"A listing of the amounts owed to a company by the length of time outstanding.","definition_ar":"قائمة بالمبالغ المستحقة لشركة ما حسب المدة الزمنية منذ تعليقها.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":28,"en":"Allocate","ar":"تخصيص","definition_en":"Identification of costs with cost objectives; apportioning or distributing costs to products, processes, jobs, or departments.","definition_ar":"تعريف التكاليف مع غايات التكلفة؛ بعمل نسب أو تُوزيع التكاليف على المنتجات، أو العمليات، أو الوظائف، أو الدوائر.","topic":"Cost Management","difficulty":"Intermediate"},{"id":29,"en":"Allocation Base","ar":"أساس التخصيص","definition_en":"The basis used to assign indirect costs to cost objects, such as labor or machine hours.","definition_ar":"أسس، تُستخدم في تكليف التكاليف غير المباشرة على مواد التكلفة، كساعات العمل أو ساعات الآلة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":30,"en":"Allowance for Uncollectible Accounts","ar":"مسموحات الحسابات الغير قابلة للتحصيل","definition_en":"A contra account to Accounts Receivable established to record the estimated percentage of Accounts Receivable that will not be collected.","definition_ar":"حساب مُعاكس للحسابات المدينة، يُؤسس لتسجيل تقدير للحسابات المدينة التي لن تحصّل كنسبة مئوية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":31,"en":"Amortization","ar":"إهلاك","definition_en":"The accounting process of allocating costs to the time periods during which such costs are consumed.","definition_ar":"عملية في المحاسبة لتخصيص تكاليف على فترات زمنية، تُستهلك أثناؤها تلك التكاليف.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":32,"en":"Annual Report","ar":"تقرير سنوي","definition_en":"A report prepared by entities after the close of each reporting year that includes financial statements and disclosure, an audit report, information from management, and other pertinent information concerning the entity’s financial condition and operating performance.","definition_ar":"تقرير، تُحضّره الكيانات بعد إغلاق كل سنة من سنوات إعداد التقرير، يشمل القوائم المالية مع الإفصاحات، و تقرير التدقيق، و معلومات عن الإدارة، و معلومات أخرى ذات صلة تخص الحالة المالية و أداء التشغيل في الكيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":33,"en":"Annuity","ar":"سنوية","definition_en":"A series of payments of an equal amount at fixed intervals for a specified number of periods.","definition_ar":"دفعات متسلسلة بمبالغ متساوية عند فواصل بينية ثابتة لعدد محدد من الفترات.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":34,"en":"Application Controls","ar":"ضوابط التطبيق","definition_en":"Controls, such as input controls, adopted to safeguard specific data processing activity, such as payroll. Their purpose is to provide reasonable assurance that data is properly processed, recorded, and reported.","definition_ar":"ضوابط كضوابط المدخلات، تتبنى لحماية نشاط معالجة بيانات محدد، ككشوف الرواتب. و الغرض منها توفير تأكيد معقول على أن البيانات قد عُولجت، و سُجّلت، و أُعدّت تقارير فيها على نحو لائق.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":35,"en":"Appraisal Costs","ar":"تكاليف التقويم","definition_en":"Costs incurred to determine whether products and services are conforming to customer and/or manufacturing requirements. Examples include inspection and testing costs.","definition_ar":"تكاليف، تُتكبد لتحديد ما إذا كانت المنتجات والخدمات مطابقة لمتطلبات الزبون و/أو التصنيع. و تشمل الأمثلة تكاليف التفتيش و الفحص.","topic":"Cost Management","difficulty":"Intermediate"},{"id":36,"en":"Appreciation","ar":"ارتفاع القيمة","definition_en":"The situation where there is an increase in economic worth caused by rising market prices.","definition_ar":"وضعية، يزداد فيها المقدار الاقتصادي بسبب ارتفاع أسعار السوق.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":37,"en":"Arbitrage Pricing Theory (APT)","ar":"نظرية موازنة الأسعار (APT)","definition_en":"A framework for analyzing the relationship between risks and rates of return on securities, especially common stocks. It asserts that the risk elements that influence returns on securities include (1) inflation, (2) industrial production, (3) risk premiums, and (4) the slope of the term structure of interest rates.","definition_ar":"إطار عمل لتحليل العلاقة بين المخاطر و معدلات العائد على الأوراق المالية، بالأخص الأسهم العادية. و تجزم هذه النظرية على أن عناصر المخاطر التي تؤثر على عائدات الأوراق المالية، تشمل (1) التضخم، (2) و الإنتاج الصناعي، (3) و علاوة المخاطر، (4) و ميل هيكل المدة لمعدلات الفائدة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":38,"en":"Asset","ar":"أصل","definition_en":"1. Probable future economic benefits obtained by an entity as a result of past transactions. 2. Any owned physical object or right having economic value to its owners, expressed for accounting purposes in terms of its cost or other value (such as current replacement cost).","definition_ar":"1. منافع اقتصادية محتملة في المستقبل، يحصل عليها. 2. أي مادة عينية أو حق مملوك له قيمة اقتصادية للمالكين، يعبّر عنه لأغراض أحكام المحاسبة بتكلفته أو بقيم أخرى (كتكلفة الإحلال الحالية).","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":39,"en":"Asset Coverage","ar":"تغطية الأصول","definition_en":"A measure of the extent to which a company is able to cover its debt obligations after all liabilities have been satisfied.","definition_ar":"قياس مدى قدرة الشركة على تغطية التزاماتها من الديون بعد الوفاء بكافة المطلوبات.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":40,"en":"Asset Turnover","ar":"دوران الأصول","definition_en":"A financial ratio that assesses how efficiently an entity is utilizing its assets; it relates sales to assets. (Also called Total Asset Turnover.)","definition_ar":"نسبة مالية لتقييم فعالية الكيان في الاستنفاع من أصوله؛ بعمل علاقة بين المبيعات و الأصول. (يسمى أيضاً مجموع دوران الأصول.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":41,"en":"Audit","ar":"تدقيق","definition_en":"The systematic examination by analyses, confirmation, and tests of accounting records to confirm with reasonable assurance that the records adequately reflect economic status and operations.","definition_ar":"اختبار نظامي، يَستخدم تحليلات، و تثبيت، و فحص على سجلات المحاسبة للتثبيت بتأكيد معقول أن السجلات تعكس على نحو كافٍ الوضع الاقتصادي و التشغيل.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":42,"en":"Audit Committee","ar":"لجنة التدقيق","definition_en":"Members of the board of directors (in the case of corporations), trustees, legislative bodies, or similar governance boards, with responsibilities for oversight and direction of the internal auditing function.","definition_ar":"أعضاء مجلس الإدارة (في حالة الشركات العامة corporations)، أو الأمناء، أو الجهات التشريعية، أو مجالس الحوكمة المشابهة، الذين يتولّون مسؤوليات الرقابة و التوجيه على مسار عمل التدقيق الداخلي.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":43,"en":"Audit Report","ar":"تقرير التدقيق","definition_en":"A written document that presents the scope and results of the audit.","definition_ar":"وثيقة مكتوبة، يقدّم فيها نطاق و نتائج التدقيق.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":44,"en":"Authoritative (Top-Down) Budgeting","ar":"إعداد موازنة مصرّحة (من القمة للأسفل)","definition_en":"A budgeting process where all budgets for the organization are prepared by top management, including budgets for lower-level operations.","definition_ar":"عملية لإعداد الموازنة، تُحضّر بها جميع موازنات الوحدة المنظمة من قبل قمة الإدارة، و تشمل موازنات التشغيل في المستويات الأدنى.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":45,"en":"Authority","ar":"سلطة","definition_en":"The formal and legitimate right of a manager to make decisions, issue orders, and allocate resources to achieve organizationally desired outcomes.","definition_ar":"حق رسمي و مشروع للمدير في صُنع القرارات، و إصدار الطلبيات، و تخصيص الموارد لإنجاز النتائج المرغوب بها تنظيمياً.","topic":"Performance Management","difficulty":"Intermediate"},{"id":46,"en":"Authorized Shares","ar":"حصص مصرّح بها","definition_en":"Maximum number of shares of stock a firm is authorized to offer to the public.","definition_ar":"أقصى عدد من حصص الأسهم، يُصرّح للمنشأة بطرحها العام.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":47,"en":"Available-for-Sale Securities","ar":"أوراق مالية متاحة للبيع","definition_en":"Under GAAP, investments the company may hold or sell.","definition_ar":"بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، ما يمكن للشركة أن تمسكه أو تبيعه من استثمارات.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":48,"en":"Average Collection Period","ar":"متوسط فترة التحصيل","definition_en":"A measure of the average number of days it takes to collect receivables (credit sales). (Also called Days Sales Outstanding and Days Sales in Receivables.)","definition_ar":"قياس لمتوسط عدد الأيام التي يستغرقها التحصيل من المدينين (مبيعات الائتمان). (يسمى أيضاً أيام تعليق المبيعات و أيام المبيعات في الحسابات المدينة.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":49,"en":"Average Days in Inventory","ar":"متوسط أيام المخزون","definition_en":"The average number of days an item is held in inventory.","definition_ar":"متوسط عدد الأيام التي يُحتفظ فيها ببند ما كمخزون.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":50,"en":"Average Fixed Cost","ar":"متوسط التكلفة الثابتة","definition_en":"Total fixed costs divided by the number of units produced. (Fixed cost per unit)","definition_ar":"مجموع التكاليف الثابتة مقسوماً على عدد الوحدات المنتجة. (التكلفة الثابتة لكل وحدة)","topic":"Cost Management","difficulty":"Intermediate"},{"id":51,"en":"Average Total Cost","ar":"متوسط مجموع التكلفة","definition_en":"Total manufacturing costs divided by the number of units produced. Sometimes called per unit cost.","definition_ar":"مجموع تكاليف التصنيع مقسوماً على عدد الوحدات المنتجة. و تسمى أحياناً التكلفة لكل وحدة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":52,"en":"Average Variable Cost","ar":"متوسط التكلفة المتغيرة","definition_en":"Total variable cost divided by the number of units produced.","definition_ar":"مجموع التكلفة المتغيرة مقسوماً على عدد الوحدات المنتجة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":53,"en":"Backflush Costing","ar":"احتساب التكاليف بترجيع التدفق","definition_en":"A product costing approach used in a Just-in-Time operating environment in which some or all of the costing is delayed until the goods are finished. Standard costs are then pulled backward through the system to assign costs to products.","definition_ar":"نهج لاحتساب تكاليف المنتج، يُستخدم في بيئة التشغيل «فقط وقت الحاجة» (Just-in-Time) التي فيها يُؤخّر بعض أو كل احتساب التكاليف حتى تصبح البضاعة تامة. حينها تُسحب التكاليف المعيارية بالرجوع للخلف من خلال النظام و ذلك لتكليف التكاليف على المنتجات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":54,"en":"Backup Controls","ar":"ضوابط الاحتياط","definition_en":"Controls, such as file duplicating, in an Information Technology (IT) environment to insure that data is not lost.","definition_ar":"ضوابط، كالنسخ المطابق لملف، في بيئة تكنولوجيا المعلومات (IT) لتأمين عدم ضياع البيانات.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":55,"en":"Bad Debts","ar":"ديون معدومة","definition_en":"Accounts or notes receivable that management determines to be uncollectible after reasonable efforts to collect them have not been successful.","definition_ar":"حسابات أو إشعارات مدينة، تُحدد الإدارة أنها غير قابلة للتحصيل بعد بذل جهود معقولة لتحصيلها وعدم نجاحها.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":56,"en":"Bad Debts Expense","ar":"مصاريف الديون المعدومة","definition_en":"The expense to record uncollectible accounts receivable.","definition_ar":"مصاريف لتسجيل الحسابات المدينة الغير قابلة للتحصيل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":57,"en":"Balance Sheet","ar":"ميزانية عمومية","definition_en":"A financial statement that summarizes a company’s assets, liabilities and shareholders’ equity at a particular point in time.","definition_ar":"قائمة مالية، يُلّخص فيها أصول، و مطلوبات، و حقوق ملكية أصحاب الحصص لشركة ما في تاريخ معين.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":58,"en":"Balanced Scorecard","ar":"بطاقة النتائج المتوازنة","definition_en":"An approach using multiple measures to evaluate performance, including financial measures, and the non-financial measures of customers, internal business processes, and learning and growth.","definition_ar":"نهج، يَستخدم قياسات متعددة في تقييم الأداء، تشمل قياسات مالية، و قياسات غير مالية للزبائن، و معالجة الأعمال الداخلية، و التعلم و النمو.","topic":"Performance Management","difficulty":"Intermediate"},{"id":59,"en":"Banker’s Acceptances","ar":"قبولات البنك","definition_en":"Financial instrument of an entity stating that payment is guaranteed by a bank, commonly used in foreign trade.","definition_ar":"أداة مالية للكيان، يَردُ فيها أن الدفع مضمون من قبل أحد البنوك، و هي شائعة الاستخدام في التجارة الأجنبية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":60,"en":"Bankruptcy","ar":"إفلاس","definition_en":"A condition in which a court has granted a company legal protection from creditors because it cannot meet its obligations as they come due.","definition_ar":"حالة، تَمنح فيها المحكمة شركة ما الحماية القانونية من الدائنين لأنها لا تستطيع تلبية التزاماتها عندما تصبح مستحقة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":61,"en":"Batch Costing","ar":"احتساب التكاليف على دُفعات","definition_en":"The costs of activities related to a group of units of products or services rather than to each individual unit of product or service.","definition_ar":"تكاليف الأنشطة ذات العلاقة بمجموعة من وحدات المنتجات أو الخدمات بدلًا من تلك المتعلقة بكل وحدة فردية من المنتج أو الخدمة على حدة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":62,"en":"BCG Growth-Share Matrix","ar":"مصفوفة حصة النمو (BCG)","definition_en":"A method of analyzing a portfolio of products or businesses. Developed by the Boston Consulting Group, it classifies businesses as Stars, Cash Cows, Dogs, or Question Marks.","definition_ar":"طريقة لتحليل محفظة من المنتجات أو الأعمال. طَوّرتها مجموعة بوسطن الاستشارية، و تُصنّف الأعمال بها كنجوم، أو أبقار النقد، أو كلاب، أو علامات استفهام.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":63,"en":"Benchmarking","ar":"قياس بالمقارنة","definition_en":"A process of measuring an entity’s performance, products, and services against standards based on best levels of performance achievable or achieved by other entities.","definition_ar":"عملية تقيس الأداء، و المنتجات، و الخدمات في الكيان بمقابلتها مع معايير الكيانات الأخرى كأفضل أساس لمستويات الأداء القابلة للإنجاز أو المنجزة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":64,"en":"Best Practice","ar":"أفضل مزاولة","definition_en":"A technique, method, process, or activity that is more effective at delivering a particular outcome than any other technique, method, process, or activity.","definition_ar":"تقنية، أو طريقة، أو عملية، أو نشاط له فاعلية أكبر في الوصول لنتيجة معينة من أي تقنية، أو طريقة، أو عملية، أو نشاط آخر.","topic":"Performance Management","difficulty":"Intermediate"},{"id":65,"en":"Beta","ar":"بيتا","definition_en":"A measurement of the movement of the price of a particular stock compared with the movement of the market as a whole during the same period. If a stock has a beta value less than 1, it is regarded as less risky than the overall market. If a stock has a beta value greater than 1, it is regarded as more risky than the market","definition_ar":"قياس حركة سعر سهم معين مقارنة مع مجمل حركة السوق أثناء الفترة نفسها. فإذا كان سهم ما ذو قيمة بيتا أقل من 1، فإنه يعتبر ذو خطورة أقل من السوق العام. و إذا كان سهم ما ذو قيمة بيتا أكبر من 1، فإنه يعتبر ذو خطورة أعلى من السوق العام","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":66,"en":"Big Data","ar":"بيانات هائلة","definition_en":"Data sets that are too large and complex for traditional database applications, including both structured and unstructured data.","definition_ar":"مجموعات بيانات كبيرة و معقدة جداً في تطبيقات قواعد البيانات التقليدية، تشمل كلا البيانات المُهيكلة وغير المُهيكلة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":67,"en":"Binomial Option-Valuation Models","ar":"نماذج تقدير قيمة الخيار الثنائية","definition_en":"Option pricing models in which the underlying asset can take on only two possible, discrete values in the next time period for each value that it can take on in the preceding time period.","definition_ar":"نماذج لتسعير الخيار، يمكن بها للأصل المُرتكز أن يأخذ قيمتين بتبصُّر فقط للفترة الزمنية التالية، و ذلك عن كل قيمة يمكن أن يأخذها لفترة زمنية سابقة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":68,"en":"Biometrics","ar":"(Biometrics) قياسات حيوية","definition_en":"A means of authenticating identity for access control on the of basis of physical characteristics.","definition_ar":"وسيلة للمصادقة على الهوية لضبط الدخول، قوامها أسس الخصائص الجسمانية.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":69,"en":"Black-Scholes Option-Valuation Model","ar":"نموذج تقدير قيمة الخيارِ بلاك سكولز (Black-Scholes)","definition_en":"A model for pricing options in which the value of an option depends on (1) the value of the underlying asset, (2) the time to expiration of the option, (3) the exercise price, (4) the volatility of the underlying asset, and (5) the risk-free rate or time value of money.","definition_ar":"نموذج لتسعير الخيارات، تَتبع فيه قيمة الخيار (1) قيمة الأصل المُرتكز (2) الفترة الزمنية لانتهاء صلاحية الخيار (3) سعر الممارسة (4) تقلّبات الأصل المرتكز (5) معدل خلو المخاطر أو قيمة المال مع الوقت.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":70,"en":"Blockchain","ar":"(Blockchain) سلسلة-بلوك","definition_en":"A digital ledger or a list of records, called blocks, that continually increase in number, cannot be altered, and are linked using cryptography (see distributed ledger.)","definition_ar":"أستاذ رقمي أو قائمة سجلات، تُسمى بلوكز (blocks)، تتزايد أعدادها باستمرار، ولا يمكن تبديلها، و هي مترابطة باستخدام تشفير رقمي (أنظر الأستاذ المُوزّع.)","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":71,"en":"Board of Directors","ar":"مجلس الإدارة","definition_en":"A group of individuals elected by a corporation’s shareholders to oversee the management of the corporation. The members of a Board of Directors meet periodically and assume legal responsibility for corporate activities.","definition_ar":"مجموعة من الأفراد المنتخبين من قبل أصحاب الحصص في شركة عامة للإشراف على إدارة الشركة العامة. و يجتمع أعضاء مجلس الإدارة دورياً و يأخذ على عاتقه المسؤولية القانونية لنشاطات الشركة العامة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":72,"en":"Bond","ar":"صك","definition_en":"A long-term debt instrument signifying the promise of the issuer to pay the face amount at the maturity date. Periodic interest payments are often required.","definition_ar":"أداة دين طويلة المدة، تُشير لوعدٍ من المُصدر بدفع المبلغ الوُجهي عند تاريخ الاستحقاق. و مراراً، تَتطلب دفعات فوائد دورية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":73,"en":"Bonds Payable","ar":"حسابات دائنة للصكوك","definition_en":"A long-term liability account used to record the amount of bonds that are outstanding.","definition_ar":"حساب مطلوبات طويل المدة، يُستخدم لتسجيل مبلغ الصكوك المعلّقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":74,"en":"Book Value","ar":"قيمة الدفتر","definition_en":"The amount at which an asset or a liability is carried on the books of account, net of any contra account. (Also called Net Book Value.)","definition_ar":"مبلغ، تُحمّل به الأصول أو المطلوبات في دفاتر الحسابات، صافٍ من أي حساب معاكس. (يسمى أيضاً صافي قيمة الدفتر.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":75,"en":"Book Value per Share","ar":"قيمة الدفتر لكل حصة","definition_en":"Measures common shareholder equity on a per share basis.","definition_ar":"تقيس حقوق ملكية أصحاب الحصص العادية بأسس الحصة الواحدة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":76,"en":"Bottleneck","ar":"عنق الزجاجة","definition_en":"Operational constraints or inefficient usage of available resources creating workinprocess inventory buildup and/or idle time.","definition_ar":"معيقات التشغيل أو الاستخدام الغير فعّال للموارد المتاحة، و تسبب تصاعد مخزون قيد تشغيل العمل و/أو الوقت المعطّل.","topic":"Cost Management","difficulty":"Intermediate"},{"id":77,"en":"Bottom-Up Approach","ar":"نهج من القاع للأعلى","definition_en":"An approach to auditing internal controls whereby all controls are documented irrespective of risk.","definition_ar":"نهج لتدقيق الضوابط الداخلية، تُوثّق به جميع الضوابط بغض النظر عن المخاطر.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":78,"en":"Breakeven Analysis","ar":"تحليل التعادل","definition_en":"An analysis of the relationship of cost and revenue. It determines the volume at which there is neither profit nor loss for a product or group of products. (Also called Cost/Volume/Profit Analysis.)","definition_ar":"تحليل للعلاقة بين التكلفة و الإيراد. يحدد الحجم الذي لا يوجد عنده ربح أو خسارة لمنتج أو مجموعة منتجات. (يسمى أيضاً تحليل التكلفة/الحجم/الربح.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":79,"en":"Breakeven Point","ar":"نقطة التعادل","definition_en":"The volume of sales at which total revenues and total costs are equal.","definition_ar":"حجم المبيعات التي يتساوى عندها مجموع الإيرادات و مجموع التكاليف.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":80,"en":"Budget","ar":"موازنة","definition_en":"A schedule of planned or expected revenues, expenses, assets, and liabilities. A budget provides guidelines for future operations and appraisal of performance. (Also called Profit Plan.)","definition_ar":"جدول للإيرادات، و المصاريف، و الأصول، و المطلوبات حسب ما هو مخطط أو متوقع. و تُوفّر الموازنة إرشادات للمستقبل في التشغيل و تقويم الأداء. (يسمى أيضاً خطة الربح.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":81,"en":"Budget Process","ar":"عملية الموازنة","definition_en":"The process used by an organization to prepare a plan for a future period, allocate resources, determine revenues and expenditures, and compile reports pertaining to that plan.","definition_ar":"عملية، تستخدمها الوحدة المنظمة لتحضير خطة لفترة مقبلة، و لتخصيص الموارد، و لتحديد الإيرادات و النفقات، و لجمع التقارير ذات العلاقة بتلك الخطة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":82,"en":"Budgetary Slack","ar":"تراخي الموازنة","definition_en":"Intentional underestimation of revenues and/or overestimation of expenses.","definition_ar":"تقدير، يُتعمّد به بخَس تقدير الإيرادات و/أو مبالغة تقدير المصاريف.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":83,"en":"Budgeting","ar":"إعداد الموازنة","definition_en":"The process of planning flows of financial resources into, within, and from an entity during a specified future period or for a specified project.","definition_ar":"عملية التخطيط لتدفقات الموارد المالية إلى، أو ضمن حيز، أو من كيان ما أثناء فترة محددة أو لمشروع محدد في المستقبل.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":84,"en":"Business","ar":"أعمال","definition_en":"A commercial or industrial enterprise.","definition_ar":"مؤسسة (enterprise) تجارية أو صناعية.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":85,"en":"Business Combination","ar":"تركيبة الأعمال","definition_en":"A grouping of a company with other businesses into a single accounting entity for reporting purposes (consolidated financial statements). The company and the other businesses continue to operate as separate entities.","definition_ar":"تجميع شركة مع غيرها من الأعمال، تُعدُّ ككيان فردي في المحاسبة بغرض إعداد التقارير (قوائم مالية موحدة). و تستمرُ تلك الشركة و الأعمال الأخرى في التشغيل ككيانات منفصلة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":86,"en":"Business Continuity Planning","ar":"تخطيط لاستمرار الأعمال","definition_en":"The creation of a strategy to ensure that personnel and assets are protected and able to function in the event of a disaster.","definition_ar":"خلق استراتيجية للتوكيد على أن الموظفين و الأصول محميين و قادرين على تأدية مسارات العمل إذا ما حدثت كارثة ما.","topic":"Risk Management","difficulty":"Intermediate"},{"id":87,"en":"Business Intelligence (BI)","ar":"ذكاء الأعمال (BI)","definition_en":"Technology-driven process for analyzing data and presenting actionable information to help make informed business decisions.","definition_ar":"عملية تقودها التكنولوجيا في تحليل البيانات و تقديم المعلومات القابلة للتفعيل للمساعدة في صنع قرارات مطلعة للأعمال","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":88,"en":"Business Model","ar":"نموذج الأعمال","definition_en":"Describes how an organization creates and delivers value.","definition_ar":"يَصف كيف تَخلقُ و تَوصّلُ الوحدة المنظمة القيمة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":89,"en":"Business Plan","ar":"خطة الأعمال","definition_en":"A document prepared by a company’s management, detailing the past, present, and future of the company. It forms the basis for preparing budgets for the individual company units.","definition_ar":"وثيقة، تُحضّرها إدارة الشركة لتفصيل ماضي، و حاضر، و مستقبل الشركة. و هي تُشكّلُ أسس تحضير الموازنات للوحدات الفردية في الشركة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":90,"en":"Business Portfolio","ar":"محفظة الأعمال","definition_en":"A collection of products, projects, services, or brands that are offered for sale by an entity.","definition_ar":"حصيلة منتجات، أو مشروعات، أو خدمات، أو علامات تجارية، تُطرح للبيع من قبل كيان ما.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":91,"en":"Business Process","ar":"عمليات الأعمال","definition_en":"A sequence of logically related & time based work activities to provide a specific output for a customer.","definition_ar":"سلسلة متعاقبة من أنشطة عمل ما ذات علاقة منطقية و أساسها الوقت، تُوفّر مُخرج محدد لزبون ما.","topic":"Cost Management","difficulty":"Intermediate"},{"id":92,"en":"Business Unit","ar":"وحدة الأعمال","definition_en":"Any segment of an organization, or an entire business entity that is not divided into segments. Sometimes treated as a Profit Center.","definition_ar":"أي مقطع من وحدة منظمة، أو كيان الأعمال بأكمله على أن لا يكون مُقسّم إلى مقاطع. و يُعامل كمركز ربح في بعض الأحيان.","topic":"Performance Management","difficulty":"Intermediate"},{"id":93,"en":"Byproduct","ar":"منتج جانبي","definition_en":"An item resulting from a production process that has relatively little value compared to the company’s main product.","definition_ar":"بند، يَنتُج من عملية إنتاج ما ذو قيمة قليلة نسبياً مقارنة بالمنتج الأساسي للشركة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":94,"en":"Call Option","ar":"خيار الشراء","definition_en":"A contract that gives the buyer the right to buy an asset (for example a share of stock) at a specified price within a specified period of time.","definition_ar":"عقد، يَعطي المشتري الحق في شراء أصل ما (على سبيل المثال حصة من أسهم) بسعر محدد وضمن حيز فترة من الزمن محددة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":95,"en":"Capacity Constraints","ar":"معيقات طاقة الإنتاج","definition_en":"Resources that limit the maximum performance possible considering the conditions of the existing physical plant, labor force, method of production, or supply of material.","definition_ar":"موارد، تَحُدّ من ما هو ممكن من أداءٍ عالٍ، نظراً لحالة ما هو موجود من أصول عينية، أو قوى عمل، أو طريقة إنتاج، أو توريد مواد.","topic":"Cost Management","difficulty":"Intermediate"},{"id":96,"en":"Capacity Management","ar":"إدارة طاقة الإنتاج","definition_en":"Management of an entity’s costs of unused (excess) capacity such as production facilities, distribution channels, etc.","definition_ar":"إدارة التكاليف في كيان ذي طاقة إنتاج غير مستخدمة (فائضة) كمرافق الإنتاج، وقنوات التوزيع، و إلخ.","topic":"Cost Management","difficulty":"Intermediate"},{"id":97,"en":"Capital","ar":"رأس المال","definition_en":"1. The equity invested in an entity by its owners. 2. Total assets less liabilities. 3. Long-term assets (e.g., equipment). Resources or assets that an organization has or needs to create value; in integrated reporting/ thinking, capital is generally organized into six categories: financial, manufacturing, human, social and relationship, intellectual, and natural.","definition_ar":"1. حقوق الملكية المستثمرة في كيان ما من قبل مالكيها. 2. مجموع الأصول ناقص المطلوبات. 3. أصول طويلة المدة (مثل، المعدات). موارد أو أصول لدى الوحدة المنظمة أو ما تَحتاج لخلق القيمة؛ بإعداد تقارير/تفكير متكاملة، و يُنظّمُ رأس المال في ست فئات عموماً: المالية، و التصنيع، و البشر، و المجتمع و العلاقات، و الفِكر، و الطبيعة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":98,"en":"Capital Adequacy","ar":"كفاية رأس المال","definition_en":"The amount of capital relative to a company’s assets. A useful measure in risk management (particularly for banks).","definition_ar":"مبلغ رأس المال بالنسبة إلى أصول الشركة. و هو قياس مفيد في إدارة المخاطر (للبنوك خاصة).","topic":"Risk Management","difficulty":"Intermediate"},{"id":99,"en":"Capital Asset Pricing Model (CAPM)","ar":"نموذج تسعير أصول رأس المال (CAPM)","definition_en":"A general framework for analyzing the relationship between risks and rates of return on securities, especially common stocks.","definition_ar":"إطار عمل عام لتحليل العلاقة بين المخاطر و معدل العائد على الأوراق المالية، بالأخص الأسهم العادية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":100,"en":"Capital Budget","ar":"موازنة رأس المال","definition_en":"A plan of proposed outlays for acquiring long term assets and the means of financing the acquisition.","definition_ar":"خطة استنفاقات مقترحة للاستحواذ على أصول طويلة المدة مع و سائل تمويل الاستحواذ.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":101,"en":"Capital Budgeting","ar":"إعداد موازنة رأس المال","definition_en":"The evaluation and making of long-term investment decisions.","definition_ar":"تقييم و صنع قرارات لاستثمار طويل المدة.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":102,"en":"Capital Expenditure","ar":"نفقات رأس المال","definition_en":"A cost that is recorded as a long-term asset, not an expense, at the time it is incurred.","definition_ar":"تكلفة، تُسجّل كأصل طويل المدة، و ليست مصاريف، تُتكبدُ في وقتها.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":103,"en":"Capital Gain or Loss","ar":"خسارة أو مكسب رأس المال","definition_en":"The extent by which the net realized value from sales of a capital asset exceeds (or in the case of a capital loss is less than) the cost of acquisition plus additional improvements, less depreciation and/or depletion charges.","definition_ar":"مدى تَجاوز صافي القيمة المحقق من مبيعات أصل رأس المال (أو يقل في حال خسارة رأس المال) تكلفة الاستحواذ زائد التحسينات الإضافية، و ناقصاً منها ثمن الاهتلاك و/أو النفاذ.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":104,"en":"Capital Investment","ar":"استثمار رأس المال","definition_en":"Any expenditure which increases the capacity, efficiency, life span, or economy of the operation of an existing fixed asset. Outlay of money from which future cash inflows are expected for more than a year. (Also referred to as Capital Expenditure.)","definition_ar":"أية نفقات، تؤدي إلى زيادة طاقة إنتاج، أو فعالية، أو مدى حياة، أو تقتصد في تشغيل أصلٍ ثابتٍ موجود. و استنفاق المال، يُتوّقع منه تدفقات واردة للنقد في أكثر من سنة مقبلة. (يُشار إليه أيضاً كنفقات رأس المال.)","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":105,"en":"Capital Lease","ar":"تأجير رأس المال","definition_en":"A lease that transfers substantially all the benefits and risks inherent in the ownership of the property to the lessee, who accounts for the lease as an acquisition of an asset & the incurrence of a liability.","definition_ar":"تأجير، يُحوّل كافة المنافع و المخاطر الكامنة في ملكية الممتلكات إلى المستأجر بحدٍ كبير، الذي يُحاسب على التأجير كاستحواذ للأصل و يَتكبّد المطلوبات.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":106,"en":"Capital Stock","ar":"أسهم رأس المال","definition_en":"Ownership shares in a corporation issued to shareholders. May consist of Common Stock and Preferred Stock.","definition_ar":"حصص الملكية في شركة عامة، يتم إصدارها لأصحاب الحصص. و يمكن أن تتكوّن من أسهم عادية و أسهم ممتازة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":107,"en":"Capital Structure","ar":"هيكل رأس المال","definition_en":"The relative proportions of short-term debt, long- term debt, and owners’ equity in the company.","definition_ar":"نسب نسبية لديون قصيرة المدة، و ديون طويلة المدة، و حقوق الملكية للمالكين في الشركة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":108,"en":"Capitalize","ar":"رسملة","definition_en":"To record expenditure that is expected to benefit a future period as an asset rather than treating the expenditure as an expense of the period in which it occurs.","definition_ar":"لتسجيل نفقات من المتوقع أن تَنفع في فترة مقبلة كأصول، بدلًا من التعامل مع تلك النفقات كمصاريف في الفترة التي تحدث فيها.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":109,"en":"Carrying Cost","ar":"تكلفة محمّلة","definition_en":"Costs of storing and holding inventory, including the cost of capital from the time of acquisition or manufacture until the time of sale or use.","definition_ar":"تكاليف التخزين و الإمساك على المخزون، تشمل التكاليف الرأسمالية منذ وقت الاستحواذ أو التصنيع حتى وقت البيع أو الاستخدام.","topic":"Cost Management","difficulty":"Intermediate"},{"id":110,"en":"Carrying Value","ar":"قيمة محمّلة","definition_en":"The amount shown on an entity’s financial statements for assets, liabilities, or owner’s equity, net of reductions or offsets.","definition_ar":"مبالغ، تُستعرض في القوائم المالية للكيان من أصول، أو مطلوبات، أو حقوق ملكية للمالكين، صافٍ منها التخفيضات أو المعاوضات.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":111,"en":"Cartel","ar":"(Cartel) كارتل","definition_en":"An organization of sellers coordinating supply decisions to maximize joint profits. A cartel seeks to create a monopoly in the market.","definition_ar":"منظمة لباعة، يُنسّقوا فيما بينهم لعمل قرارات عرض تُعظّم الأرباح المشتركة. و يسعى الكارتل لخلق احتكار في السوق.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":112,"en":"Cash","ar":"نقد","definition_en":"Refers to money in the form of liquid currency that a bank will accept for immediate deposit, such as coins, checks, and money orders.","definition_ar":"يُشير إلى مال على شكل عُملات مسيّلة، يقبلها البنك كإيداع فوري، كالقطع المعدنية، و الشيكات، و طلبيات المال.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":113,"en":"Cash Budget","ar":"موازنة النقد","definition_en":"An estimate of the amount and timing of cash receipts and disbursements at various points over a future period, and cash on hand at the end.","definition_ar":"تقدير لمبلغ و توقيت المقبوضات و المصروفات نقداً في مواعيدها المختلفة خلال فترة مقبلة، و النقد النهائي الذي في اليد.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":114,"en":"Cash Cow","ar":"بقرة النقد","definition_en":"A division, or product, that is not growing, but is generating significant cash flow, which can be transferred to other, faster growing divisions.","definition_ar":"قسم، أو منتج، لا ينمو، لكنه يولّد تدفق نقد ذي أهمية، يُمكن تحويله إلى الآخرين، كالأقسام التي تنمو أسرع.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":115,"en":"Cash Cycle","ar":"دورة النقد","definition_en":"The period of time during which cash is converted into inventories, and inventories are converted back into cash through the sale of goods or collection of accounts receivable. (Also called Cash Conversion Cycle or Earnings Cycle.)","definition_ar":"فترة من الزمن، يُحوّل خلالها النقد إلى مخزون، ثم يرجع المخزون و يتحوّل إلى نقد من خلال بيع البضاعة أو تحصيل الحسابات المدينة. (يسمى أيضاً دورة تحوّل النقد أو دورة المدخولات.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":116,"en":"Cash Discount","ar":"خصم النقد","definition_en":"A reduction in the basic price, commonly used to encourage prompt payment or promote sales.","definition_ar":"تخفيض السعر الأساسي، وهو شائع الاستخدام لتشجيع الدفع الحثيث أو الترويج للمبيعات.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":117,"en":"Cash Equivalents","ar":"مُعادِلات النقد","definition_en":"Short-term financial instruments of high liquidity and safety which can be converted to cash on short notice","definition_ar":"أدوات مالية قصيرة المدة و عالية السيولة و الأمان، يُمكن أن تُحوّل إلى نقد في غضون إخطار قصير","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":118,"en":"Cash Flow","ar":"تدفق النقد","definition_en":"The stream of cash inflows and outflows of an entity or segment of an entity.","definition_ar":"مجرى تدفقات واردة للنقد أو تدفقات صادرة للنقد لكيان أو لمقطع في كيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":119,"en":"Cash Flow at Risk","ar":"تدفق النقد عند المخاطر","definition_en":"A probabilistic estimate of the sensitivity of cash flow; how budgeted cash flow might be affected by changes in certain risk factors and other variables.","definition_ar":"تقدير احتمالي لحساسية تدفق النقد، و كيف يمكن لتدفق نقد الموازنة أن تؤثر فيه تغيرات معينة في عوامل المخاطر و غيرها من المتغيرات.","topic":"Risk Management","difficulty":"Intermediate"},{"id":120,"en":"Cash Flow Ratio","ar":"نسبة تدفق النقد","definition_en":"A liquidity measure, whereby operating cash flow is divided by current liabilities.","definition_ar":"قياس للسيولة، و هو تدفق النقد من التشغيل مقسوماً على المطلوبات الجارية.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":121,"en":"Cash Flow to Fixed Charges","ar":"تدفق النقد إلى الرسوم الثابتة","definition_en":"A leverage ratio that measures the cash flow available to meet fixed charges.","definition_ar":"نسبة المديونية التي تقيس تدفق النقد المتاح لتلبية الرسوم الثابتة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":122,"en":"Cash from Financing Activities","ar":"نقد من أنشطة التمويل","definition_en":"Under GAAP, all cash receipts & all cash disbursements from issuing debt, receiving contributions from owners, and paying dividends to owners.","definition_ar":"بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، جميع المقبوضات نقداً و جميع المصروفات نقداً من إصدار لدين، و استلام مساهمات من المالكين، و دفع توزيعات الأرباح للمالكين.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":123,"en":"Cash from Investing Activities","ar":"نقد من أنشطة الاستثمار","definition_en":"Under GAAP, all cash receipts and cash disbursements from transactions involving long- term assets and investments in other firms.","definition_ar":"بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، جميع المقبوضات نقداً و المصروفات نقداً من معاملات تتضمن الأصول طويلة المدة، و الاستثمارات في المنشآت الأخرى.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":124,"en":"Cash from Operating Activities","ar":"نقد من أنشطة التشغيل","definition_en":"Under GAAP, all cash receipts and cash disbursements that result from transactions involving revenues and expenses.","definition_ar":"بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، جميع المقبوضات نقداً و المصروفات نقداً التي تنتج من معاملات تتضمن إيرادات و مصاريف.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":125,"en":"Cash Management","ar":"إدارة النقد","definition_en":"The processes an entity uses to collect, disburse, and invest its cash.","definition_ar":"عمليات، يستخدمها الكيان لتحصيل، و صرف، و استثمار نقده.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":126,"en":"Cash Ratio","ar":"نسبة النقد","definition_en":"A measure of a company’s liquidity that relates cash and marketable securities to current liabilities.","definition_ar":"قياس سيولة الشركة بعمل علاقة بين النقد و الأوراق المالية بقابلية السوق مع المطلوبات الجارية.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":127,"en":"Centralization","ar":"مركزية","definition_en":"An organizational structure in which senior management maintains significant direction, authority, and control over all operations & policies.","definition_ar":"هيكل تنظيمي، يحتفظ كبار الإداريين فيه بما هو ذي أهمية من توجيه، و سلطة، و ضبط على كافة العمليات و السياسات.","topic":"Performance Management","difficulty":"Intermediate"},{"id":128,"en":"Change in the Quantity Demanded","ar":"تغير في كمية الطلب","definition_en":"A change in the quantity that buyers are willing to purchase at different price levels due only to a change in price. Often referred to as a movement along the demand curve.","definition_ar":"تغير في الكمية التي يرغب المشترون في شرائها عند مستويات أسعار مختلفة بسبب تغير السعر فقط. مراراً، يُشار إليها بأنها حركة على طول منحنى الطلب.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":129,"en":"Change in the Quantity Supplied","ar":"تغير في كمية العرض","definition_en":"A change in the quantity sellers are willing to supply due only to a change in price. Often referred to as a movement along the supply curve.","definition_ar":"تغير في الكمية التي يرغب البائعون في توريدها بسبب تغير السعر فقط. مراراً، يُشار إليها بأنها حركة على طول منحنى العرض.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":130,"en":"Chart of Accounts","ar":"دليل الحسابات","definition_en":"A list of all of the accounts in a firm’s accounting records.","definition_ar":"قائمة بجميع الحسابات التي في سجلات المحاسبة لمنشأة ما.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":131,"en":"Classification","ar":"تصنيف","definition_en":"Supervised machine learning whereby you group objects into one of a set of predefined classes.","definition_ar":"تعلّم الآلة الخاضع للإشراف، يمكن به تجميع المواد في مجموعة واحدة ذات تصنيفات سابقة التعريف.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":132,"en":"Cloud Computing","ar":"حوسبة سَحابية","definition_en":"The delivery of computer services over the internet, including software, data storage, hardware, and applications.","definition_ar":"توصيل خدمات في الحوسبة من خلال الإنترنت، تشمل البرمجيات، و تخزين البيانات، و الأجهزة، و التطبيقات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":133,"en":"Clustering","ar":"عنقدة","definition_en":"Unsupervised machine learning whereby natural groupings in data are found such that the objects in the groups are more like each other than to other groups.","definition_ar":"تعلّم الآلة الغير الخاضع للإشراف، توجد به تجميعات طبيعية للبيانات كالمواد التي في مجموعاتها تكون متشابهة فيما بينها أكثر من غيرها في المجموعات الأخرى.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":134,"en":"Code of Conduct","ar":"دليل قواعد التصرفات","definition_en":"A set of rules outlining acceptable ethical behavior for employees within an organization.","definition_ar":"مجموعة من القواعد، تَخُطُّ بخطوط عريضة السلوك الأخلاقي المقبول من الموظفين ضمن حيز الوحدة المنظمة.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":135,"en":"Coefficient of Determination","ar":"معامل التحديد","definition_en":"The proportion of the variation in the dependent variable that is predicted by the independent variable (R squared.)","definition_ar":"نسبة التغير في المتغير التابع، يُتنبأ به بواسطة المتغير المستقل (آر التربيعية.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":136,"en":"Coefficient of Variation","ar":"معامل التغيّر","definition_en":"A statistical measure of relative dispersion or relative risk. It is computed by dividing the standard deviation by the expected value.","definition_ar":"قياس إحصائي للتشتت النسبي أو المخاطر النسبية. و يُحسب بتقسيم الانحراف المعياري على القيمة المتوقعة.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":137,"en":"Collateral","ar":"ضمان تبعي","definition_en":"An asset pledged as a guarantee to a lender until a loan is repaid. If the borrower defaults, the lender has a right to sell the collateral asset.","definition_ar":"أصل، يُستعهد كضمان للمقرض حتى يتم دفع القرض. و إذا قصّر المقترض، يحق للمقرض بيع أصل الضمان التبعي.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":138,"en":"Commercial Bank","ar":"بنك تجاري","definition_en":"An institution that accepts deposits, offers checking accounts, makes loans, and offers a variety of other related services.","definition_ar":"مؤسسة (institution)، تقبل الودائع، و تطرح الحسابات الجارية، و تمنح القروض، و تطرح أنواعاً مختلفة من الخدمات الأخرى ذات العلاقة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":139,"en":"Commercial Paper","ar":"ورقة تجارية","definition_en":"A short-term unsecured loan of a corporation having maturity up to 270 days. It is typically issued on a discount (from face value) basis.","definition_ar":"قرض غير مضمون قصير المدة لشركة عامة، يصل استحقاقه إلى 270 يوماً. و نموذجياً، يُصدرُ على أسس من الخصم (من القيمة الوُجهيّة).","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":140,"en":"Commitment Fee","ar":"رسم الالتزام","definition_en":"A fee paid to a financial institution by an entity to secure a line of credit and maintain the unused portion thereof.","definition_ar":"رسم، يدفعه كيان لمؤسسة تمويل (institution) لضمان خط الائتمان و لحفظ الجزئية غير المستخدمة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":141,"en":"Committee of Sponsoring Organizations (COSO)","ar":"لجنة المنظمات الراعية (COSO)","definition_en":"A voluntary private-sector organization, established in the U.S., dedicated to providing guidance on organizational governance, business ethics, internal control, enterprise risk management, fraud, and financial reporting.","definition_ar":"منظمة قطاع خاص تطوعية، تأسست في الولايات المتحدة، مُكرّسة لتوفير الإرشاد في الحوكمة التنظيمية، و أخلاقيات الأعمال، و الضوابط الداخلية، و إدارة مخاطر المؤسسات (enterprise)، و الاحتيال، و إعداد التقارير المالية.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":142,"en":"Common Base Year Statements","ar":"قوائم سنة الأساس المشتركة","definition_en":"Financial Statements showing the percentage change over a base year. (Also called Horizontal Analysis.)","definition_ar":"قوائم مالية، تستعرض النسبة المئوية للتغير على أساس سنة ما. (يسمى أيضاً التحليل الأفقي.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":143,"en":"Common Cost","ar":"تكلفة مشتركة","definition_en":"A cost of operating a facility that is shared by two or more users.","definition_ar":"تكلفة تشغيل مرفق ما، يشترك فيها اثنين أو أكثر من المستخدمين.","topic":"Cost Management","difficulty":"Intermediate"},{"id":144,"en":"Common Stock","ar":"أسهم عادية","definition_en":"An ownership share in a company, having voting and dividend rights.","definition_ar":"حصص ملكية في الشركة، ذات حقوق في التصويت و توزيع الأرباح.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":145,"en":"Common-Size Financial Statements","ar":"قوائم مالية ذات مقاس مشترك","definition_en":"Financial statements used for comparison between firms. A common size Income Statement shows all amounts as a percent of revenue. A common size Balance Sheet shows all values as a percent of total assets.","definition_ar":"قوائم مالية، تُستخدم للمقارنة بين المنشآت. و تُستعرض في قائمة الدخل ذات المقاس المشترك جميع المبالغ كنسب مئوية من الإيراد. و تُستعرض في الميزانية العمومية ذات المقاس المشترك جميع القيم كنسب مئوية من مجموع الأصول.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":146,"en":"Company Risk","ar":"مخاطر الشركة","definition_en":"The risk due to the unique circumstances of a specific enterprise, as opposed to the overall market. (Also called Unsystematic Risk.)","definition_ar":"مخاطر جرّاء ظروف فريدة في مؤسسة (enterprise) محددة ما، تتعارض مع السوق العام. (يسمى أيضاً مخاطر غير نظامية.)","topic":"Risk Management","difficulty":"Intermediate"},{"id":147,"en":"Comparability","ar":"قابلية المقارنة","definition_en":"The quality of information that enables users to identify similarities in and differences between two sets of economic phenomena.","definition_ar":"نوعية المعلومات، تُمكّن مستخدميها من تعريف المتشابهات و الفروقات بين مجموعتين من الظواهر الاقتصادية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":148,"en":"Compensating Balance","ar":"رصيد التعويض","definition_en":"An amount required to be kept on deposit at a bank.","definition_ar":"مبلغ، يتطلب المحافظة عليه كوديعة في البنك.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":149,"en":"Compensation","ar":"تعويضات","definition_en":"Employee or management wages and other financial benefits earned from labor.","definition_ar":"أجور الموظفين أو الإدارة وغيرها من المنافع المالية، يتم جنيها من العمل.","topic":"Performance Management","difficulty":"Intermediate"},{"id":150,"en":"Competence","ar":"جدارة","definition_en":"An ethical standard in IMA’s Statement of Ethical Professional Practice that requires members to maintain an appropriate level of professional expertise and perform duties in accordance with relevant laws and standards.","definition_ar":"معيار أخلاقي من بيان الآي.أم.أيه. (IMA) لمزاولة المهنة بأخلاقية، يَتطلب من الأعضاء أن يحتفظوا بمستوى متناسب من الخبرة المهنية و أن يؤدوا الواجبات وفقاً للقوانين و المعايير ذات العلاقة.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":151,"en":"Competition-Based Pricing","ar":"تسعير على أساس المنافسة","definition_en":"A pricing strategy wherein the price of a product is determined primarily by the price being charged by one or more competitors.","definition_ar":"إستراتيجية تسعير لتحديد سعر منتج، يُثمّن بها السعر في المقام الأول بواسطة واحد أو أكثر من المنافسين.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":152,"en":"Competitive Analysis","ar":"تحليل التنافس","definition_en":"Comparison of the competitive advantage of the planning company and its identified competitors.","definition_ar":"مقارنة ميزة التنافس بين شركة ذات خطة و منافسيها المُعرّفين.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":153,"en":"Completed-Contract Method","ar":"طريقة العقد المُكتمل","definition_en":"An accounting method that defers recognition of revenues until the completion of a contract, but recognizes anticipated losses immediately.","definition_ar":"طريقة في المحاسبة، تُؤجّل الاعتراف بالإيرادات حتى اكتمال العقد، و لكن تعترف بالخسائر المنتظرة فوراً.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":154,"en":"Compliance Audit","ar":"تدقيق الامتثال","definition_en":"A type of internal audit that reviews an organization’s adherence to laws, rules, policies, and procedures.","definition_ar":"نوع من التدقيق الداخلي لمراجعة تقيّد الوحدة المنظمة بالقوانين، و القواعد، و السياسات، و الإجراءات.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":155,"en":"Compliance Risk","ar":"مخاطر الامتثال","definition_en":"Risk to earnings or capital arising from violations of laws, rules, regulations, policies, procedures, and/or ethical standards.","definition_ar":"مخاطر على المدخولات أو رأس المال، تنجم عن انتهاكات للقوانين، أو القواعد، أو اللوائح، أو السياسات، أو الإجراءات، و/أو المعايير الأخلاقية.","topic":"Risk Management","difficulty":"Intermediate"},{"id":156,"en":"Compound Interest","ar":"فائدة مركبة","definition_en":"Interest resulting from the periodic addition of simple interest to principal, establishing the new base as the principal for computation of interest for the next period.","definition_ar":"فائدة، تنتج من إضافة دورية لفائدة بسيطة على أصل الدين، مما يجدد تأسيس أصل الدين بأساس جديد تحسب عليه الفائدة للفترة التالية.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":157,"en":"Comprehensive Income","ar":"دخل شامل","definition_en":"All changes in equity during a period except those resulting from investments by owners and distributions to owners.","definition_ar":"كافة التغيرات على حقوق الملكية أثناء فترة ما عدا التغيرات التي تنتج من استثمارات المالكين أو توزيعات على المالكين.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":158,"en":"Concentration Banking","ar":"أعمال البنك بالتركيز","definition_en":"A procedure utilized to manage cash wherein an entity utilizes a large bank (the Concentration Bank) to gather all the cash from smaller local (depository) banks where customers make payments.","definition_ar":"إجراء، يُستنفع به في إدارة النقد إذ به يَستنفع الكيان ببنك كبير (بنك التركيز) لتجميع كل النقد من البنوك المحلية الأصغر (بنوك الإيداع) التي عن طريقها يدفع الزبائن.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":159,"en":"Confidentiality","ar":"السرية","definition_en":"An ethical standard in IMA’s Statement of Ethical Professional Practice that requires members to keep employer information confidential and to not use confidential information for personal advantage.","definition_ar":"معيار أخلاقي من بيان الآي.أم.أيه. (IMA) لمزاولة المهنة بأخلاقية، يَتطلب من الأعضاء المحافظة على سرية معلومات صاحب العمل و عدم استخدام المعلومات السرية لمنفعة شخصية.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":160,"en":"Conservatism","ar":"تحفّظ","definition_en":"1. An accounting concept that states that revenues are recognized only when they are reasonably certain, but expenses are recognized when they are probable. 2. A prudent reaction to uncertainty to try to ensure that uncertainty and risks inherent in business situations are adequately considered.","definition_ar":"1. مفهوم في المحاسبة، يَردُ فيه أن الإيرادات يُعترف بها فقط عند اليقين بها بحد معقول، و لكن المصاريف يُعترف بها عندما تكون محتملة. 2. رد فعل حصيف على عدم اليقين في محاولة للتوكيد على أن عدم اليقين و المخاطر الكامنة في وضعيات الأعمال، هما قيد النظر على نحو كافٍ.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":161,"en":"Consistency","ar":"اتساق","definition_en":"Conformity from period to period with unchanging policies and procedures.","definition_ar":"تطابق من فترة إلى فترة مع سياسات و إجراءات لا تتغير.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":162,"en":"Consolidated Financial Statements","ar":"قوائم مالية موحدة","definition_en":"Financial Statements showing financial condition or operating results of 2 or more associated enterprises as they would appear if they were one entity.","definition_ar":"قوائم مالية، تستعرض الحالة المالية أو نتائج التشغيل لمؤسستين (enterprise) مرتبطتين أو أكثر لتظهرا كما إذا كانا كيان واحد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":163,"en":"Constant Gross Profit Method","ar":"طريقة الربح الإجمالي الثابت","definition_en":"A method of allocating joint costs where costs are allocated so that the overall gross-margin percentage is identical for each individual product. (Also called Gross Margin Method.)","definition_ar":"طريقة لتخصيص التكاليف المشتركة، تُخصص بها التكاليف لتكون النسبة المئوية للهامش الإجمالي ككل متطابقة لكل منتج فردي. (يسمى أيضاً طريقة الهامش الإجمالي.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":164,"en":"Constraint","ar":"معيق","definition_en":"An activity, resource, or policy that limits or bounds the attainment of an objective.","definition_ar":"نشاط، أو مورد، أو سياسة تَحدُّ أو تُقيّد من إحراز الغاية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":165,"en":"Contingency Planning","ar":"التخطيط للعوارض","definition_en":"Planning for the response to situations that may occur such as emergencies or setbacks","definition_ar":"تخطيط للاستجابة لوضعيات ممكن أن تحدث كالطوارئ أو النّكسات","topic":"Risk Management","difficulty":"Intermediate"},{"id":166,"en":"Continuous Budget","ar":"موازنة مستمرة","definition_en":"A moving projection of financial operations for a series of weeks, months, or quarters immediately ahead. At the end of each period, the portion of the projection then lapsed is removed and a new projection for a period of similar length is added to the series. (Also called Rolling Budget.)","definition_ar":"عرض تصوّرات متحرك لعمليات مالية في مسلسل من أسابيع، أو شهور، أو أرباع التالية على الفور. و عند نهاية كل فترة، تُزال الجزئية التي مضت من عرض التصورات ليضاف للمسلسل عرض تصوّرات جديد لفترة ذات مدة مشابهة. (يسمى أيضاً موازنة اللّف.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":167,"en":"Continuous Improvement","ar":"تحسين مستمر","definition_en":"A management approach to productivity improvement, where planned improvements occur in small incremental amounts by refinement of all components of a process. (Also called Kaizen.)","definition_ar":"نهج في الإدارة لتحسين الإنتاجية، تحدث به التحسينات المخطط لها بمبالغ تزايدية صغيرة و ذلك بتنقيح كافة مكونات العملية. (يسمى أيضاً كايزن (Kaizen).)","topic":"Cost Management","difficulty":"Intermediate"},{"id":168,"en":"Contributed Capital","ar":"رأس المال المساهم به","definition_en":"Equity resulting from the contributions of owners, also known as paid-in capital.","definition_ar":"حقوق ملكية، تَنتجُ من مساهمات المالكين، و أيضا يُعرفُ برأس المال المدفوع.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":169,"en":"Contribution Margin","ar":"هامش المساهمة","definition_en":"The excess of sales revenues over variable costs. (Also called Marginal Contribution or Marginal Income.)","definition_ar":"فائض إيرادات المبيعات على التكاليف المتغيرة. (يسمى أيضاً المساهمة الهامشية أو الدخل الهامشي.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":170,"en":"Contribution Pricing","ar":"تسعير المساهمة","definition_en":"A method of establishing the price of the product based on variable costs and usually a profit margin.","definition_ar":"طريقة لتأسيس سعر المنتج على أساس التكاليف المتغيرة و عادةً على هامش الربح.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":171,"en":"Control Risk","ar":"مخاطر الضوابط","definition_en":"A measure of the auditor’s assessment of the likelihood that misstatements exceeding a tolerable level will not be prevented or detected by the client’s internal control system.","definition_ar":"قياس تقييم المدقق لترجيح أن البيانات غير صحيحة، و أنها تتجاوز المستوى المسموح به في عدم منعها أو اكتشافها بواسطة نظام الضوابط الداخلي للعميل.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":172,"en":"Controllable Cost","ar":"تكلفة قابلة للضبط","definition_en":"A cost that can be influenced by the actions of the responsible manager.","definition_ar":"تكلفة يمكن أن تتأثر بأفعال المدير المسؤول.","topic":"Performance Management","difficulty":"Intermediate"},{"id":173,"en":"Controller","ar":"مراقب مالي","definition_en":"The individual within an entity who is responsible for the accounting function. (Also called Comptroller.)","definition_ar":"شخص ضمن حيز الكيان يكون مسؤولًا عن مسار عمل المحاسبة. (يسمى أيضاً (Comptroller).)","topic":"Internal Controls","difficulty":"Intermediate"},{"id":174,"en":"Controls","ar":"ضوابط","definition_en":"Measures put in place to monitor activities and ensure they are functioning as designed.","definition_ar":"قياسات، تُوضع كما ينبغي لترصد الأنشطة، و لتُوكّد على تأدية مسارات العمل كما في التصميم.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":175,"en":"Conversion Cost","ar":"تكلفة التحوّل","definition_en":"The sum of all manufacturing costs except direct material.","definition_ar":"حاصل جمع كل تكاليف التصنيع عدا المواد المباشرة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":176,"en":"Convertible","ar":"قابل للتحوّل","definition_en":"Securities (bonds or preferred stock) issued by companies which can be converted into common shares at a given price at a future date.","definition_ar":"أوراق مالية (صكوك أو أسهم ممتازة) صادرة عن شركات، يمكن أن تُحوّلها إلى حصص عادية بسعر معطى في تاريخ مقبل.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":177,"en":"Corporate Governance","ar":"حوكمة الشركات","definition_en":"The set of rules, processes, policies and/or laws by which an organization is directed, operated and controlled.","definition_ar":"مجموعة قواعد، و عمليات، و سياسات، و/أو قوانين بها تُوجّه، و تُشغّل، و تُضبط الوحدة المنظمة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":178,"en":"Correlation","ar":"ارتباط","definition_en":"The extent or degree of statistical association among two or more variables.","definition_ar":"مدى أو درجة الارتباط الإحصائي بين متغيرين أو أكثر.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":179,"en":"Cost (noun)","ar":"تكلفة (كاسم)","definition_en":"1. In management accounting, a measurement in monetary terms, of the amount of resources used for some purpose. 2. In financial accounting, the sacrifice measured by the price paid or required to be paid, to acquire goods or services.","definition_ar":"1. في المحاسبة الإدارية، هي القياس بأحكام النقد، وهي مبلغ الموارد المستخدمة لغرض ما. 2. في المحاسبة المالية، تُقاس التضحية بالسعر المدفوع أو المطلوب أن يُدفع، للاستحواذ على بضاعة أو خدمات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":180,"en":"Cost (verb)","ar":"تكلفة (كفعل)","definition_en":"To ascertain the cost of something.","definition_ar":"للتيقّن من تكلفة شيء ما.","topic":"Cost Management","difficulty":"Intermediate"},{"id":181,"en":"Cost Allocation System","ar":"نظام تخصيص التكلفة","definition_en":"A method by which costs are allocated to cost objects (Job order costing, Process costing, Activity- based costing, and Life-cycle costing).","definition_ar":"طريقة، تخصص بها التكاليف على مواد التكلفة (احتساب تكلفة طلبية عمل، و احتساب تكلفة العمليات، و احتساب التكلفة على أساس النشاط، و احتساب تكلفة دورة الحياة).","topic":"Cost Management","difficulty":"Intermediate"},{"id":182,"en":"Cost Behavior","ar":"سلوك التكلفة","definition_en":"The change or lack of change in the amount of a cost item associated with changes in the level of activity.","definition_ar":"تغير أو نقص التغير في مبلغ بند التكلفة المرتبطة بتغيرات في مستوى النشاط.","topic":"Cost Management","difficulty":"Intermediate"},{"id":183,"en":"Cost Benefit Analysis","ar":"تحليل التكلفة و المنفعة","definition_en":"A tool for planning and reporting that involves the identification and measurement of all costs and benefits attributed to an activity.","definition_ar":"أداة للتخطيط و إعداد التقارير، تتضمن تعريف و قياس التكاليف و المنافع التي تعزى لنشاط ما.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":184,"en":"Cost Center","ar":"مركز تكلفة","definition_en":"A grouping of operating costs having some common characteristics for measuring performance and assigning responsibility. A Responsibility Center where the manager is responsible for costs only.","definition_ar":"تجميع تكاليف التشغيل ذات الخصائص المشتركة لقياس الأداء و لتكليف المسؤولية. في مركز المسؤولية، يكون المدير مسؤولًا عن التكاليف فقط.","topic":"Performance Management","difficulty":"Intermediate"},{"id":185,"en":"Cost Driver","ar":"مُحرّك التكلفة","definition_en":"A variable causally affecting costs over a time period.","definition_ar":"متغير، يُؤثر على التكاليف سببياً على امتداد فترة زمنية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":186,"en":"Cost Leadership","ar":"قيادة التكلفة","definition_en":"The ability of a company to compete by producing at lower cost than competitors.","definition_ar":"مقدرة الشركة على التنافس بإنتاجٍ تكلفته أقل من المنافسين.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":187,"en":"Cost Management","ar":"إدارة التكاليف","definition_en":"Actions undertaken by managers to satisfy customers while continuously controlling and reducing costs.","definition_ar":"أفعالٌ، يَتعهدها المدراء لإرضاء الزبائن بينما يضبطون و يخفّضون التكاليف باستمرار.","topic":"Cost Management","difficulty":"Intermediate"},{"id":188,"en":"Cost Objects","ar":"مواد التكلفة","definition_en":"A function, organizational subdivision, contract, or other work unit for which cost data are desired and for which provision is made to accumulate and measure the cost of processes, products, jobs, capitalized projects, etc.","definition_ar":"مسار عمل، أو قسم فرع تنظيمي، أو عقد، أو وحدة عمل، يُرغب في الحصول على بيانات تكلفتها، فيّعد لها تدبير لتراكم و قياس تكاليف العمليات، و المنتجات، و الوظائف، و المشاريع الرأسمالية و إلخ.","topic":"Cost Management","difficulty":"Intermediate"},{"id":189,"en":"Cost of Capital","ar":"تكلفة رأس المال","definition_en":"A measure of the cost of using capital. A weighted average of the interest cost of debt capital and the implicit cost of equity capital. It is the minimum rate of return that must be earned on new investments that will not dilute the interests of the shareholders.","definition_ar":"قياس تكلفة استخدام رأس المال. كمتوسط مرجح لتكلفة فوائد الدين في رأس المال و التكلفة الضمنية من حقوق الملكية في رأس المال. و هي أدنى معدل عائد لن يخفف من مصالح أصحاب الحصص، و يجب جَنيُهُ من الاستثمارات الجديدة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":190,"en":"Cost of Goods Sold","ar":"تكلفة البضاعة المباعة","definition_en":"The inventory costs of the goods sold during a specific time period; the difference between the costs of goods available for sale during a specific period of time and the cost of goods on hand at the end of the period. Inventory costs include all costs necessary to get the product ready for sale.","definition_ar":"تكاليف المخزون من البضاعة المباعة أثناء فترة زمنية محددة؛ و هي الفرق بين تكاليف البضاعة المتاحة للبيع أثناء فترة من الزمن محددة و تكلفة البضاعة التي في اليد عند نهاية الفترة. و تشمل تكاليف المخزون جميع التكاليف الضرورية لجعل المنتج جاهز للبيع.","topic":"Cost Management","difficulty":"Intermediate"},{"id":191,"en":"Cost of Quality","ar":"تكلفة النوعية","definition_en":"Costs incurred to detect, prevent, or rectify poor quality production.","definition_ar":"تكلفة مُتكبدة لاكتشاف، أو منع، أو تدارك ضعف نوعية الإنتاج.","topic":"Cost Management","difficulty":"Intermediate"},{"id":192,"en":"Cost of Sales","ar":"تكلفة المبيعات","definition_en":"The cost of products or services whose sales are reported as revenue. (Also called Cost of Goods Sold.)","definition_ar":"تكلفة منتجات أو خدمات، يُعد بها تقارير مبيعات كإيرادات. (يسمى أيضاً تكلفة البضاعة المباعة.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":193,"en":"Cost Pools","ar":"تجمعات التكلفة","definition_en":"The collection of cost elements that have a common cause and that can be assigned to other cost objects according to a common basis of allocation.","definition_ar":"حصيلة عناصر تكلفة ذات مسببات مشتركة، يُمكن تكليف مواد التكلفة الأخرى بها وفقاً لأسس تخصيص مشتركة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":194,"en":"Cost System","ar":"نظام التكلفة","definition_en":"The system an entity utilizes to collect and assign costs to intermediate and final cost objects.","definition_ar":"نظام، يستنفع به الكيان لجمع و لتكليف التكاليف على مواد التكلفة الوسيطة و النهائية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":195,"en":"Cost/Volume/Profit Analysis (CVP)","ar":"تحليل التكلفة/الحجم/الربح (CVP)","definition_en":"An analysis of the relationship of cost and revenue emphasizing both the volume at which there is zero profit and the influence of fixed and variable factors on the profit expectations at various levels of operation. (Also called Breakeven Analysis.)","definition_ar":"تحليل لعلاقة التكلفة بالإيراد مع التشديد على حجم كلاهما الذي يكون الربح عنده صفراً و على العوامل الثابتة و المتغيرة كمؤثر على توقعات الربح في مستويات التشغيل المختلفة. (يسمى أيضاً تحليل التعادل.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":196,"en":"Cost-Based Pricing","ar":"تسعير على أساس التكلفة","definition_en":"The practice of establishing the selling price of a good or service based primarily on the cost to produce it.","definition_ar":"مزاولة تأسيس سعر بيع بضاعة أو خدمة على أساس تكلفة إنتاجها في المقام الأول.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":197,"en":"Costing","ar":"احتساب التكاليف","definition_en":"The accumulation & assignment of costs to cost objects.","definition_ar":"تراكم و تكليف التكاليف على مواد التكلفة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":198,"en":"Cost-Plus Pricing","ar":"تسعير التكلفة زائد","definition_en":"A pricing practice in which the selling price is determined by adding a percentage or monetary amount to the cost of a product.","definition_ar":"مزاولة للتسعير، يُحدد بها سعر البيع بإضافة نسبة مئوية أو مبلغ النقد على تكلفة المنتج.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":199,"en":"Countertrade","ar":"تجارة مكافئة","definition_en":"The trading of goods for other goods. (Also called Barter.)","definition_ar":"تداول بضاعة مقابل بضاعة أخرى. (و يسمى أيضاً مقايضة.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":200,"en":"Coupon Rate","ar":"معدل القسيمة","definition_en":"The annual rate of interest stated on a debt instrument.","definition_ar":"معدل الفائدة السنوي كما ورد في أداة الدين.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":201,"en":"Credibility","ar":"مصداقية","definition_en":"An ethical standard in IMA’s Statement of Ethical Professional Practice that requires members to communicate information fairly and objectively, disclose all relevant information, and to disclose delays or deficiencies in information.","definition_ar":"معيار أخلاقي من بيان الآي.أم.أيه. (IMA) لمزاولة المهنة بأخلاقية، يَتطلب من الأعضاء التواصل بالمعلومات بإنصاف و موضوعية، و الإفصاح عن جميع المعلومات ذات العلاقة، و الإفصاح عن التأخير أو التقصير في المعلومات.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":202,"en":"Credit","ar":"ائتمان","definition_en":"A contractual agreement in which a borrower receives something of value now and agrees to repay the lender at a later date.","definition_ar":"اتفاق تعاقدي، يَستلم به المقترض شيئاً ذا قيمة الآن و يوافق على أن يتم الدفع للمقرض في تاريخ لاحق.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":203,"en":"Credit Risk","ar":"مخاطر الائتمان","definition_en":"An investor’s risk of loss arising from a borrower who defaults; i.e., does not make payments as promised.","definition_ar":"مخاطر خسارة المستثمر التي تنجم عن المقترض الذي يقصّر؛ أي، لا يفي بالدفعات كما وعد.","topic":"Risk Management","difficulty":"Intermediate"},{"id":204,"en":"Critical Success Factors","ar":"عوامل النجاح الحرجة","definition_en":"The important things an entity must do to be successful.","definition_ar":"الأشياء المهمة التي يجب على الكيان فعلها ليكون ناجحاً.","topic":"Performance Management","difficulty":"Intermediate"},{"id":205,"en":"Cumulative Average-Time Learning Model","ar":"نموذج التّعلم بمتوسط وقت تراكمي","definition_en":"A learning curve model in which the cumulative average time per unit declines by a constant percentage each time the cumulative quantity of units produced is doubled.","definition_ar":"نموذج لمنحنى تعلم، يتراجع فيه متوسط الوقت التراكمي لكل وحدة بنسبة مئوية ثابتة لكل مرة تتضاعف فيها الكمية التراكمية من الوحدات المنتجة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":206,"en":"Cumulative Preferred Stock","ar":"أسهم ممتازة تراكمية","definition_en":"Stock whose holders must receive dividends in arrears before a company can pay any current dividends to other shareholders.","definition_ar":"أسهم، يجب أن يستلم حملتها المتأخرات من توزيعات الأرباح قبل أن يمكن للشركة أن تدفع أي توزيعات أرباح حالية لأصحاب الحصص الآخرين.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":207,"en":"Current Assets","ar":"أصول جارية","definition_en":"Cash and other assets that are expected to be sold, consumed or converted into cash during the normal operating cycle of a business.","definition_ar":"نقد و أصول أخرى، يُتوقّع بيعها، أو استهلاكها أو تَحوّلها إلى نقد أثناء دورة التشغيل العادية للأعمال.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":208,"en":"Current Cost","ar":"تكلفة حالية","definition_en":"The amount of cash needed if the same asset, an identical asset, or an asset with equivalent productive capacity were acquired currently.","definition_ar":"مبلغ من النقد، يُحتاج له إذا الأصل نفسه، أو أصل متطابق له، أو أصل بطاقة إنتاجية معادلة له، أُستحوذ عليه حالياً.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":209,"en":"Current Liability","ar":"مطلوبات جارية","definition_en":"A liability required or expected to be discharged (fulfilled) by using current assets within one year or the operating cycle, whichever is longer.","definition_ar":"مطلوبات، تَتطلب أو يُتوّقع لتسريحها (استيفاؤها) استخدام أصول جارية ضمن حيز سنة واحدة أو دورة التشغيل، أيهما أطول.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":210,"en":"Current Ratio","ar":"نسبة جارية","definition_en":"A financial ratio used to measure short-term solvency. (Also called Liquidity Ratio.)","definition_ar":"نسبة مالية تستخدم في قياس الملاءة القصيرة المدة. (يسمى أيضاً نسبة السيولة.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":211,"en":"Customer Satisfaction","ar":"رضا الزبائن","definition_en":"A measure of the extent to which customers are satisfied with the products and related services they received from a supplier.","definition_ar":"قياس مدى رضا الزبائن عن المنتجات التي استلموها من المورّد و الخدمات ذات العلاقة بها.","topic":"Performance Management","difficulty":"Intermediate"},{"id":212,"en":"Cyber-Attacks","ar":"هجمات إلكترونية","definition_en":"In computer technology, an unauthorized attempt to alter, destroy, or steal an organization’s assets.","definition_ar":"في تكنولوجيا الحاسوب، شروع غير مصرح به في تبديل، أو تدمير، أو سرقة أصول وحدة منظمة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":213,"en":"Cycle Time","ar":"زمن الدورة","definition_en":"The total elapsed time to move a unit of work from the beginning to the end of a physical process, as defined by the producer and the customer.","definition_ar":"مجموع الوقت الذي ينقضي في نقل وحدة عمل من بداية إلى نهاية عملية مادية، يُعرّفها المُنتج و الزبون.","topic":"Cost Management","difficulty":"Intermediate"},{"id":214,"en":"Cyclical","ar":"دوري","definition_en":"A type of trend where something (e.g., sales) varies in a regular pattern; a repeated sequence.","definition_ar":"نوع من التّوجُّه، يتغير فيه شيء ما (مثل، المبيعات) عن النمط المنتظم؛ كالسلسلة التي تتكرر.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":215,"en":"Data Analytics","ar":"تحليل البيانات","definition_en":"The quantitative techniques and processes used to cleanse, transform, and model data with the goal of generating business insight for decision making.","definition_ar":"تقنيات و عمليات كمّية، تستخدم في تنظيف، و تناقل، و نمذجة البيانات بهدف توليد رؤى في الأعمال لصنع القرار.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":216,"en":"Data Communications","ar":"اتصالات البيانات","definition_en":"Transfer of data among functional units through data transmission protocols.","definition_ar":"نقل البيانات بين وحدات مسارات العمل من خلال بروتوكولات إرسال البيانات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":217,"en":"Data Encryption","ar":"تشفير البيانات","definition_en":"In computer security, the process of transforming data into an unintelligible form in such a way that the original data either cannot be obtained or can be obtained only by using a decryption process.","definition_ar":"في أمن الحاسوب، عملية تناقل البيانات إلى شكل غير مفهوم بطريقة ما تصبح بها البيانات الأصلية أما لا يمكن الحصول عليها أو يمكن الحصول عليها باستخدام عملية فك التشفير فقط.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":218,"en":"Data Governance","ar":"حوكمة البيانات","definition_en":"Management of the availability, usability, integrity, and security of an organization’s data.","definition_ar":"إدارة إتاحة، و استخدام، و نزاهة، و أمن البيانات لوحدة منظمة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":219,"en":"Data Lifecycle","ar":"دورة حياة البيانات","definition_en":"Sequence of stages that data goes through from initial generation to its eventual deletion at the end of its useful life.","definition_ar":"سلسلة مراحل، تَمرُّ من خلالها البيانات من تَولُّدها الأوّلي إلى حذفها في نهاية المطاف أي عند نهاية عمر الاستفادة منها.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":220,"en":"Data Mining","ar":"تنقيب البيانات","definition_en":"Accessing and examining large data through statistical analysis to generate new information.","definition_ar":"الوصول للبيانات الضخمة و اختبارها من خلال التحليل الإحصائي لتوليد معلومات جديدة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":221,"en":"Data Query Language","ar":"لغة الاستعلام عن البيانات","definition_en":"A high-level database management language with easy-to-use commands that allow users to retrieve, sort, order, and display data.","definition_ar":"لغة عالية المستوى لإدارة قاعدة البيانات مع أوامر سهلة في الاستخدام، تسمح للمستخدمين باستعادة، و فرز، و نسق، و عرض البيانات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":222,"en":"Data Visualization","ar":"عرض مرئي للبيانات","definition_en":"The graphical representation of data to help users understand the significance of the data.","definition_ar":"تمثيل جرافيكي للبيانات لمساعدة المستخدمين على فهم أهمية البيانات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":223,"en":"Data Warehouse","ar":"مستودع البيانات","definition_en":"A central repository for all or significant parts of the data that an organization’s business systems collect.","definition_ar":"خزين مركزي لجميع البيانات التي تُجمّعُها أنظمة الأعمال في الوحدة المنظمة أو جميع أجزاء البيانات ذات الأهمية.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":224,"en":"Database","ar":"قاعدة بيانات","definition_en":"A structured set of interrelated and centrally managed data files that are stored with minimum redundancy.","definition_ar":"مجموعة مهيكلة من ملفات لبيانات ذات علاقة متداخلة، تُدار مركزياً بأدنى إسراف في التخزين.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":225,"en":"Database Management","ar":"إدارة قاعد البيانات","definition_en":"The management of an organization’s data.","definition_ar":"إدارة البيانات لوحدة منظمة ما.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":226,"en":"Database Management System (DBMS)","ar":"نظام إدارة قاعدة البيانات (DBMS)","definition_en":"The program that manages and controls the data and interfaces between the data and the computer programs that use the data.","definition_ar":"برامج، تدير و تضبط البيانات و تَستوجِهُ بين البيانات و برامج الحاسوب التي تستخدم البيانات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":227,"en":"Days Purchases in Payables","ar":"أيام المشتريات في الحسابات الدائنة","definition_en":"A financial ratio measuring the portion of accounts payable that is current.","definition_ar":"نسبة مالية تقيس الجزئية الجارية من الحسابات الدائنة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":228,"en":"Days Sales in Inventory","ar":"أيام المبيعات كمخزون","definition_en":"A measure of the age or adequacy of inventory.","definition_ar":"قياس لعمر أو لكفاية المخزون.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":229,"en":"Days Sales in Receivables","ar":"أيام المبيعات في الحسابات المدينة","definition_en":"A measure of the average number of days a credit sale is outstanding. (Also called Days Sales Outstanding and Average Collection Period.)","definition_ar":"قياس لمتوسط عدد الأيام التي يكون فيها بيع الائتمان معلّق. (يسمى أيضاً أيام تعليق المبيعات و متوسط فترة التحصيل.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":230,"en":"Debt Ratio","ar":"نسبة الدين","definition_en":"A financial ratio used to measure the extent to which an entity utilizes debt. (Also called Debt to Total Assets Ratio.)","definition_ar":"نسبة مالية، تُستخدم في قياس مدى استنفاع الكيان من الديون. (يسمى أيضاً نسبة الديون إلى مجموع الأصول.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":231,"en":"Debt Security","ar":"ورقة مالية بالدين","definition_en":"A promise in writing to repay a debt. For example a bond, bill or note.","definition_ar":"وعد مكتوب على أن يتم دفع دين ما.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":232,"en":"Debt to Total Assets Ratio","ar":"نسبة الديون إلى مجموع الأصول","definition_en":"A financial ratio used to measure the extent to which an entity utilizes debt, expressed as total debt divided by total assets. (Also called Debt Ratio.)","definition_ar":"نسبة مالية، تُستخدم في قياس مدى استنفاع الكيان من الديون، و يُعبّر عنها كمجموع الديون مقسوماً على مجموع الأصول. (يسمى أيضاً نسبة الدين.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":233,"en":"Debt-to-Equity Ratio","ar":"نسبة الديون إلى حقوق الملكية","definition_en":"A measure of leverage, represented by total debt divided by equity.","definition_ar":"قياس للمديونية، تتمثل بمجموع الديون مقسوماً على حقوق الملكية.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":234,"en":"Decentralization","ar":"لامركزية","definition_en":"An organizational structure in which senior management maintains minimal control over individual operations and policies.","definition_ar":"هيكل تنظيمي، يحتفظ كبار الإداريين فيه بأدنى ضبط على العمليات والسياسات الفردية.","topic":"Performance Management","difficulty":"Intermediate"},{"id":235,"en":"Decision Tree","ar":"شجرة القرار","definition_en":"A diagram of possible alternatives and their expected consequences used to formulate possible courses of actions in order to make decisions.","definition_ar":"مخطط بياني للبدائل الممكنة مع العواقب المتوقعة منها، يُستخدم في صياغة مساقات العمل الممكنة من أجل صنع القرارات.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":236,"en":"Declining-Balance Method","ar":"طريقة الرصيد المتناقص","definition_en":"An accelerated depreciation method in which an asset’s net book value is multiplied by a constant depreciation rate resulting in higher depreciation charges in the early years of an asset’s life.","definition_ar":"طريقة اهتلاك متسارع، يُضرب بها صافي قيمة الدفتر للأصل بمعدل اهتلاك ثابت فينتج ثمن للاهتلاك عالٍ في السنوات الأولى من حياة الأصل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":237,"en":"Default Risk","ar":"مخاطر التقصير","definition_en":"The risk that a debtor may not be able to meet the terms of a loan.","definition_ar":"مخاطر من عدم قدرة المدين على تلبية أحكام القرض.","topic":"Risk Management","difficulty":"Intermediate"},{"id":238,"en":"Deferred","ar":"مؤجل","definition_en":"When an asset or liability is not realized as an expense or income until a future date.","definition_ar":"عندما لا تتحقق الأصول أو المطلوبات كمصاريف أو دخل حتى تاريخ مقبل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":239,"en":"Deferred Expenses","ar":"مصاريف مؤجلة","definition_en":"Expenditures not recognized in the period in which they were made. They are carried forward as assets that will become expenses in future periods. (Also called Deferred Charges.)","definition_ar":"نفقات لا يعترف بها في الفترة التي تمت فيها. إذ تُحمّل آجلًا كأصول ستصبح مصاريف في فترات مقبلة. (يسمى أيضاً رسوم مؤجلة.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":240,"en":"Deferred Income Taxes","ar":"ضريبة دخل مؤجلة","definition_en":"In general, the difference between the income tax expense recorded for financial accounting purposes and the amount of income tax paid.","definition_ar":"عامةً، هي الفرق بين مصاريف ضريبة الدخل المسجّلة لأغراض المحاسبة المالية ومبلغ ضريبة الدخل الذي دفع.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":241,"en":"Deferred Revenue","ar":"إيرادات مؤجلة","definition_en":"Generally, revenues received or recorded but not yet earned. (Also called Deferred Credit.)","definition_ar":"عموماً، هي إيراد مُستلم أو مُسجّل ولكنه لم يُجنى بعد. (ويسمى أيضاً ائتمان مؤجل)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":242,"en":"Deferred Tax Asset","ar":"أصول الضريبة المؤجلة","definition_en":"Under GAAP, the deferred tax benefits attributable to deductible temporary differences.","definition_ar":"بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، هي منافع الضريبة المؤجلة التي تعزى لفروقات مؤقتة قابلة للاستقطاع.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":243,"en":"Deferred Tax Liability","ar":"مطلوبات الضريبة المؤجلة","definition_en":"Under GAAP, the deferred tax effect attributable to taxable temporary differences, which represent the increase in taxable payable in future years.","definition_ar":"بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، هي آثار الضريبة المؤجلة التي تعزى لفروقات مؤقتة خاضعة للضريبة. تتمثل كزيادة في الحسابات الدائنة للضريبة في السنوات المقبلة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":244,"en":"Degree of Financial Leverage","ar":"درجة المديونية المالية","definition_en":"A financial ratio represented as the % change in net income divided by the % change in Earnings Before Interest and Taxes.","definition_ar":"نسبة مالية، تتمثل في % التغير في صافي الدخل مقسوماً على % التغير في المدخولات قبل الفوائد والضرائب.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":245,"en":"Degree of Operating Leverage","ar":"درجة المديونية التشغيلية","definition_en":"A financial ratio represented as the % change in Earnings Before Interest and Taxes divided by the % change in sales.","definition_ar":"نسبة مالية، تتمثل في % التغير في المدخولات قبل الفوائد والضرائب مقسوماً على % التغير في المبيعات.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":246,"en":"Delegation of Authority","ar":"تفويض السلطة","definition_en":"The assignment of authority and responsibility to another person to carry out specific activities.","definition_ar":"تكليف السلطة و المسؤولية لشخص آخر ليحمل على عاتقه أنشطة محددة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":247,"en":"Demand","ar":"طلب","definition_en":"The quantity of a commodity or service wanted at a specified price and time. Along with supply and other factors, a key determinant of price.","definition_ar":"كمية السلع أو الخدمات المطلوبة بسعر و وقت محدد. و إلى جانب العرض والعوامل الأخرى، هو محدد رئيسي للسعر.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":248,"en":"Deontology","ar":"غير الغائية","definition_en":"A moral philosophy that states that an action is morally good or not independent of the consequence, depends instead on a characteristic of the action itself, duty (as opposed to teleology.)","definition_ar":"فلسفة معنوية، يَرد فيها أن الأفعال معنوياً تكون مستقلة عن العواقب في كونها جيدة أم لا، و تتبع بدلًا لذلك خاصية الفعل ذاته، الواجب (مما يتعارض مع الغائية (teleology).)","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":249,"en":"Department","ar":"دائرة","definition_en":"A division or distinct section of an organization.","definition_ar":"قسم أو شعبة ذات معالم واضحة في الوحدة المنظمة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":250,"en":"Departmental Overhead","ar":"فوقية الدائرة","definition_en":"The total overhead costs incurred by a department.","definition_ar":"مجموع التكاليف الفوقية التي تتكبدها دائرة ما.","topic":"Cost Management","difficulty":"Intermediate"},{"id":251,"en":"Depletion","ar":"نفاذ","definition_en":"The process of allocating the cost of wasting assets (natural resources) to expense over the periods benefiting from the cost.","definition_ar":"عملية تخصيص تكلفة الأصول المهدورة (الموارد الطبيعية) كي تصبح مصاريف على الفترات التي انتفعت من التكلفة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":252,"en":"Depreciation","ar":"اهتلاك","definition_en":"The process of allocating the cost of tangible assets to operations over periods benefited (generally the expected life of the asset).","definition_ar":"عملية تخصيص تكلفة الأصول الملموسة على التشغيل، في الفترات التي يُنتفع فيها منها (عموماً هي العمر المتوقع للأصل).","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":253,"en":"Derivatives","ar":"مشتقات","definition_en":"A collective term for financial instruments whose prices are based on the price of another (underlying) investment (e.g., futures, options, warrants, and convertible securities).","definition_ar":"مصطلح جماعي لأدوات مالية ذات سعر أساسه سعر استثمار (مرتكز) آخر (مثل، العقود المقبلة، و الخيارات، و المذكرات، و الأوراق المالية القابلة للتحوّل).","topic":"Risk Management","difficulty":"Intermediate"},{"id":254,"en":"Descriptive Analytics","ar":"تحليل وصفي","definition_en":"Summary of historical data that describes what happened.","definition_ar":"ملخص لبيانات تاريخية تصف ما حدث.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":255,"en":"Detection Risk","ar":"مخاطر الاكتشاف","definition_en":"The risk that errors not detected or prevented by the control structure will also not be detected by the auditor.","definition_ar":"مخاطر عدم اكتشاف أو منع الأخطاء بهيكل الضوابط، و أيضا أن لا تُكتشف عن طريق المدقق.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":256,"en":"Diagnostic Analytics","ar":"تحليل تشخيصي","definition_en":"An examination of data to discover why something happened.","definition_ar":"اختبار البيانات لاكتشاف لماذا حدث شيء ما.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":257,"en":"Differential Cost","ar":"تكلفة تفاضلية","definition_en":"The difference in total cost between two alternatives. (Also called Incremental Cost).","definition_ar":"الفرق في مجموع التكاليف بين بديلين. (يسمى أيضاً التكلفة التزايدية).","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":258,"en":"Differentiation","ar":"تفاضل","definition_en":"The ability of a company to compete by producing a unique product.","definition_ar":"مقدرة الشركة على أن تتنافس بإنتاج منتج فريد.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":259,"en":"Diluted Earnings per Share","ar":"دخل مخفف لكل حصة","definition_en":"Earnings (net income) per share where “share” includes common stock, preferred stock, unexercised stock options, unexercised warrants, and some convertible debt.","definition_ar":"مدخولات (صافي دخل) كل حصة، و تشمل “الحصة” الأسهم العادية، و الأسهم الممتازة، و خيارات الأسهم غير الممارسة، و المذكرات غير الممارسة، و بعض الديون القابلة للتحوّل.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":260,"en":"Direct Cost","ar":"تكلفة مباشرة","definition_en":"A cost that is specifically identified with a single cost object.","definition_ar":"تكلفة، تُعرّف تحديداً لمادة تكلفة واحدة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":261,"en":"Direct Costing","ar":"احتساب التكاليف المباشرة","definition_en":"Method of inventory costing that includes all direct manufacturing costs and variable indirect manufacturing costs as inventory (fixed indirect manufacturing costs are excluded). (Also called Variable Costing.)","definition_ar":"طريقة لاحتساب تكاليف المخزون، تشمل جميع تكاليف التصنيع المباشرة وتكاليف التصنيع غير المباشرة المتغيرة للمخزون (تستبعد تكاليف التصنيع غير المباشرة الثابتة). (يسمى أيضاً احتساب التكاليف المتغيرة.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":262,"en":"Direct Foreign Investment","ar":"استثمار أجنبي مباشر","definition_en":"Overseas investment by multinational enterprises.","definition_ar":"استثمار عبر البحار من قبل مؤسسات (enterprise) متعددة الجنسيات.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":263,"en":"Direct Labor Cost","ar":"تكلفة العمل المباشرة","definition_en":"The compensation of all labor that can be identified with a cost object.","definition_ar":"تعويضات العمالة ككل، و يمكن أن تُعرّف لمادة التكلفة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":264,"en":"Direct Materials Cost","ar":"تكلفة المواد المباشرة","definition_en":"The acquisition cost of all materials that can be identified as part of the cost object.","definition_ar":"تكلفة استحواذ جميع المواد التي يمكن أن تعرّف كجزء من مادة التكلفة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":265,"en":"Direct Method","ar":"طريقة مباشرة","definition_en":"1. Method of allocating service department costs that ignores any services rendered by one service department to another, allocating each service department’s costs directly to the production departments. (Also called Direct Allocation Method.) 2. A method of preparing The Statement of Cash Flows where net cash flow from operating activities are reported as major classes of operating cash receipts and cash disbursements (as opposed to indirect method.)","definition_ar":"1. طريقة لتخصيص تكاليف دائرة الخدمات، تُتجاهل بها أية خدمات تقدمها دائرة الخدمات لدائرة خدمات أخرى، مع تخصيص كل تكاليف دائرة الخدمات على دوائر الإنتاج مباشرةً. (يسمى أيضاً طريقة التخصيص المباشر.) 2. أو هي طريقة لتحضير قائمة تدفقات النقد إذ بها يعد تقرير لصافي تدفق النقد من أنشطة التشغيل كتصنيفات تشغيل رئيسية لمقبوضات النقد و مصروفات النقد (مما يتعارض مع الطريقة غير المباشرة.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":266,"en":"Direct Write-off Method","ar":"طريقة الشطب المباشر","definition_en":"A method of accounting for bad debts in which they are expensed in the period in which they are identified as uncollectible.","definition_ar":"طريقة في المحاسبة للديون المعدومة، إذ تُقيّد كمصاريف في الفترة التي تُعرف فيها أنها غير قابلة للتحصيل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":267,"en":"Disaster Recovery","ar":"تغطية الكوارث","definition_en":"A procedure for storing an installation’s essential data in a secure location, and for recovering that data in the event of a catastrophic problem.","definition_ar":"إجراء لتخزين بيانات التثبيت الأساسية في موقع آمن، لتغطي تلك البيانات في حال حدوث مشكلة كارثية.","topic":"Risk Management","difficulty":"Intermediate"},{"id":268,"en":"Disbursement","ar":"صرف","definition_en":"The payment of cash.","definition_ar":"دُفعات النقد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":269,"en":"Disbursement Float","ar":"تعويم الصرف","definition_en":"The value of checks that an entity wrote that have not yet cleared the banking system and not yet deducted from the entity’s bank account. (Also called Payment Float.)","definition_ar":"قيمة الشيكات التي كتبها الكيان و لم تمر بعد في مقاصة نظام البنك و لم تستقطع بعد من حساب بنك الكيان. (يُسمى أيضاً تعويم الدفعات.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":270,"en":"Disclosure","ar":"إفصاح","definition_en":"An explanation or exhibit attached to a financial statement, or report.","definition_ar":"شرح أو إيضاح، يُرفق بقائمة مالية، أو تقرير.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":271,"en":"Discount","ar":"خصم","definition_en":"1. In the case of debt securities, the difference between the price paid by an investor and the face value. 2. In the case of products for sale, the difference between the price paid by a customer and the full price of the item.","definition_ar":"1. في حالة الأوراق المالية للديون، الفرق بين السعر الذي يدفعه المستثمر و القيمة الوُجهيّة. 2. في حالة منتجات البيع، هو الفرق بين السعر الذي يدفعه الزبون والسعر الكامل للبند.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":272,"en":"Discount Factor","ar":"عامل الخصم","definition_en":"The present value of one unit of currency that is expected to be received in future years.","definition_ar":"القيمة الحالية لوحدة واحدة من العملة والتي يُتوقع استلامها في سنوات مقبلة.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":273,"en":"Discount on Bonds Payable","ar":"خصم على الحسابات الدائنة للصكوك","definition_en":"The difference between the face value of the bonds and its selling price when the selling price is less than the face value.","definition_ar":"الفرق بين القيمة الوُجهيّة للصكوك و سعر بيعها عندما يكون سعر البيع أصغر من القيمة الوُجهيّة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":274,"en":"Discount Rate","ar":"معدل الخصم","definition_en":"The interest rate used to convert future cash flows to their present value.","definition_ar":"معدل فائدة، يُستخدم في تحوّل تدفقات النقد المقبلة إلى قيمتها الحالية.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":275,"en":"Discounted Cash Flow","ar":"تدفق النقد المخصوم","definition_en":"A method of evaluating future net cash flows by discounting them to their present value. The two methods most commonly used are Internal Rate of Return (IRR) and Net Present Value (NPV) methods.","definition_ar":"طريقة، يُقيّم بها صافي تدفقات النقد المقبلة بخصمها لقيمتها الحالية. والطريقتان الأكثر شيوعاً في الاستخدام هما طريقة معدل العائد الداخلي (IRR) و صافي القيمة الحالية (NPV).","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":276,"en":"Discounted Payback","ar":"استرجاع مخصوم","definition_en":"The amount of time expected to elapse before the discounted present value of cash inflows equals the discounted present value of the cash outflows.","definition_ar":"مقدار الوقت المتوقع انقضاؤه قبل أن تصبح القيمة الحالية المخصومة للتدفقات الواردة للنقد مساوية للقيمة الحالية المخصومة للتدفقات الصادرة للنقد.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":277,"en":"Discretionary Cost","ar":"تكلفة تَبصُّرية","definition_en":"A cost whose amount within a time period is governed by a management decision to incur the cost. (Also called Managed Cost or Programmed Cost.)","definition_ar":"تكلفة، يكون مبلغها محكوم بقرار من الإدارة لتَكبُّد تلك التكلفة ضمن حيز فترة زمنية. (يسمى أيضاً تكلفة مُدارة أو تكلفة مبرمجة.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":278,"en":"Diseconomies of Scale","ar":"تبذيرات التحجيم","definition_en":"Increases in average total costs occurring from an increase in the scale of production in the long run.","definition_ar":"زيادات على متوسط مجموع التكاليف ناجمة عن زيادة في تحجيم الإنتاج على المدى الطويل.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":279,"en":"Distributed Ledger","ar":"أستاذ مُوزّع","definition_en":"A database that is shared and synchronized within a network spread across multiple sites without a central administrator or centralized data storage (see blockchain.)","definition_ar":"قاعدة بيانات مشتركة و متزامنة ضمن حيز شبكة ذات انتشار يصل لعدة مواقع بدون مدير موارد رئيسي أو تخزين بيانات مركزي (أنظر سلسلة بلوك.)","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":280,"en":"Distribution","ar":"توزيع","definition_en":"The mechanism by which products or services are delivered to the customer.","definition_ar":"آلية، يتم بها توصيل المنتجات أو الخدمات إلى الزبون.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":281,"en":"Distribution Channels","ar":"قنوات التوزيع","definition_en":"A chain of intermediaries, each passing the product down the chain to the next organization, until it finally reaches the consumer or end-user (e.g., retailer, wholesaler, agent).","definition_ar":"سلسلة من الوسطاء، يُمرر كل منهم المنتج أسفل السلسلة إلى الوحدة المنظمة التالية، حتى يصل إلى المستهلك أو المستخدم النهائي (مثل، بائع التجزئة، أو بائع الجملة، أو الوكيل).","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":282,"en":"Diversification","ar":"تنويع","definition_en":"A technique used by an investor to reduce risk by distributing investment funds among a variety of asset classes; a strategy that implements expansion into new product lines, new customers, new geographic locations, new industries.","definition_ar":"تقنية، يستخدمها المستثمر ليخفّض المخاطر بتوزيع صناديق الاستثمار بين مختلف تصنيفات الأصول؛ إذ تُنفذ استراتيجية توسّع في خطوط المنتجات الجديدة، و الزبائن الجدد، و المواقع الجغرافية الجديدة، و الصناعات الجديدة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":283,"en":"Divestiture","ar":"تجريد","definition_en":"The sale of one or more of a company’s subsidiaries or divisions.","definition_ar":"بيع واحد أو أكثر من الشركات التابعة أو أقسام الشركة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":284,"en":"Dividend","ar":"توزيع أرباح","definition_en":"The distribution of part of a company’s earnings to shareholders.","definition_ar":"توزيع جزء من مدخولات الشركة على أصحاب الحصص.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":285,"en":"Dividend Declaration Date","ar":"تاريخ الإعلان عن توزيع الأرباح","definition_en":"The date on which the board of directors declares a dividend.","definition_ar":"التاريخ الذي يُعلن فيه مجلس الإدارة توزيع الأرباح.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":286,"en":"Dividend Discount Model","ar":"نموذج خصم توزيع الأرباح","definition_en":"A method used to place a value on a share of stock based on the net present value of the dividends that are expected to be received in the future. Expressed as D / (k – g), where D = the expected dividend per share, k = the expected rate of return, and g is the expected growth rate. (2 forms: constant growth model and two-stage model.)","definition_ar":"طريقة، تُستخدم في إعطاء قيمة لحصة من الأسهم على أساس صافي القيمة الحالية لتوزيع الأرباح المتوقع استلامه في المستقبل. و تُعبّر عنها المعادلة D / (k – g)، إذ D = توزيع الأرباح المتوقع لكل حصة، و k = معدل العائد المتوقع، و g = معدل النمو المتوقع. (بنموذجين: نموذج النمو الثابت، و نموذج ذو مرحلتين.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":287,"en":"Dividend Payout","ar":"دفع توزيع الأرباح","definition_en":"The amount of the dividend paid on a share of stock in a year.","definition_ar":"مبلغ توزيع الأرباح الذي دُفع لحصة من الأسهم في سنة واحدة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":288,"en":"Dividend Payout Ratio","ar":"نسبة دفع توزيع الأرباح","definition_en":"The annual dividend per share of stock as a proportion of Earnings per Share.","definition_ar":"توزيع الأرباح السنوي لكل حصة من الأسهم كنسبة و تناسب مع الدخل لكل حصة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":289,"en":"Dividend Yield","ar":"محصلة توزيع الأرباح","definition_en":"The annual dividend income per share received from a company as a proportion of the current market price per share.","definition_ar":"ما استُلم من شركة كدخل من توزيع الأرباح السنوي عن كل حصة واحدة و ذلك كنسبة و تناسب مع سعر السوق الحالي لكل حصة واحدة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":290,"en":"Dividends in Arrears","ar":"متأخرات توزيع الأرباح","definition_en":"Dividends owed to holders of cumulative preferred stock but not yet paid.","definition_ar":"ما يُستحق كتوزيع أرباح لحملة الأسهم الممتازة التراكمية و لكن لم يدفع بعد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":291,"en":"Downstream Costs","ar":"تكاليف نهائية","definition_en":"Costs incurred after a product is manufactured, including marketing, distribution & customer service.","definition_ar":"تكاليف، تُتكبد بعد تصنيع المنتج، و تشمل التسويق، و التوزيع، و خدمة الزبائن.","topic":"Cost Management","difficulty":"Intermediate"},{"id":292,"en":"Draft","ar":"حوالة","definition_en":"An instrument signed by a one person to another person requesting payment at a future time to a third party.","definition_ar":"أداة مالية، يُوقّعها شخص ما لشخص آخر يطلب فيها الدفع في وقت مقبل لطرف ثالث.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":293,"en":"Drum-Buffer-Rope System","ar":"نظام الطّبلة-المصد-الحبل","definition_en":"The Theory of Constraints production application, where drum refers to the constraint, buffer refers to the material release duration, and rope refers to the release timing. The aim is to protect the constraint in the system against process dependency and variation, maximizing the systems’ overall effectiveness.","definition_ar":"تطبيق لنظرية معيقات الإنتاج، إذ تُشير الطبلة إلى المعيقات، و يُشير المصد إلى أمد الإفراج عن المواد، و يُشير الحبل إلى توقيت الإفراج. و الهدف هو حماية المُعيق في النظام بالمقابل مع التبعية و التغير في العملية، مما يُعظّم من فاعلية الأنظمة ككل.","topic":"Cost Management","difficulty":"Intermediate"},{"id":294,"en":"Dual Allocation Method","ar":"طريقة التخصيص المزدوج","definition_en":"A method of allocating service department costs where cost are classified into two cost pools - a variable cost cost-pool & a fixed-cost cost- pool. Each of these pools uses a different cost- allocation base.","definition_ar":"طريقة لتخصيص تكاليف دائرة الخدمات، تُصنّف بها التكلفة إلى تجمُّعين من التكاليف – تجمُّع التكاليف للتكلفة المتغيرة، و تجمُّع التكاليف للتكلفة الثابتة. و يَستخدم كل من هذين التجمعين أساساً مختلفاً لتخصيص التكاليف.","topic":"Cost Management","difficulty":"Intermediate"},{"id":295,"en":"Dual-Rate Transfer Pricing","ar":"تسعير التحويل بمعدل مزدوج","definition_en":"A method where the transfer price is set at different levels for the supplying and receiving divisions of an organization.","definition_ar":"طريقة، يُحدد بها سعر التحويل بمستويات مختلفة لأقسام التوريد و الاستلام في الوحدة المنظمة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":296,"en":"Duration","ar":"أمد","definition_en":"A measure of the volatility of fixed income securities or of a portfolio of fixed income securities to changes in interest rates (i.e., the weighted average number of years until cash flows are received).","definition_ar":"قياس لتقلّب الأوراق المالية بدخل ثابت أو محفظة الأوراق المالية بدخل ثابت الناجم عن تغيرات في معدلات الفائدة (أي، متوسط عدد السنوات المرجح إلى أن يتم استلام تدفقات النقد).","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":297,"en":"Earnings","ar":"(Earnings) مدخولات","definition_en":"The excess of revenue over expenses for an accounting period. Sometimes used synonymously with net earnings, net income, or income.","definition_ar":"فائض الإيراد على المصاريف خلال فترة المحاسبة. و بعض الأحيان تُستخدم كمترادفات له صافي المدخولات، أو صافي الدخل (income)، أو الدخل (income).","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":298,"en":"Earnings at Risk","ar":"مدخولات عند المخاطر","definition_en":"A probabilistic estimate of the sensitivity of earnings; how forecasted earnings might be affected by changes in certain risk factors & other variables. Earnings Before Interest, Taxes, Depreciation, and Amortization (EBITDA) A metric used to evaluate profitability; it eliminates the effects of financing and accounting decisions.","definition_ar":"تقدير احتمالي لحساسية المدخولات، و كيف يمكن لمدخولات متوقّعة أن تؤثر فيها تغيرات معينة في عوامل المخاطر وغيرها من المتغيرات. مدخولات ما قبل الفوائد، و الضرائب، و الاهتلاك، و الإهلاك (EBITDA) نظام قياس، يُستخدم في تقييم الربحية، وهو يقضى على آثار قرارات التمويل والمحاسبة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":299,"en":"Earnings Distribution","ar":"توزيع المدخولات","definition_en":"A probabilistic distribution of earnings outcome such that one can estimate the probability of obtaining a certain level of earnings. Used in risk management.","definition_ar":"توزيع احتمالي لنتيجة المدخولات بحيث يمكن لأحد ما تقدير احتمالية الحصول على مستوى مدخولات معين. يُستخدم في إدارة المخاطر.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":300,"en":"Earnings Per Share (EPS)","ar":"دخل (مدخولات) لكل حصة (EPS)","definition_en":"Net income available to common shareholders on a per share basis.","definition_ar":"صافي الدخل المتاح لأصحاب الحصص العادية بأسس كل حصة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":301,"en":"Earnings Quality","ar":"النوعية للمدخولات","definition_en":"The extent that net income is a realistic portrayal of operating performance (i.e., that reported results have not been intentionally overstated or understated by management).","definition_ar":"مدى كون صافي الدخل بمثابة تصوير عقلاني لأداء التشغيل (أي، نتائج التقارير لم يُبالغ فيها أو يُبخس منها عمداً من قبل الإدارة).","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":302,"en":"Earnings Yield","ar":"محصلة المدخولات","definition_en":"Earnings per share for the most recent 12 months as a proportion of the current price per share.","definition_ar":"دخل لكل حصة في أحدث 12 شهراً و ذلك كنسبة و تناسب مع السعر الحالي لكل حصة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":303,"en":"Earnings-Based Valuation","ar":"تقدير القيمة على أساس المدخولات","definition_en":"Techniques used to value a share of stock or entity based on earnings expected to be generated by the item or entity. Generally involves present value models.","definition_ar":"تقنيات، تُستخدم في تقييم حصة من أسهم أو كيان على أساس المدخولات المتوقّع توليدها من البند أو الكيان. عموماً تتضمن نماذج القيمة الحالية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":304,"en":"Economic Order Quantity (EOQ)","ar":"كمية الطلبية الاقتصادية (EOQ)","definition_en":"The optimal amount of an item to order when inventory is reduced to the reorder point. (Also called Optimal Lot Size.)","definition_ar":"المبلغ الأمثل لطلبية بند ما عندما ينخفض المخزون منه إلى نقطة إعادة الطلبية. (يسمى أيضاً مقاس الرزمة الأمثل.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":305,"en":"Economic Profit","ar":"ربح الاقتصاد","definition_en":"A return to investors that exceeds the opportunity cost of financial capital.","definition_ar":"عائد المستثمرين الذي يتجاوز تكلفة الفرصة لرأس المال المالي.","topic":"Performance Management","difficulty":"Intermediate"},{"id":306,"en":"Economies of Scale","ar":"توفيرات التحجيم","definition_en":"Reduction in an entity’s per unit cost associated with production processes that produce large volumes of output.","definition_ar":"تخفيض في تكلفة كل وحدة في الكيان، يكون مرتبط بعمليات الإنتاج التي تنتج المخرجات بكميات كبيرة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":307,"en":"Effective Interest Rate","ar":"معدل الفائدة ذو الفاعلية","definition_en":"The internal rate of return or yield to maturity of a bond at the time of issue.","definition_ar":"معدل العائد الداخلي (IRR) أو المحصلة إلي استحقاق الصك عند وقت الإصدار.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":308,"en":"Efficiency (Usage) Variances","ar":"انحراف (الاستخدام) الفعالية","definition_en":"The difference between the actual quantity of input used and the budgeted quantity of input, multiplied by the budgeted price.","definition_ar":"الفرق بين الكمية الفعلية للمدخلات المستخدمة و كمية الموازنة للمدخلات، مضروباً في سعر الموازنة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":309,"en":"Efficient Market Hypothesis","ar":"فرضية فعالية السوق","definition_en":"The hypothesis that security prices always fully reflect all publicly available information concerning traded securities.","definition_ar":"فرضية أن أسعار الأوراق المالية دائما تعكس المعلومات المتاحة علانية تماماً و التي تخص الأوراق المالية المتداولة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":310,"en":"Elasticity","ar":"مرونة","definition_en":"A measure of the degree to which a price change for an item results in a unit change in supply or a unit change in demand.","definition_ar":"قياس للدرجة، يؤدي فيها تغير سعر بند ما إلى تغير في وحدات العرض أو تغير في وحدات الطلب.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":311,"en":"Elasticity of Demand","ar":"مرونة الطلب","definition_en":"A measure of consumer response to a change in the price of a product or service. Calculated as the percent change in quantity demanded divided by a percent change in price.Depending on the response, the product or service is called either elastic or inelastic.","definition_ar":"قياس لاستجابة المستهلك لتغيرٍ في سعر منتج أو خدمة ما. و تحتسب كنسبة مئوية للتغير في الكمية المطلوبة مقسوماً على النسبة المئوية للتغير في السعر. و تبعاً للاستجابة، يسمى المنتج أو الخدمة إما ذي مرونة أو بدون مرونة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":312,"en":"Encryption","ar":"تشفير","definition_en":"A procedure that transforms information, using an algorithm, to make it unreadable to anyone who does not have the key to decode the message.","definition_ar":"إجراء لتناقل المعلومات، باستخدام خوارزمية، لجعلها غير مقروءة لأي شخص لا يمتلك المفتاح لفك شفرة الرسالة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":313,"en":"Enterprise Performance Management (EPM)","ar":"إدارة أداء المؤسسة (EPM)","definition_en":"Business planning system that involves evaluating and managing performance for an enterprise to reach performance goals and enhance efficiency. (Also known as Corporate Performance (CPM) or Business Performance Management (BPM)).","definition_ar":"نظام لتخطيط الأعمال، يتضمن تقييم و إدارة أداء المؤسسة (enterprise) لبلوغ أهداف الأداء و تعزيز الفعالية. (معروف أيضا باسم أداء الشركات (CPM) أو إدارة أداء الأعمال (BPM)).","topic":"Performance Management","difficulty":"Intermediate"},{"id":314,"en":"Enterprise Performance Management System (EPM)","ar":"نظام إدارة أداء المؤسسة (EPM)","definition_en":"Business planning system that involves evaluating and managing performance for an enterprise to reach performance goals and enhance efficiency. (Also known as Corporate Performance Management (CPM) or Business Performance Management (BPM).)","definition_ar":"نظام لتخطيط الأعمال، يتضمن تقييم و إدارة أداء المؤسسة (enterpise) لبلوغ أهداف الأداء و تعزيز الفعالية. (يُعرف أيضاً بإدارة أداء الشركات العامة (CPM) أو إدارة أداء الأعمال (BPM).)","topic":"Performance Management","difficulty":"Intermediate"},{"id":315,"en":"Enterprise Resource Planning System (ERP)","ar":"نظام تخطيط موارد المؤسسة (ERP)","definition_en":"A system that integrates all facets of an organization’s activities, including accounting, finance, manufacturing, inventory management, marketing, and human resources.","definition_ar":"نظام، يعمل على تكامل جميع أوجه الأنشطة لوحدة منظمة، يشمل المحاسبة، و المالية، و التصنيع، و إدارة المخزون، و التسويق، و الموارد البشرية.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":316,"en":"Enterprise Risk Management (ERM)","ar":"إدارة مخاطر المؤسسة (ERM)","definition_en":"A process applied across the enterprise designed to 1. Identify potential events that, if they occur, could negatively impact the enterprise; and 2. Manage this risk to provide reasonable assurance to management and the Board of Directors.","definition_ar":"عملية، تُطبّق على امتداد المؤسسة (enterprise) و تُصمم من أجل 1. تعريف الأحداث ذات الإمكانية، التي إذا حدثت، لها أثراً سلبياً على المؤسسة (enterprise)؛ و 2. إدارة هذه المخاطر هو لتوفير تأكيد معقول للإدارة ومجلس الإدارة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":317,"en":"Enterprise-Wide","ar":"على اتساع المؤسسة (Enterprise)","definition_en":"Used to describe systems and processes in use throughout an organization.","definition_ar":"يستخدم في وصف الأنظمة و العمليات المستخدمة في كافة أرجاء الوحدة المنظمة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":318,"en":"Entity","ar":"كيان","definition_en":"A person, partnership, corporation, or other separate identifiable unit.","definition_ar":"قد يكون شخص، أو شراكة، أو شركة عامة، أو وحدة أخرى منفصلة و قابلة للتعريف.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":319,"en":"Equilibrium","ar":"اتّزان","definition_en":"In economics the state of a market for a product or service where there is a balance of supply & demand","definition_ar":"في الاقتصاد هو حالة السوق لمنتج أو خدمة، يكون فيها توازن بين العرض و الطلب","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":320,"en":"Equity","ar":"حقوق الملكية","definition_en":"The residual amount after deducting an entity’s liabilities from its assets. The amount that shareholders own in a corporation.","definition_ar":"المبلغ المتبقي بعد استقطاع المطلوبات من الأصول للكيان. و هو المبلغ الذي يمتلكه أصحاب الحصص في شركة عامة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":321,"en":"Equity Carve-Out","ar":"انشقاق حقوق الملكية","definition_en":"When a parent company sells a minority (usually 20% or less) stake in a subsidiary for an IPO. (Also called partial spin-off.)","definition_ar":"عندما تبيع الشركة الأم حصة الأقلية (عادةً 20% أو أقل) في شركة تابعة لها من أجل الطرح العام الأولي (IPO). (يسمى أيضاً انبثاق جزئي (partial spin-off).)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":322,"en":"Equity Multiplier","ar":"مضاعف حقوق الملكية","definition_en":"Total assets as a proportion of common equity. (Also called Financial Leverage Ratio.)","definition_ar":"مجموع الأصول كنسبة و تناسب مع حقوق الملكية العادية. (يسمى أيضاً نسبة المديونية المالية.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":323,"en":"Equivalent Units","ar":"وحدات معادلة","definition_en":"A measure of the physical quantities of inputs necessary to produce output of 1 fully complete unit.","definition_ar":"قياس للكميات العينية من المدخلات اللازمة لإنتاج مخرج واحد لوحدة مكتملة تماماً.","topic":"Cost Management","difficulty":"Intermediate"},{"id":324,"en":"Ethics Code","ar":"دليل قواعد الأخلاقيات","definition_en":"A list of principles and/or standards governing the conduct of individuals within an organization.","definition_ar":"قائمة المبادئ و/أو المعايير لحوكمة تصرفات الأفراد ضمن حيز الوحدة المنظمة.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":325,"en":"Ethics Help-Line","ar":"خط المساعدة في الأخلاقيات","definition_en":"A resource for obtaining guidance on ethical dilemmas; generally in the form of an exclusive telephone number that connects to an ethics counselor.","definition_ar":"مورد للحصول على إرشاد في الإشكاليات الأخلاقية؛ وهو عموماً على شكل رقم هاتف حصري للتواصل مع مستشار في الأخلاقيات.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":326,"en":"Eurodollars","ar":"يورودولارز","definition_en":"Deposits denominated in U.S. Dollars at financial institutions outside the United States.","definition_ar":"ودائع قوامها الدولار الأمريكي في مؤسسات (institution) مالية خارج الولايات المتحدة الأمريكية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":327,"en":"Exception Reporting","ar":"إعداد تقرير الاستثناءات","definition_en":"Reporting that alerts management by focusing on significant deviations from planned performance.","definition_ar":"إعداد تقرير، يُنبّه الإدارة للتركيز على الانحرافات عن الأداء المخطط له، ذات الأهمية.","topic":"Performance Management","difficulty":"Intermediate"},{"id":328,"en":"Exchange Rate","ar":"سعر الصرف","definition_en":"The price of one country’s currency in terms of another country’s currency.","definition_ar":"سعر عملة إحدى الدول بأحكام عملة دولة أخرى.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":329,"en":"Exchange Rate Risk","ar":"مخاطر سعر الصرف","definition_en":"The risk that the value of a cash flow will decline due to a change in exchange rates.","definition_ar":"مخاطر تراجع قيمة تدفق النقد جرّاء تغير في أسعار الصرف.","topic":"Risk Management","difficulty":"Intermediate"},{"id":330,"en":"Exercise Price","ar":"سعر الممارسة","definition_en":"Price at which a call option or put option may be exercised (carrying out terms of agreement). (Also called Strike Price.)","definition_ar":"سعر، يمكن عنده ممارسة خيار الشراء أو خيار البيع (اضطلاعاً بأحكام الاتفاق). (يسمى أيضاً سعر التنفيذ (Strike Price).)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":331,"en":"Expected Value","ar":"قيمة متوقعة","definition_en":"The weighted average of the outcomes of an action, in which the values of the possible outcomes are weighted by their probabilities.","definition_ar":"متوسط مرجّح لنتائج الأفعال، تكون فيه قيم النتائج الممكنة مرجحة حسب احتمالاتها.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":332,"en":"Expenditure","ar":"إنفاق","definition_en":"Payment for goods or services received that may be made at either the time the goods or services are received or a later time.","definition_ar":"دفعات على البضاعة أو الخدمات التي استلمت، يمكن عملها سواءاً في وقت الحصول على البضاعة أو الخدمات أو في وقت لاحق.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":333,"en":"Expense","ar":"مصاريف","definition_en":"Cost of goods and services used in the current accounting period.","definition_ar":"تكلفة البضاعة و الخدمات المستخدمة في فترة المحاسبة الحالية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":334,"en":"Expense Recognition","ar":"اعتراف بالمصاريف","definition_en":"The recording in the accounting system of a cost.","definition_ar":"تسجيل التكلفة في نظام المحاسبة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":335,"en":"Expropriation Risk","ar":"مخاطر المصادرة","definition_en":"The risk of a foreign government seizing the private property of a company.","definition_ar":"مخاطر حجز حكومة أجنبية لممتلكات خاصة بالشركة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":336,"en":"External Factors","ar":"عوامل خارجية","definition_en":"Factors beyond the control of an entity that influence overall economic conditions or the market for its product.","definition_ar":"عوامل من بعد ضوابط الكيان، تؤثر على حالته الاقتصادية ككل أو على سوق منتجاته.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":337,"en":"External Failure Costs","ar":"تكاليف الفشل الخارجي","definition_en":"Costs that an entity incurs when it detects nonconforming products or services after delivering them to customers (e.g., warranty repairs and product liability).","definition_ar":"تكاليف، يتكبّدها الكيان عندما يكتشف أن المنتجات أو الخدمات غير مطابقة بعد توصيلها للزبائن (مثل، التصليحات على الضمانة و مسؤولية الإنتاج).","topic":"Cost Management","difficulty":"Intermediate"},{"id":338,"en":"External Financial Reporting","ar":"إعداد تقرير مالي خارجي","definition_en":"The reporting of financial information focused on an external audience (lenders, investors, and the general public).","definition_ar":"إعداد تقارير بمعلومات مالية تُرّكز على الجمهور الخارجي (مقرضون، و مستثمرون، وعامة الناس عموماً).","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":339,"en":"Extraordinary Items","ar":"بنود استثنائية","definition_en":"Under GAAP, events that are unusual in nature and infrequent in occurrence.","definition_ar":"بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، أحداث غير معتادة بطبيعتها و غير متكررة الحدوث.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":340,"en":"Factoring","ar":"بيع الديون","definition_en":"The sale of accounts receivable at a discount to a factor (usually a financial institution). The financial institution then collects the accounts from the customer.","definition_ar":"بيع الحسابات المدينة بخصم إلى عامل وسيط (عادة مؤسسة (institution) مالية). بعد ذلك تحصّل المؤسسة (institution) المالية الحسابات من الزبون.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":341,"en":"Factory Overhead","ar":"فوقية المصنع","definition_en":"All manufacturing costs except direct materials and direct labor.","definition_ar":"جميع تكاليف التصنيع عدا المواد المباشرة و العمالة المباشرة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":342,"en":"Fair Market Value","ar":"قيمة السوق العادلة","definition_en":"The exchange price that would prevail for a good or service traded in an active market consisting of a large number of well-informed buyers and sellers dealing at arm’s length.","definition_ar":"سعر استبدال سائد لبضاعة أو خدمة متداولة في سوق مُفعّل، يتكوّن من عدد كبير من المشترين و البائعين من ذوي حسن الاطلاع الذين يعقدون صفقاتهم بندية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":343,"en":"Fair Value Method","ar":"طريقة القيمة العادلة","definition_en":"A method used to value an entity’s investments in marketable securities. If the carrying value of marketable securities falls below the Fair Market Value, then the value of the security should be reduced to the Fair Market Value.","definition_ar":"طريقة، تُستخدم في تقييم استثمارات الكيان في أوراق مالية بقابلية السوق. و إذا كانت القيمة المحملة على الأوراق المالية بقابلية السوق أقل من قيمة السوق العادلة، حينها ينبغي تخفيض قيمة الأوراق المالية إلى قيمة السوق العادلة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":344,"en":"Favorable Budget Variance","ar":"انحراف موازنة مواتي","definition_en":"A variance arising when actual or current performance exceeds expected performance.","definition_ar":"انحراف، ينجم عندما يتجاوز الأداء الفعلي أو الحالي الأداء المتوقع.","topic":"Performance Management","difficulty":"Intermediate"},{"id":345,"en":"Feedback","ar":"تعقيب","definition_en":"The process of informing users of information about how actual performance compares with the expected or desired level of performance.","definition_ar":"عملية إطلاع مستخدمي المعلومات على كيف يقارن الأداء الفعلي مع مستوى الأداء المتوقع أو المرغوب.","topic":"Performance Management","difficulty":"Intermediate"},{"id":346,"en":"Fiduciary","ar":"مُستأمن","definition_en":"A person who hold a legal or moral relationship of trust with one or more other persons, often taking care of another’s assets on their behalf.","definition_ar":"شخص ما لديه قانونياً أو معنوياً علاقة أمانة بشخص آخر أو أكثر، و هو يعتني مراراً بأصول الآخرين بالنيابة عنهم.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":347,"en":"Financial Accounting","ar":"محاسبة مالية","definition_en":"The accounting for assets, equities, revenues and expenses of an entity; primarily concerned with the historical reporting to external users of the financial position and operations of the entity on a regular periodic basis.","definition_ar":"محاسبة الأصول، و حقوق الملكية، و الإيرادات، و المصاريف لكيان؛ تخص في المقام الأول إعداد تقارير تاريخية للمستخدمين الخارجيين عن المركز المالي و عمليات الكيان بأسس دورية منتظمة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":348,"en":"Financial Accounting Standards Board (FASB)","ar":"مجلس معايير المحاسبة المالية (FASB)","definition_en":"An independent board consisting of seven members responsible for establishing generally accepted accounting principles for the U.S.","definition_ar":"مجلس مستقل، يتكوّن من سبعة أعضاء مسؤولين عن تأسيس مبادئ المحاسبة المقبولة عموماً في الولايات المتحدة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":349,"en":"Financial Budget","ar":"موازنة مالية","definition_en":"The part of the Master Budget that includes the Capital Budget, Cash Budget, Budgeted Balance Sheet, and Budgeted Statement of Cash Flows.","definition_ar":"جزء من الموازنة الرئيسية، تشمل موازنة رأس المال، و موازنة النقد، و موازنة الميزانية العمومية، و موازنة قائمة تدفقات النقد.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":350,"en":"Financial Instrument","ar":"أداة مالية","definition_en":"An instrument having monetary value (e.g., bond).","definition_ar":"أداة لها قيمة النقد (مثل، الصك).","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":351,"en":"Financial Leverage","ar":"مديونية مالية","definition_en":"The extent to which the assets of an entity are financed with debt.","definition_ar":"مدى تمويل أصول الكيان بالدين.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":352,"en":"Financial Leverage Ratio","ar":"نسبة المديونية المالية","definition_en":"Total assets as a proportion of total common equity, which measures the extent of financial leverage.","definition_ar":"مجموع الأصول كنسبة و تناسب مع مجموع حقوق الملكية العادية، مما يقيس مدى المديونية المالية.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":353,"en":"Financial Reporting","ar":"إعداد التقارير المالية","definition_en":"Presentation of financial information indicating an entity’s financial position, operating performance, and funds flow for an accounting period.","definition_ar":"تقديم معلومات مالية عن الكيان كمؤشر عن المركز المالي، و أداء التشغيل، و تدفق الأموال في فترة المحاسبة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":354,"en":"Financial Statement","ar":"قوائم مالية","definition_en":"A report containing financial information about an organization, including the Balance Sheet (or Statement of Financial Position), Income Statement, and Cash Flow Statement.","definition_ar":"تقارير، تحتوي على معلومات مالية عن الوحدة المنظمة، تشمل الميزانية العمومية (أو قائمة المركز المالي)، و قائمة الدخل، و قائمة تدفق النقد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":355,"en":"Financing Expenses","ar":"مصاريف التمويل","definition_en":"Expenses incurred by an entity in order to issue debt or equity securities.","definition_ar":"مصاريف، يتكبّدها الكيان من أجل إصدار أوراق مالية كدين أو كحقوق ملكية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":356,"en":"Finished Goods Inventories","ar":"مخزون البضاعة التامة","definition_en":"The part of inventory that accounts for the completed product, ready for sale or other disposition.","definition_ar":"جزء من المخزون، يُحاسب كمنتج مكتمل، أو جاهز للبيع، أو غيرها من أوجه التخلص منه.","topic":"Cost Management","difficulty":"Intermediate"},{"id":357,"en":"Firewall","ar":"جدار ناري","definition_en":"A network configuration (usually both computer hardware and software) that prevents unauthorized traffic into and out of a secure network.","definition_ar":"تكوين الشبكة (عادةً يكون من أجهزة و برمجيات الحاسوب) الذي يمنع المرور الغير المصرح به من و إلى شبكة آمنة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":358,"en":"Firm","ar":"منشأة","definition_en":"A business entity, such as a corporation","definition_ar":"كيان للأعمال، كشركة عامة","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":359,"en":"First-In-First-Out (FIFO)","ar":"الوارد أولًا يصرف أولًا (FIFO)","definition_en":"A method of inventory valuation and cost flow assumption, where the ending inventory cost is computed from the most recent purchases and the cost of goods sold is computed from the oldest purchases, including beginning inventory.","definition_ar":"طريقة لتقدير قيمة المخزون و افتراض تدفق التكلفة، تُحسب بها تكلفة مخزون آخر المدة من أحدث المشتريات و تُحسب تكلفة البضاعة المباعة من أقدم المشتريات، كما تشمل مخزون أول المدة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":360,"en":"Fiscal Year","ar":"سنة مالية","definition_en":"Any accounting period of 12 successive calendar months (or 52 weeks, or 365 days), used by an entity for financial reporting.","definition_ar":"أي فترة محاسبة قوامها 12 شهراً متتالياً في الرزنامة (أو 52 أسبوعاً، أو 365 يوماً)، تُستخدم من قبل الكيان لإعداد التقارير المالية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":361,"en":"Fixed Asset","ar":"أصل ثابت","definition_en":"A noncurrent, nonmonetary, tangible asset used in the normal operations of a business.","definition_ar":"أصل ملموس، و غير نقدي، و غير جاري يُستخدم في عمليات الأعمال العادية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":362,"en":"Fixed Asset Turnover","ar":"دوران الأصول الثابتة","definition_en":"Measures an entity’s ability to generate sales from fixed assets. It relates sales to net property, plant, and equipment.","definition_ar":"يقيس مقدرة الكيان على توليد المبيعات من الأصول الثابتة. بعمل علاقة بين المبيعات و الصافي من الممتلكات، و المعمل، و المعدات.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":363,"en":"Fixed Budget","ar":"موازنة ثابتة","definition_en":"A budget with fixed and unchangeable amounts of revenues and expenses. (Also called a static budget.)","definition_ar":"موازنة بمبالغ ثابتة و غير قابلة للتغير من الإيرادات و المصاريف. (يسمى أيضاً موازنة ساكنة (Static Budget).)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":364,"en":"Fixed Charge Coverage Ratio","ar":"نسبة تغطية الرسوم الثابتة","definition_en":"A leverage ratio, represented as earnings before fixed charges and taxes divided by fixed charges. Fixed charges include interest, required principal repayments, and leases.","definition_ar":"نسبة المديونية، تتمثل في المدخولات ما قبل الرسوم الثابتة و الضرائب مقسوماً على الرسوم الثابتة. و تشمل الرسوم الثابتة الفوائد، و متطلبات إتمام دفعات أصل الدين، و الإيجارات.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":365,"en":"Fixed Charges","ar":"رسوم ثابتة","definition_en":"Fixed financial costs such as interest payments and lease (rent) payments.","definition_ar":"تكاليف مالية ثابتة كدفعات الفوائد و دفعات الإيجار (الاستئجار).","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":366,"en":"Fixed Cost","ar":"تكلفة ثابتة","definition_en":"A cost that does not vary with the volume of activity in the short term. (Also called Nonvariable Cost or Constant Cost.)","definition_ar":"تكلفة لا تتغير بتغير حجم النشاط في مدة قصير. (يسمى أيضاً التكلفة غير القابلة للتغيير أو التكلفة الثابتة (Constant Cost).)","topic":"Cost Management","difficulty":"Intermediate"},{"id":367,"en":"Fixed Exchange Rate","ar":"سعر الصرف الثابت","definition_en":"A monetary system in which a country’s currency is set at a fixed rate relative to other currencies.","definition_ar":"نظام النقد، يوضع به معدل ثابت لعملة دولة ما بالنسبة إلى العملات الأخرى.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":368,"en":"Fixed Overhead","ar":"فوقية ثابتة","definition_en":"Overhead costs that do not vary with the level of output.","definition_ar":"تكاليف فوقية، لا تتغير بتغير مستوى المخرجات","topic":"Cost Management","difficulty":"Intermediate"},{"id":369,"en":"Fixed Overhead Spending Variance","ar":"انحراف إنفاق الفوقية الثابتة","definition_en":"The difference between the fixed overhead incurred and the fixed overhead budgeted.","definition_ar":"الفرق بين الفوقية الثابتة المتكبدة و الفوقية الثابتة في الموازنة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":370,"en":"Flexible Budget","ar":"موازنة مرنة","definition_en":"A budget in which the budgeted amounts may be adjusted to any activity level.","definition_ar":"موازنة، يُمكن بها تسوية مبالغ الموازنة إلي أي مستوى من النشاط.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":371,"en":"Flexible Exchange Rate","ar":"سعر الصرف المرن","definition_en":"An exchange rate for a country’s currency that is determined by the market forces of supply and demand. (Also called Floating Exchange Rate.)","definition_ar":"سعر صرف عملة دولة ما، يُحدد بقوى السوق في العرض و الطلب. (يسمى أيضاً تعويم سعر الصرف.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":372,"en":"Floating Exchange Rate","ar":"تعويم سعر الصرف","definition_en":"An exchange rate for a country’s currency that is determined by the market forces of supply & demand. Also referred to as a Flexible Exchange Rate.","definition_ar":"سعر صرف عملة دولة ما، يُحدد بقوى السوق في العرض و الطلب. أيضاً يُشار إليه بسعر الصرف المرن.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":373,"en":"Flowchart","ar":"مخطط انسيابي","definition_en":"A graphical representation of the flow of information in which symbols are used to represent operations, data, reports generated, equipment, etc.","definition_ar":"تمثيل جرافيكي لتدفق المعلومات، تُستخدم فيه رموز لتمثيل العمليات، و البيانات، و التقارير المتولّدة، و المعدات، و الخ.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":374,"en":"FOB (free on board) Destination","ar":"(FOB Destination) تسليم عند الوجهة","definition_en":"The seller pays the shipping costs. Title passes to the buyer upon receipt of the goods.","definition_ar":"يدفع البائع تكاليف الشحن. و يُنقل حق ملكية البضاعة إلى المشتري عند استلامها.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":375,"en":"FOB (free on board) Shipping Point","ar":"(FOB Shipping Point) تسليم عند نقطة الشحن","definition_en":"The buyer pays the shipping costs. Title passes to the buyer when the goods are shipped.","definition_ar":"يدفع المشتري تكاليف الشحن. و يُنقل حق ملكية البضاعة إلى المشتري عندما تشحن البضاعة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":376,"en":"Forecast","ar":"توقّعات","definition_en":"A projection of the expected financial position, results of operations, and cash flows based on expected conditions in the future.","definition_ar":"عرض تصورات متوقعة للمركز المالي، و نتائج التشغيل، و تدفقات النقد على أساس الحالات المتوقعة في المستقبل.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":377,"en":"Foreign Corrupt Practices Act","ar":"قانون ممارسات الفساد الأجنبي","definition_en":"A U.S. federal law requiring any company having publicly-traded stock to maintain records that accurately and fairly represent the company’s transactions, and have an adequate system of internal accounting controls. Enacted with the intent to bring an end to bribery of foreign officials.","definition_ar":"قانون اتحادي في الولايات المتحدة، يَتطلب من أي شركة ذات أسهم للتداول العام حفظ سجلاتها التي تمثل معاملات الشركة بدقة و إنصاف، وأن يكون لديها نظام كاف لضوابط المحاسبة الداخلية. سُنّ بنية وضع نهاية لرشوة الموظفين الأجانب.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":378,"en":"Foreign Exchange","ar":"الصرف الأجنبي","definition_en":"Financial instruments, such as paper currency, notes, and checks, used to make payments between countries.","definition_ar":"أدوات مالية، كالعملة الورقية، و الإشعارات، و الشيكات، تُستخدم للوفاء بالدفعات بين الدول.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":379,"en":"Forfaiting","ar":"شراء مستندات التصدير","definition_en":"A form of finance where a third party purchases trade receivables from an exporter at a discount, and then collects from the importer the payment using the shipped goods as collateral.","definition_ar":"شكل من أشكال التمويل، يشتري به طرف ثالث حسابات مدينة تجارية من المصدّر بخصم، بعد ذلك يحصّل الدفعة من المستورد باستخدام البضاعة المشحونة كضمان تبعي.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":380,"en":"Forward Contract","ar":"عقد آجل","definition_en":"A non-standardized cash market transaction in which the delivery of the commodity is deferred until after the contract has been made.","definition_ar":"معاملة غير معيارية في سوق النقد، يُؤجّل فيها توصيل السلعة حتى ما بعد إبرام العقد.","topic":"Risk Management","difficulty":"Intermediate"},{"id":381,"en":"Forward Delivery","ar":"توصيل آجل","definition_en":"A transaction in which the settlement will occur on a specified date in the future at a price agreed upon on the trade date. (Also called Forward Trade.)","definition_ar":"معاملة، سيحدث فيها السداد في تاريخ محدد في المستقبل و بسعر متفق عليه في تاريخ التداول. (يسمى أيضاً تداول آجل.)","topic":"Risk Management","difficulty":"Intermediate"},{"id":382,"en":"Forward Market","ar":"سوق آجل","definition_en":"A market in which participants agree to trade some commodity, security, or foreign exchange at a fixed price for future delivery.","definition_ar":"سوق، يتفق فيه المشاركون على المتاجرة ببعض السلع، أو الأوراق المالية، أو الصرف الأجنبي بسعر ثابت مقابل التوصيل في المستقبل.","topic":"Risk Management","difficulty":"Intermediate"},{"id":383,"en":"Franchise","ar":"امتياز","definition_en":"A license granted by one entity (franchisor) to another entity (franchisee), entitling the franchisee to produce or market a product or service in a specific area, for a specific time.","definition_ar":"ترخيص، يُمنح من أحد الكيانات (مانح الامتياز) إلى كيان آخر (صاحب الامتياز)، فيصبح صاحب الامتياز ذي أحقية في إنتاج أو تسويق منتج أو خدمة ما في منطقة محددة، و لفترة محددة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":384,"en":"Fraud Triangle","ar":"مثلث الاحتيال","definition_en":"A model for explaining the factors that cause someone to commit occupational fraud. It consists of three components (opportunity, pressure, and rationalization).","definition_ar":"نموذج، يشرح العوامل التي بسببها يرتكب الشخص الاحتيال الوظيفي. يتكوّن من ثلاثة مكوّنات (الفرصة، و الضغط، و التبرير).","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":385,"en":"Fraudulent","ar":"احتيال","definition_en":"Intentional perversion of truth in order to induce another to part with something of value or to surrender a legal right.","definition_ar":"تحريف متعمد للحقيقة من أجل حض طرف آخر للتخلي عن شيء ذي قيمة أو للتنازل عن حق قانوني.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":386,"en":"Fringe Benefit","ar":"منافع إضافية","definition_en":"Non-wage forms of compensation, including pensions and health insurance, provided to an employee in addition to monetary compensation.","definition_ar":"شكل من أشكال التعويضات غير الأجور، يشمل المعاشات، و التأمين الصحي، و ما يُوفّر للموظف بالإضافة إلى تعويضات النقد.","topic":"Performance Management","difficulty":"Intermediate"},{"id":387,"en":"Full Cost","ar":"تكلفة كاملة","definition_en":"The sum of all the costs in all the business functions.","definition_ar":"حاصل جمع كل التكاليف من كل مسارات العمل في الأعمال.","topic":"Cost Management","difficulty":"Intermediate"},{"id":388,"en":"Full-Disclosure Principle","ar":"مبدأ الإفصاح التام","definition_en":"The principle that requires companies to disclose any circumstances and events that would make a difference to the users of the statements.","definition_ar":"مبدأ، يَتطلب من الشركات الإفصاح عن أي ظروف أو أحداث من شأنها أن تُحدث فرقاً لدى مستخدمي القوائم.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":389,"en":"Function","ar":"مسار عمل","definition_en":"The general end or purpose to be accomplished by an organizational unit, such as administration, selling, or research. It can also be a group of related activities serving a common end.","definition_ar":"ما سيتم كخاتمة أو غرض عام من قبل وحدة تنظيمية، كإدارة الموارد، أو المبيعات، أو البحوث. أيضاً يمكن أن تكون عبارة عن مجموعة من الأنشطة ذات العلاقة التي تخدم خاتمة مشتركة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":390,"en":"Functional Currency","ar":"عملة وظيفية","definition_en":"The currency of the primary economic environment in which the entity operates.","definition_ar":"عملة البيئة الاقتصادية الرئيسية التي فيها يشتغل الكيان.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":391,"en":"Future","ar":"عقد مقبل","definition_en":"A legal agreement to make or take delivery of a specified instrument at a fixed future date at a price determined at the time of dealing.","definition_ar":"اتفاق قانوني لعمل أو لتوصيل أداة محددة في تاريخ ثابت في المستقبل و بسعر يُحدد وقت إتمام الصفقة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":392,"en":"General Ledger","ar":"أستاذ عام","definition_en":"The primary record of a company’s financial information containing all of the accounts maintained by the company.","definition_ar":"سجل رئيسي للمعلومات المالية للشركة، يشمل جميع الحسابات التي تحتفظ بها الشركة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":393,"en":"Generally Accepted Accounting Principles (GAAP)","ar":"مبادئ المحاسبة المقبولة عموما (GAAP)","definition_en":"The body of accounting rules, methods, and procedures endorsed by the accounting profession, either by convention or by authoritative literature, as a guide to the preparation of financial statements.","definition_ar":"جهة في المحاسبة ذات قواعد، و طرق، و إجراءات تحظي بتأييد من مهنة المحاسبة، كمرشد لتحضير القوائم المالية، سواءاً بالعادات أو بالأدبيات المصرّحة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":394,"en":"Geographical Pricing","ar":"تسعير جغرافي","definition_en":"Product and service pricing based on the marketplace in which it is provided.","definition_ar":"تسعير المنتجات و الخدمات على أساس مكان السوق الذي تتوفر فيه.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":395,"en":"Goal Congruence","ar":"تطابق الهدف","definition_en":"A characteristic of a management control system that is structured so that the goals of individuals are consistent with the goals of the organization.","definition_ar":"خاصيّة في نظام ضوابط الإدارة، يُهيّكل بها أهداف الأفراد لتصبح متّسقةً مع أهداف الوحدة المنظمة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":396,"en":"Going Concern","ar":"الاستمرارية","definition_en":"The assumption that, in the absence of evidence to the contrary, a firm will continue to exist indefinitely.","definition_ar":"افتراض أن، في غياب ما يدل على العكس، ستستمر المنشأة في وجودها إلى ما لا نهاية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":397,"en":"Goodwill","ar":"شهرة","definition_en":"The excess of the fair market value an entity above its identifiable net assets.","definition_ar":"فائض قيمة السوق العادلة لكيان ما عن صافي أصوله القابلة للتعريف.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":398,"en":"Gross Profit Margin","ar":"هامش الربح الإجمالي","definition_en":"Net sales less cost of sales. (Also called Gross Profit.)","definition_ar":"صافي المبيعات ناقص تكلفة المبيعات. (يسمى أيضاً الربح الإجمالي.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":399,"en":"Gross Profit Margin Percentage","ar":"النسبة المئوية لهامش الربح الإجمالي","definition_en":"Gross profit divided by sales.","definition_ar":"الربح الإجمالي مقسوماً على المبيعات.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":400,"en":"Gross Revenue","ar":"الإيراد الإجمالي","definition_en":"Total unadjusted revenue. (Also called Gross Sales.)","definition_ar":"مجموع الإيرادات بدون تسوية. (يسمى أيضاً إجمالي المبيعات.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":401,"en":"Hardware","ar":"أجهزة","definition_en":"The physical components of a computer system.","definition_ar":"مكوّنات عينية في نظام الحاسوب.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":402,"en":"Hazard Risk","ar":"مخاطر الكوارث","definition_en":"The risk within a situation that has the potential for harm to humans, property and damage of environment or a combination of these.","definition_ar":"مخاطر ضمن حيز وضعية ذات إمكانية في أن تضر البشر، أو الممتلكات، أو تخرّب البيئة، أو كتركيبة مما سبق.","topic":"Risk Management","difficulty":"Intermediate"},{"id":403,"en":"Hedging","ar":"تحوّط","definition_en":"A method of reducing exposures to fluctuations in prices, exchange rates, or interest rates.","definition_ar":"طريقة لخفض التّعرض لتذبذبات الأسعار، أو أسعار الصرف، أو معدلات الفائدة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":404,"en":"Held-to-Maturity Securities","ar":"أوراق مالية تحفظ إلى تاريخ الاستحقاق","definition_en":"Investments in debt securities that the company plans to hold until they mature.","definition_ar":"استثمارات في الأوراق المالية للديون، تخطط الشركة بأن تمسك بها حتى استحقاقها.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":405,"en":"High-Low Method","ar":"طريقة أعلى أدنى","definition_en":"Method of estimating cost behavior by using only the highest and lowest values of the cost driver within the relevant range.","definition_ar":"طريقة لتقدير سلوك التكلفة باستخدام أعلى و أدنى قيمة لمحرك التكلفة و ذلك فقط ضمن حيز المدى ذو العلاقة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":406,"en":"Historical Cost","ar":"تكلفة تاريخية","definition_en":"The amount originally paid for an asset, unadjusted for subsequent changes in value. (Also called Acquisition Cost or Original Cost.)","definition_ar":"مبلغ أصلي دُفع في أصل ما، بدون تسوية تغيرات لاحقة في القيمة. (يسمى أيضاً تكلفة الاستحواذ أو التكلفة الأصلية.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":407,"en":"Holding Gain or Loss","ar":"مكاسب أو خسائر الإمساك","definition_en":"Unrealized gains or losses from holding assets or liabilities during a period of changing prices.","definition_ar":"مكاسب أو خسائر غير متحققة من الإمساك على الأصول أو المطلوبات أثناء فترة ما تتغير فيها الأسعار.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":408,"en":"Horizontal Analysis","ar":"تحليل أفقي","definition_en":"Compares each amount on a financial statement with a base amount for a selected base year. (Also called Common Base Year Statements.)","definition_ar":"يقارن كل مبلغ في قائمة مالية ما بمبلغ أساس من سنة أساس مختارة. (يسمى أيضاً قوائم سنة الأساس المشتركة.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":409,"en":"Hurdle Rate","ar":"معدل حدي","definition_en":"The minimum acceptable rate of return that companies will consider from a prospective project or investment. (Also called Required Rate of Return.)","definition_ar":"أدنى معدل عائد مقبول، تنتظره الشركات من مشروع أو استثمار قادم. (يسمى أيضاً معدل العائد المطلوب (Required Rate of Return).)","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":410,"en":"Hybrid Cost System","ar":"نظام تكلفة هجين","definition_en":"A cost system having characteristics of both Job Costing and Process Costing systems.","definition_ar":"نظام تكلفة به خصائص من أنظمة كلٍ من احتساب تكاليف العمل و احتساب تكاليف العمليات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":411,"en":"IMA Statement of Ethical Professional Practice","ar":"بيان الآي.أم.أيه. (IMA) لمزاولة المهنة بأخلاقية","definition_en":"A commitment to ethical professional practice made by members of the Institute of Management Accountants (IMA) that includes standards that guide the conduct of members including competence, confidentiality, integrity & credibility. The statement also includes guidelines for the resolution of ethical conflict.","definition_ar":"الالتزام بمزاولة المهنة بأخلاقية من قبل أعضاء معهد المحاسبين الإداريين (IMA)، يشمل معايير تُرشد الأعضاء في تصرفاتهم التي تشمل الجدارة، و السرية، و النزاهة، و المصداقية. و أيضاً يشمل البيان إرشادات لحل التضارب الأخلاقي.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":412,"en":"Impaired Asset","ar":"أصل ضعيف","definition_en":"An asset whose fair market value is less than the amount listed on the balance sheet.","definition_ar":"أصل، تكون قيمة السوق العادلة له أقل من المبلغ المدرج في الميزانية العمومية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":413,"en":"Implicit Costs","ar":"تكاليف ضمنية","definition_en":"Costs recognized in particular situations that are not regularly recognized in the accounting records of an entity. (Also called Imputed Costs.)","definition_ar":"تكاليف، يُعترف بها في وضعيات معينة ولا يُعترف بها في سجلات المحاسبة للكيان بانتظام. (يسمى أيضاً تكاليف مفترضة.)","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":414,"en":"Implicit Interest Rate","ar":"معدل فائدة ضمني","definition_en":"Rate that would have resulted from two independent parties negotiating an interest rate. (Also called Imputed Interest Rate.)","definition_ar":"معدل، يمكن أن ينتج من تفاوض طرفين مستقلين على معدل الفائدة. (يسمى أيضاً معدل الفائدة المفترض.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":415,"en":"Imposed Budget","ar":"موازنة مفروضة","definition_en":"A budget that is decided by higher level management without the participation of the manager of the unit to whom that budget relates. (Also called Top-Down Budget.)","definition_ar":"موازنة، تقررها إدارة المستوى الأعلى و بدون مشاركة من مدير الوحدة التي لها علاقة بتلك الموازنة. (يسمى أيضاً موازنة من القمة للأسفل.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":416,"en":"Income Statement","ar":"قائمة الدخل","definition_en":"A financial statement that reports the results of operations for a period of time. By presenting revenues, expenses, gains, losses, and net income, it measures a company’s success over a time period. (Also called Statement of Earnings.)","definition_ar":"قائمة مالية بمثابة تقرير عن نتائج التشغيل لفترة من الزمن. وذلك بتقديم الإيرادات، و المصاريف، و المكاسب، و الخسائر، و صافي الدخل، وهي تقيس نجاح الشركة على امتداد فترة زمنية ما. (يسمى أيضاً قائمة المدخولات (Statement of Earnings).)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":417,"en":"Income Tax","ar":"ضريبة الدخل","definition_en":"An annual tax levied by a government on the financial income of an entity.","definition_ar":"ضريبة سنوية، تفرضها حكومة ما على الدخل المالي للكيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":418,"en":"Incorporated (Inc.)","ar":"(Inc.) متضامنة","definition_en":"A company formed into a legal corporation.","definition_ar":"شركة، تشكلت كشركة عامة قانونية.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":419,"en":"Incremental","ar":"تزايدي","definition_en":"The difference in cash flow, both as to amount & as to timing, between two alternative courses of action.","definition_ar":"الفرق في تدفق النقد، كمبلغ و كتوقيت على حد سواء، و ذلك بين مساقين للعمل يعملان كبديلين.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":420,"en":"Incremental Analysis","ar":"تحليل تزايدي","definition_en":"A method of analyzing managerial decisions that emphasizes incremental rather than the total costs and benefits associated with an action (or set of alternative actions). (Also called Marginal Analysis or Differential Analysis.)","definition_ar":"طريقة لتحليل القرارات الإدارية، تُشدد على التزايد بدلًا من مجموع التكاليف و المنافع المرتبطة مع الفعل (أو مجموعة أفعال كبدائل). (يسمى أيضاً التحليل الهامشي أو التحليل التفاضلي.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":421,"en":"Incremental Unit-Time Learning Model","ar":"نموذج التّعلم بوقت الوحدة التزايدي","definition_en":"A learning curve model in which the incremental unit time (the time needed to produce the last unit) declines by a constant percentage each time the cumulative quantity of units produced is doubled.","definition_ar":"نموذج لمنحنى تعلم، يتراجع فيه وقت الوحدة التزايدي (وقت يُحتاج له لإنتاج آخر وحدة) بنسبة مئوية ثابتة لكل مرة تتضاعف فيها الكمية التراكمية من الوحدات المنتجة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":422,"en":"Indenture","ar":"سند","definition_en":"A written agreement (also called a deed of trust) between a debt issuer and a purchaser, stating the maturity date, interest rate and other terms.","definition_ar":"اتفاق خطي (يسمى أيضاً حجة الأمانة (deed of trust)) بين من يُصدر الدين و المشتري، يَرد فيه تاريخ الاستحقاق، و معدل الفائدة، و أحكام أخرى.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":423,"en":"Independent Auditor","ar":"مدقق مستقل","definition_en":"An external auditor who has no financial or other interest in the client whose financial statements are being examined.","definition_ar":"مدقق خارجي ليس له مصلحة مالية أو غيرها مع العميل الذي يختبر قوائمه المالية.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":424,"en":"Indirect Cost","ar":"تكلفة غير مباشرة","definition_en":"Any cost not directly identified with a single final cost object, but identified with two or more final cost objects or with at least one intermediate cost object. All costs other than direct materials and direct labor. (Also called Overhead Cost or Burden.)","definition_ar":"أي تكلفة غير مُعرّفة مباشرة على مادة تكلفة نهائية مفردة، بل مُعرّفة على اثنين أو أكثر من مواد التكلفة أو على الأقل على مادة تكلفة وسيطة واحدة. و هي جميع التكاليف من غير المواد المباشرة و العمالة المباشرة. (يسمى أيضاً تكلفة فوقية أو العبء (Overhead Cost or Burden).)","topic":"Cost Management","difficulty":"Intermediate"},{"id":425,"en":"Indirect Method","ar":"طريقة غير مباشرة","definition_en":"A method of preparing the Cash Flow Statement where net cash flow from operating activities is determined by adding back to or deducting from net income those items that had no effect on cash.","definition_ar":"طريقة لتحضير قائمة تدفق النقد، يحدد بها صافي تدفق النقد من أنشطة التشغيل و ذلك بإعادة إضافة أو استقطاع البنود التي ليس لها أثار على النقد من صافي الدخل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":426,"en":"Industry Risk","ar":"مخاطر الصناعة","definition_en":"Risks companies face by virtue of the industry they are in.","definition_ar":"مخاطر تواجهها الشركات بحكم الصناعة التي هي منها.","topic":"Risk Management","difficulty":"Intermediate"},{"id":427,"en":"Inflation","ar":"تضخم","definition_en":"A rise in the general level of prices of goods & services.","definition_ar":"ارتفاع في المستوى العام لأسعار البضاعة و الخدمات.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":428,"en":"Information System","ar":"نظام المعلومات","definition_en":"A system consisting of people, computers, voice and data communications, and methods organized to accomplish data and information operations. Information systems support the running of the enterprise’s business.","definition_ar":"نظام يتكوّن من ناس، و حواسيب، و اتصالات بالصوت و البيانات، و طرق منظمة ليتم تشغيل البيانات و المعلومات. و تساند أنظمة المعلومات سير العمل في المؤسسة (enterprise).","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":429,"en":"Information Technology (IT)","ar":"تكنولوجيا المعلومات (IT)","definition_en":"IT deals with the use of electronic hardware and software to convert, store, protect process, transmit, and retrieve information.","definition_ar":"تعمل تكنولوجيا المعلومات باستخدام الأجهزة و البرمجيات الإلكترونية لتحوّل، و لتخزّن، و لتحمي العمليات، و لتنقل، و لتسترجع المعلومات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":430,"en":"Inherent Risk","ar":"مخاطر كامنة","definition_en":"1. The risk related to the very nature of the activities the company undertakes in the course of business. 2. The auditor’s assessment of the likelihood that there are material misstatements in the financial statements before considering the effectiveness of internal controls.","definition_ar":"1. مخاطر ذات علاقة بصميم طبيعة الأنشطة التي تتعهدها شركة ما في مساق أعمالها. 2. و تقييم المدقق في ترجيح وجود بيانات غير صحيحة بأهمية نسبية في القوائم المالية، قبل النظر في فاعلية الضوابط الداخلية.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":431,"en":"Initial Public Offering (IPO)","ar":"الطرح العام الأولي (IPO)","definition_en":"A company’s first public issue of common stock.","definition_ar":"أول إصدار عام للأسهم العادية لشركة ما.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":432,"en":"Input Controls","ar":"ضوابط الإدخال","definition_en":"Controls that ensure the complete and accurate recording of authorized transactions by authorized users and identify rejected and duplicate items.","definition_ar":"ضوابط، تُوكّد أن التسجيل مُكتمل و دقيق لمعاملات مُصرّح بها من قبل مستخدمين مصرّح لهم مع تعريف البنود المرفوضة و المزدوجة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":433,"en":"Insider Trading","ar":"تداول داخلي","definition_en":"The buying and selling of a corporation’s stock by individuals with access to non-public information.","definition_ar":"شراء و بيع أسهم لشركة عامة من قبل أفراد لديهم حق الوصول لمعلومات غير معلنة.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":434,"en":"Installment Sale","ar":"بيع التقسيط","definition_en":"An arrangement where the buyer takes possession of the property immediately but does not receive the deed and title until a series of payments have been made.","definition_ar":"ترتيب، يأخذ به المشتري حيازة الممتلكات فوراً و لكنه لا يستلم الحجّة و حق الملكية حتى يتم الدفعات المتسلسلة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":435,"en":"Insurance","ar":"تأمين","definition_en":"A form of risk management used to hedge against the risk of a contingent, uncertain loss; the transfer of the risk of a loss from one entity to another, in exchange for payment.","definition_ar":"شكل من أشكال إدارة المخاطر، يُستخدم في التحوّط ضد مخاطر الخسارة العارضة، و عدم اليقين؛ بنقل مخاطر الخسارة من كيان إلى آخر، في مقابل دفعات.","topic":"Risk Management","difficulty":"Intermediate"},{"id":436,"en":"Intangible","ar":"غير ملموس","definition_en":"A type of non-current asset that has no physical substance and whose value comes from rights or advantages conferred upon the owner. Examples are patents, copyrights, trademarks, brand names, licenses, and goodwill.","definition_ar":"نوع من الأصول غير الجارية و ليس لها وجود مادي، يستمد قيمته من الحقوق أو المميزات الممنوحة للمالك. من الأمثلة على ذلك براءة الاختراع، و حقوق النسخ، و العلامات التجارية، و البراند، و التراخيص، و الشهرة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":437,"en":"Integrated Reporting","ar":"إعداد تقارير متكاملة","definition_en":"A process that communicates organization value creation over time in a periodic report.","definition_ar":"عملية تواصل عبر الزمن بتقرير دوري عن القيمة التي تخلقها وحدة منظمة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":438,"en":"Integrated Thinking","ar":"تفكير متكامل","definition_en":"A process of decision making, managing, and reporting that is based on the relationships of operating and functional units and the capitals that the organization uses to create value over time.","definition_ar":"عملية صنع القرار، و الإدارة، و إعداد التقارير، على أساس العلاقات بين وحدات التشغيل و سير العمل و رأس المال الذي تستخدمه الوحدة المنظمة لخلق القيمة مع مرور الزمن.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":439,"en":"Integrity","ar":"نزاهة","definition_en":"An ethical standard in IMA’s Statement of Ethical Professional Practice that requires members to avoid conflicts of interest and refrain from activities that would discredit the profession.","definition_ar":"معيار أخلاقي من بيان الآي.أم.أيه.( ) لمزاولة المهنة بأخلاقية، يَتطلب من الأعضاء تجنب تضارب المصالح و الامتناع عن الأنشطة التي قد تحط من مصداقية المهنة.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":440,"en":"Interest","ar":"فائدة","definition_en":"The cost incurred or amount earned for the use of borrowed capital.","definition_ar":"تكلفة مُتكبدة أو مبلغ يُجنى من جراء استخدام رأس مال مقترض.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":441,"en":"Interest-Bearing","ar":"تحمل فوائد","definition_en":"A debt instrument that includes a provision that interest be paid.","definition_ar":"أداة دين، تشمل تدابير لدفع الفائدة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":442,"en":"Interim Financial Reports","ar":"تقارير مالية وقتية","definition_en":"Financial statements prepared for periods shorter than one year, such as monthly or quarterly.","definition_ar":"قوائم مالية مُحضّرة لفترات أقصر من سنة واحدة، كأن تكون شهرية أو ربعية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":443,"en":"Internal Auditing","ar":"تدقيق داخلي","definition_en":"An appraisal activity within an entity that measures & reports on the extent to which various organizational policies are followed and goals are met.","definition_ar":"نشاط للتقويم ضمن حيز الكيان، يقيس و يقدم التقارير عن المدى الذي تُتبع به السياسات التنظيمية المختلفة و تُحقق الأهداف.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":444,"en":"Internal Control","ar":"ضوابط داخلية","definition_en":"Controls established by management to ensure adherence to management policies, safeguarding of assets, and completeness and accuracy of records.","definition_ar":"ضوابط، تُؤسسها الإدارة للتوكيد على التقيّد بسياسات الإدارة، و حماية الأصول، و اكتمال و دقة السجلات.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":445,"en":"Internal Control Risk","ar":"مخاطر الضوابط الداخلية","definition_en":"The risk that internal controls are not effective, because of either inadequate set-up and design or lax execution.","definition_ar":"مخاطر في عدم فاعلية الضوابط الداخلية، إما بسبب التهيئة و التصميم غير كافٍ أو التنفيذ رخو.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":446,"en":"Internal Factors","ar":"عوامل داخلية","definition_en":"In strategic planning, an analysis of the internal strengths and weaknesses of an entity.","definition_ar":"في التخطيط الاستراتيجي، هو تحليل داخلي لنقاط القوة و الضعف في الكيان.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":447,"en":"Internal Failure Costs","ar":"تكاليف الفشل الداخلي","definition_en":"Costs incurred when an entity detects nonconforming products or services before delivering them to customers. Examples include scrap, rework and retesting.","definition_ar":"تكاليف، يَتكبّدها الكيان عندما يكتشف منتجات أو خدمات غير مطابقة قبل توصيلها للزبائن. من الأمثلة على ذلك الخردة، و إعادة العمل، و إعادة الفحص.","topic":"Cost Management","difficulty":"Intermediate"},{"id":448,"en":"Internal Rate of Return (IRR)","ar":"معدل العائد الداخلي (IRR)","definition_en":"The discount rate that equates the net present value of a stream of cash outflows and inflows to zero.","definition_ar":"معدل خصم، يساوي صافي القيمة الحالية لمجرى التدفقات الصادرة للنقد و التدفقات الواردة للنقد بالصفر.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":449,"en":"International Accounting Standards Board (IASB)","ar":"مجلس معايير المحاسبة الدولية (IASB)","definition_en":"An independent, privately-funded accounting standard-setter based in London, UK, with board members from nine countries, committed to developing a single set of high-quality, understandable and enforceable global financial accounting standards","definition_ar":"جهة مستقلة، بتمويل خاص تضع معايير المحاسبة و مقرها في لندن، المملكة المتحدة، أعضاء مجلسها من تسع دول، و تلتزم بتطوير مجموعة واحدة من معايير المحاسبة المالية العالمية بنوعية عالية، و قابلية للفهم، و قابلية للإنفاذ","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":450,"en":"Internet","ar":"إنترنت","definition_en":"The worldwide collection of interconnected networks that use the Internet suite of protocols and permit public access.","definition_ar":"مجموعة شبكات ذات ترابط متداخل على اتساع العالم، تَستخدم مجموعة بروتوكولات الإنترنت و تسمح بالوصول العام.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":451,"en":"Intranet","ar":"إنترانت","definition_en":"A private network that integrates Internet standards and applications within an organization’s existing computer networking infrastructure.","definition_ar":"شبكة خاصة، تعمل على تكامل معايير و تطبيقات الإنترنت ضمن حيز البنية التحتية لشبكات الحاسوب الموجودة في الوحدة المنظمة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":452,"en":"Inventory","ar":"مخزون","definition_en":"The actual raw materials, supplies, goods on hand, goods in process of manufacture, and goods in transit, in storage, or consigned to others, or the act of accounting for, listing and pricing inventory.","definition_ar":"مخزون فعلي من مواد خام، و إمدادات، و بضاعة في اليد، و بضاعة قيد عملية التصنيع، و بضاعة قيد النقل، ليُخزّن أو ليُستودع مع الآخرين، أو بحسب قانون في المحاسبة، يُدرج و يُسعّر المخزون.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":453,"en":"Inventory Turnover","ar":"دوران المخزون","definition_en":"A ratio that measures the number of times a firm’s average inventory is sold during a year.","definition_ar":"نسبة، تقيس عدد المرات التي تبيع فيها المنشأة متوسط مخزونها أثناء السنة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":454,"en":"Inventory Valuation","ar":"تقدير قيمة المخزون","definition_en":"The measurement of the cost assigned to items in inventory.","definition_ar":"قياس للتكلفة، تُكلّف به البنود على المخزون.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":455,"en":"Invested Capital","ar":"رأس المال المستثمر","definition_en":"The amount of capital contributed to a business by equity investors, either directly or through the retention of earnings.","definition_ar":"مبلغ رأس مال، يُساهم به المستثمر في الأعمال بحقوق ملكية، سواءا مباشرة أو من خلال الاحتفاظ بالمدخولات.","topic":"Performance Management","difficulty":"Intermediate"},{"id":456,"en":"Investment","ar":"استثمار","definition_en":"Expenditure to acquire property or other assets in order to produce income; also, the asset so acquired.","definition_ar":"إنفاق لاستحواذ ممتلكات أو أصول أخرى من أجل إنتاج دخل؛ وأيضا، الأصل المستحوذ لذلك.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":457,"en":"Investment Center","ar":"مركز استثمار","definition_en":"A responsibility center whose performance is measured in the amount of income it earns relative to the investment in its assets.","definition_ar":"مركز مسؤولية، يُقاس به الأداء بمبلغ الدخل الذي يجنيه بالنسبة إلى الاستثمار في أصوله.","topic":"Performance Management","difficulty":"Intermediate"},{"id":458,"en":"Job Order Costing","ar":"احتساب تكاليف طلبية عمل","definition_en":"A method of cost accounting that accumulates costs for individual jobs or lots.","definition_ar":"طريقة في محاسبة التكاليف، تتراكم بها التكاليف لأوامر العمل أو للأعمال الفردية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":459,"en":"Joint Product Costing","ar":"احتساب تكاليف منتج مشترك","definition_en":"A method of cost accounting used when simultaneously producing or otherwise acquiring two or more products (joint products) that must, by the nature of the process, be produced or acquired together. (Also called Common Cost.)","definition_ar":"طريقة في محاسبة التكاليف، تُستخدم عند إنتاج أو استحواذ اثنين أو أكثر من المنتجات في وقت واحد (منتجات مشتركة)، و يجب، بحسب طبيعة العملية، إنتاجها أو استحواذها معاً. (يسمى أيضاً التكلفة المشتركة.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":460,"en":"Joint Venture","ar":"مشروع مشترك","definition_en":"A business enterprise jointly undertaken by two or more companies, who share the initial investment, risks, and profits.","definition_ar":"أعمال مشتركة في مؤسسة (enterprise)، يتعهدّها شركتان أو أكثر، وذلك بالاشتراك في الاستثمار الأولي، و المخاطر، و الأرباح.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":461,"en":"Journal","ar":"يومية","definition_en":"A record of original entry that records transactions in chronological sequence.","definition_ar":"سجل القيد الأصلي، تُسجل فيه المعاملات في سلسلة مرتبة زمنياً.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":462,"en":"Just-In-Time Manufacturing (JIT)","ar":"تصنيع فقط وقت الحاجة (JIT)","definition_en":"A manufacturing process where products are produced or procured as they are needed rather than when they can be made","definition_ar":"عملية تصنيع، تُنتج فيها المنتجات أو تموّن عندما يُحتاج لها بدلًا من عندما يمكن تصنيعها","topic":"Cost Management","difficulty":"Intermediate"},{"id":463,"en":"Kanban","ar":"(Kanban) كانبان","definition_en":"A manufacturing strategy wherein parts are produced or delivered only as needed.","definition_ar":"استراتيجية تصنيع، تُنتج بها القطع أو تُوصّل عند الحاجة لها فقط.","topic":"Cost Management","difficulty":"Intermediate"},{"id":464,"en":"Key Performance Indicators (KPI)","ar":"مؤشرات الأداء الرئيسية (KPI)","definition_en":"Essential measures for evaluating performance.","definition_ar":"قياسات أساسية يقيّم بها الأداء.","topic":"Performance Management","difficulty":"Intermediate"},{"id":465,"en":"Last-In-First-Out (LIFO)","ar":"الوارد آخراً يصرف أولًا (LIFO)","definition_en":"A method of inventory valuation and cost flow assumption, where ending inventory is measured by assigning the most recent costs incurred to costs of goods sold, and the earliest costs to ending inventory.","definition_ar":"طريقة لتقدير قيمة المخزون و افتراض تدفق التكلفة، تقاس بها تكلفة مخزون آخر المدة بتكليف أحدث التكاليف المتكبدة على تكلفة البضاعة المباعة، و أقدمها تكلّف على مخزون آخر المدة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":466,"en":"Law of Diminishing Returns","ar":"قانون تناقص العائدات","definition_en":"The principle that states that as increasingly more units of a variable resource are combined with a fixed amount of other resources, use of additional units of the variable resource will eventually increase output at a decreasing rate.","definition_ar":"مبدأ، يَردُ فيه أن بتزايد تركيب وحدات من مورد متغير مع موارد أخرى بمبلغ ثابت، في نهاية المطاف استخدام وحدات إضافية من المورد المتغير سيزيد المخرجات بمعدل متناقص.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":467,"en":"Lead Time","ar":"فترة تنفيذ","definition_en":"The time expected to elapse between the date an order is placed and the date the goods or services are received.","definition_ar":"فترة، يُتوّقع انقضاؤها بين تاريخ طلبية الشراء و تاريخ استلام البضاعة أو الخدمات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":468,"en":"Leadership by Example","ar":"قيادة بالقدوة","definition_en":"Leaders living and acting by the company’s code of ethics, setting a good example, keeping promises & commitments, and supporting others in adhering to the code of ethics. (Also called “Tone at the Top.”)","definition_ar":"قادة، يعيشون و يعملون وفقاً لدليل قواعد أخلاقيات الشركة، و يُعدُّون قدوة حسنة، و يوفون بالوعود و الالتزامات، و يساندون الآخرين للتقيّد بدليل قواعد الأخلاقيات. (يسمى أيضاً ترنيمة من القمة ”Tone at the Top”)","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":469,"en":"Lean Manufacturing","ar":"تصنيع رشيق","definition_en":"A production practice that treats expenditures for any goal other than the creation of value for the customer to be wasteful.","definition_ar":"مزاولة الإنتاج، تُعامِل النفقات التي بهدفٍ لا يُضيف قيمة للزبون على أنها نفقات ستهدر.","topic":"Cost Management","difficulty":"Intermediate"},{"id":470,"en":"Learning Curve","ar":"منحنى التعلم","definition_en":"A mathematical expression of the phenomenon that incremental unit costs to produce decrease as managers and labor gain experience from practice and as better methods are developed.","definition_ar":"تعبير في الرياضيات عن ظاهرة تناقص تكاليف الوحدة التزايدية في الإنتاج بعد اكتساب المدراء و العمالة خبرة بالمزاولة و بتطوير طرق أفضل.","topic":"Cost Management","difficulty":"Intermediate"},{"id":471,"en":"Lease","ar":"إيجار","definition_en":"A contract between the owner of property (Lessor) and the user (Lessee) concerning the financial and operating arrangements for the property.","definition_ar":"عقد بين مالك الممتلكات (المؤجر) ومستخدمها (المستأجر) فيما يخص الترتيبات المالية و التشغيلية للممتلكات.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":472,"en":"Leasehold","ar":"مُستأجَر","definition_en":"An asset representing the right of a Lessee (User) to use property.","definition_ar":"أصل، يُمثّل حق المستأجر (المستخدم) في استخدام الممتلكات.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":473,"en":"Least-Squares Method","ar":"طريقة المربعات الصغرى","definition_en":"A statistical method for defining a line that best fits the data points and reflects the relationship between variables. (Also called Linear Regression.)","definition_ar":"طريقة في الإحصاء لمعرفة أفضل خط يليق بنقاط البيانات و يعكس العلاقة بين المتغيرات (يسمى أيضاً انحدار خطي.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":474,"en":"Ledger","ar":"أستاذ","definition_en":"A book of accounts; any book of final entry.","definition_ar":"دفتر الحسابات؛ أي دفتر قيد نهائي.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":475,"en":"Legal Risk","ar":"مخاطر القانون","definition_en":"Potential for loss arising from the uncertainty of legal proceedings, such as bankruptcy, trademark challenges, liability claims, etc.","definition_ar":"إمكانية خسارة، تنجم عن عدم اليقين بالإجراءات القانونية، كالإفلاس، و تحديات العلامات التجارية، و المطالبة بالمطلوبات، و الخ.","topic":"Risk Management","difficulty":"Intermediate"},{"id":476,"en":"Letter of Credit","ar":"خطاب ائتمان","definition_en":"A binding document from a bank guaranteeing that a buyer’s payment will be received on time and for the correct amount. Often used in international trade to eliminate perceived risks.","definition_ar":"وثيقة مُلزِمة من البنك، تضمن استلام الدفعات من المشتري في الوقت و المبلغ الصحيح. مراراً، تُستخدم في التجارة الدولية للقضاء على المخاطر المدركة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":477,"en":"Leverage","ar":"مديونية","definition_en":"The extent to which a firm is financed by debt.","definition_ar":"مدى تمويل المنشأة بالدين.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":478,"en":"Leveraged Buyout (LBO)","ar":"شراء بالمديونية (LBO)","definition_en":"Form of ownership change where a company is taken private; the investor finances a significant percentage of the purchase price of the controlling interest with borrowing.","definition_ar":"شكل من أشكال تغيّر الملكية بأخذها كشركة خاصة؛ و يموّل المستثمر سعر شراء مصالح الضبط بالاقتراض بنسبة مئوية ذات أهمية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":479,"en":"Liability","ar":"مطلوبات","definition_en":"Probable future sacrifices of economic benefits arising from present obligations of a particular entity to transfer assets or provide services to other entities in the future as a result of past transactions or events.","definition_ar":"تضحيات محتملة في المستقبل لمنافع اقتصادية، تَنجم عن التزامات حالية لكيان معين بتحويل أصول أو توفير خدمات إلى كيانات أخرى في المستقبل كنتيجة لمعاملات أو أحداث ماضية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":480,"en":"Life-Cycle Costing","ar":"احتساب تكاليف دورة الحياة","definition_en":"The accumulation of costs for activities that occur over the entire life cycle of a product, including design and development, acquisition, operation, maintenance, and service.","definition_ar":"تراكم تكاليف الأنشطة التي تحدث على مدى دورة حياة المنتج بأكملها، تشمل التصميم و التطوير، و الاستحواذ، و التشغيل، و الصيانة، و الخدمة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":481,"en":"Line Item Budget","ar":"موازنة ذات بنود","definition_en":"A budget that classifies items of expense by the nature of the expense, such as salaries, fringe benefits, travel, etc.","definition_ar":"موازنة، تُصنّف بنود المصاريف حسب طبيعة المصاريف، كالرواتب، و المنافع الإضافية، و السفر، إلخ.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":482,"en":"Line of Business","ar":"خط الأعمال","definition_en":"A set of operations directed to the production & sale of a distinctive type of goods or services to customers","definition_ar":"مجموعة من العمليات، تُوجّه لإنتاج و بيع نوع مميز من البضاعة أو الخدمات للزبائن","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":483,"en":"Line of Credit","ar":"خط الائتمان","definition_en":"An agreement usually by a bank to make loans, not to exceed a specified total amount, when needed by a customer","definition_ar":"اتفاق، يكون عادةً مع بنك يمنح قروض، لا تتجاوز مجموع مبلغ محدد، عندما يحتاج الزبون لها","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":484,"en":"Linear Programming","ar":"برمجة خطية","definition_en":"A mathematical tool used to optimize a function (the objective function) subject to various constraints, all of which are linear. Often used to find the combination of products that will maximize profits or minimize costs","definition_ar":"أداة في الرياضيات، تُستخدم للارتقاء بمسارات العمل (دالة الهدف) التي تكون موضوعاً لمعيقات مختلفة، تكون كل منها خطية. مراراً، تُستخدم في إيجاد تركيبة المنتجات التي ستعظّم الأرباح و ستقلل التكاليف.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":485,"en":"Liquidation","ar":"تصفية","definition_en":"The process by which a company, or part of a company, is terminated and the assets are redistributed.","definition_ar":"عملية، تُنهى بها الشركة، أو جزء من الشركة، و يُعاد توزيع الأصول.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":486,"en":"Liquidity","ar":"سيولة","definition_en":"Ability to convert an asset into cash quickly.","definition_ar":"مقدرة على تحوّل الأصل إلى نقد بسرعة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":487,"en":"Loan Covenants","ar":"مواثيق القرض","definition_en":"Clauses in a loan agreement that require one party to do, or refrain from doing, certain things.","definition_ar":"عبارات في اتفاق القرض، تتطلب من أحد الطرفين عمل، أو الامتناع عن عمل، أشياء معينة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":488,"en":"Lockbox System","ar":"نظام الصندوق المقفل","definition_en":"A system where a financial entity collects and deposits payments on behalf of an entity thereby reducing the mail and processing float.","definition_ar":"نظام به كيان مالي، يجمع و يودع الدفعات بالنيابة عن كيان آخر مما يخفض من البريد وتعويم العمليات.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":489,"en":"Long Position","ar":"مركز طويل","definition_en":"The purchase of a security with the expectation that the security will rise in value.","definition_ar":"شراء أوراق مالية من المتوقع أن ترتفع قيمتها.","topic":"Risk Management","difficulty":"Intermediate"},{"id":490,"en":"Long Run","ar":"مدى طويل","definition_en":"A time period of sufficient length to enable decision makers to adjust fully to a market change; the period of time in which all costs are variable.","definition_ar":"فترة زمنية ذات مدة كافية تُمكّن صنّاع القرار من التسوية مع تغير السوق تماماً. و هي فترة من الزمن تكون فيها جميع التكاليف متغيرة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":491,"en":"Long-Term Debt to Equity Ratio","ar":"نسبة الديون طويلة المدة إلى حقوق الملكية","definition_en":"Measure of the financial leverage of a firm.","definition_ar":"قياس المديونية المالية لمنشأة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":492,"en":"Long-Term Liabilities","ar":"مطلوبات طويلة المدة","definition_en":"Debts due for repayment more than one year in the future or beyond the normal operating cycle.","definition_ar":"إتمام دُفعات ديون، تُستحق بعد أكثر من سنة في المستقبل أو من بعد دورة التشغيل العادية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":493,"en":"Lower of Cost or Market Rule","ar":"قاعدة التكلفة أو السوق أيهما أدنى (LCM)","definition_en":"A method of valuation that results in an asset being valued at either acquisition cost or market value, whichever is lower.","definition_ar":"طريقة لتقدير القيمة، يَنتج بها أصل تكون قيمته أما بتكلفة الاستحواذ أو بقيمة السوق، أيهما أدنى.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":494,"en":"Maintenance","ar":"صيانة","definition_en":"Expenditures necessary to achieve the originally anticipated useful life of a fixed asset.","definition_ar":"نفقات ضرورية، ليُنجز الأصل الثابت عمر الاستفادة الأصلي المنتظر منه.","topic":"Cost Management","difficulty":"Intermediate"},{"id":495,"en":"Make Versus Buy","ar":"الصنع مقابل الشراء","definition_en":"The decision either to produce a good or service with an entity’s own resources or to buy it from an outside supplier.","definition_ar":"قرار أما أن، تُنتج البضاعة أو الخدمة من الموارد التي يمتلكها الكيان أو أن تُشترى من مورّد خارجي.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":496,"en":"Managed Floating Exchange Rates","ar":"أسعار صرف بتعويم مُدار","definition_en":"An exchange rate that is mostly allowed to change (float) as demand in currency supply and demand changes but is often altered (managed) by governments through their buying and selling of certain currencies.","definition_ar":"سعر صرف، يُسمح له بالتّغير (التعويم) غالباً مع تغيّر الطلب على عرض العملة والطلب عليها و لكنه مراراً يتبدل (التديير) من قبل الحكومات من خلال شرائها و بيعها لعملات معينة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":497,"en":"Management","ar":"إدارة","definition_en":"The process of leading and directing all or part of an organization, often a business, through the deployment and organization of resources.","definition_ar":"عملية قيادة و توجيه وحدة منظمة ككل أو جزء منها، مراراً تكون في أحد الأعمال، من خلال انتشار و تنظيم الموارد.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":498,"en":"Management Accounting","ar":"محاسبة إدارية","definition_en":"The process of identification, measurement, accumulation, analysis, preparation, interpretation, and communication of financial information used by internal decision makers in order to plan, evaluate, and control an entity and to assure appropriate use of and accountability for its resources. (Also called Managerial Accounting.)","definition_ar":"عملية التعريف، و القياس، و التراكم، و التحليل، و التحضير، و التفسير، و الاتصال بالمعلومات المالية التي يستخدمها صنّاع القرار الداخليون من أجل التخطيط، و التقييم، و الضبط في الكيان و لتؤكد على الاستخدام المتناسب و المساءلة عن موارده. (ويسمى أيضاً (Managerial Accounting))","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":499,"en":"Management Control","ar":"ضبط الإدارة","definition_en":"An organized, integrated process and structure through which management attempts to achieve enterprise goals effectively and efficiently.","definition_ar":"تنظيم متكامل للعملية و الهيكل، تَشرع الإدارة من خلاله إنجاز أهداف المؤسسة (enterprise) بفاعلية و فعالية.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":500,"en":"Management Discussion and Analysis","ar":"مناقشة و تحليل الإدارة (MD&A)","definition_en":"A discussion of Management’s views of an entity’s performance, required by the US Securities and Exchange Commission to be included in the Annual Report on Form 10-K.","definition_ar":"مناقشة آراء الإدارة عن أداء الكيان، تطلُبها لجنة الأوراق المالية و صرف العملات في الولايات المتحدة ليشتمل عليها التقرير السنوي في نموذج 10-K.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":501,"en":"Management Information System","ar":"نظام إدارة المعلومات","definition_en":"A system that provides past, present, and prospective information about internal operations and external intelligence.","definition_ar":"نظام، يوفّر الماضي، و الحاضر، و القادم من المعلومات عن العمليات الداخلية و الذكاء الخارجي.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":502,"en":"Management-by-Exception","ar":"إدارة بالاستثناء","definition_en":"The management practice of focusing on areas that deserve attention and ignoring areas that seem to be running smoothly.","definition_ar":"مزاولة الإدارة بالتركيز على مناطق تستاهل الانتباه و تجاهل المناطق التي على ما يبدو أنها تسير بسلاسة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":503,"en":"Manufacturing","ar":"تصنيع","definition_en":"The transformation of raw materials into finished goods.","definition_ar":"تناقل مواد الخام إلى أن تصبح بضاعة تامة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":504,"en":"Manufacturing Cost","ar":"تكلفة التصنيع","definition_en":"The costs incurred to transform materials into other goods through labor and factory facilities.","definition_ar":"تكاليف مُتكبدة لتحويل المواد إلى بضاعة أخرى من خلال العمالة و مرافق المصنع.","topic":"Cost Management","difficulty":"Intermediate"},{"id":505,"en":"Margin of Safety","ar":"هامش الأمان","definition_en":"The excess of budgeted sales over the break-even volume.","definition_ar":"فائض مبيعات الموازنة على حجم التعادل.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":506,"en":"Marginal Cost","ar":"تكلفة هامشية","definition_en":"Cost resulting from the production of one additional unit.","definition_ar":"تكلفة، تَنتج من إنتاج وحدة إضافية واحدة.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":507,"en":"Market Comparables","ar":"مقارنات السوق","definition_en":"Estimating the price of an asset by comparing to recent sales prices of assets with similar characteristics.","definition_ar":"تقدير سعر الأصل بمقارنته بأحدث أسعار بيع أصول ذات خصائص مشابهة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":508,"en":"Market Equilibrium Price","ar":"سعر توازن السوق","definition_en":"The price of a good or service that will balance the supply and demand.","definition_ar":"سعر البضاعة أو الخدمة الذي سيوازن العرض بالطلب.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":509,"en":"Market Penetration","ar":"اختراق السوق","definition_en":"A measure of an entity’s sales of a given product or service compared to the total sales of all suppliers in the market. (Also called Market Share.)","definition_ar":"قياس مبيعات منتج أو خدمة معطاة من الكيان بالمقارنة مع مجموع المبيعات من جميع الموردين في السوق. (يسمى أيضاً حصة السوق.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":510,"en":"Market Price","ar":"سعر السوق","definition_en":"The current price for which a good or service is offered in the marketplace.","definition_ar":"سعر حالي، تُطرح به البضاعة أو الخدمة في مكان لسوق.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":511,"en":"Market Risk","ar":"مخاطر السوق","definition_en":"The portion of stock price (or portfolio) movement that is attributable to the movement of the market as a whole. (Also called Systematic Risk.)","definition_ar":"جزئية من حركة سعر السهم (أو المحفظة)، تُعزى لمجمل حركة السوق. (يسمى أيضاً مخاطر نظامية.)","topic":"Risk Management","difficulty":"Intermediate"},{"id":512,"en":"Market Skimming Pricing","ar":"تسعير بكشط السوق","definition_en":"Charging a relatively high price for a short time when a new, innovative, or much-improved product is launched onto a market.","definition_ar":"تثمين بسعرٍ عالٍ نسبياً لفترة قصيرة عندما يطلق في السوق منتجاً جديداً، أو مبتكراً، أو أكثر تحسيناً.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":513,"en":"Market Structure","ar":"هيكل السوق","definition_en":"The organizational and other characteristics of a market, in particular those that affect the nature of competition and pricing.","definition_ar":"خصائص السوق التنظيمية و غيرها من الخصائص، لا سيما تلك التي تؤثر في طبيعة المنافسة و التسعير.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":514,"en":"Market Value","ar":"قيمة السوق","definition_en":"The value of a good, a service, or a security as determined by buyers and sellers in an open market.","definition_ar":"قيمة بضاعة، أو خدمة، أو ورقة مالية كما يحددها المشترون و البائعون في سوق مفتوح.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":515,"en":"Marketability","ar":"قابلية السوق","definition_en":"A characteristic of a security that allows it to be sold at a reasonable price in a short period of time.","definition_ar":"خاصية ورقة مالية، يُسمح ببيعها بسعر معقول في فترة من الزمن تكون قصيرة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":516,"en":"Marketable Securities","ar":"أوراق مالية بقابلية السوق","definition_en":"1. Liquid securities that can be converted into cash quickly. 2. A balance sheet classification for negotiable financial instruments.","definition_ar":"1. أوراق مالية سائلة، يُمكن تحويلها إلى نقد بسرعة. 2. تصنيف في الميزانية العمومية للأدوات المالية القابلة للتفاوض.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":517,"en":"Market-Based Transfer Price","ar":"سعر التحويل على أساس السوق","definition_en":"When the price for goods or services charged by one division of a company to another is based on the market price.","definition_ar":"عندما يصبح السعر على أساس سعر السوق لبضاعة أو خدمات يُثمّنها قسم من الشركة لقسم آخر فيها.","topic":"Performance Management","difficulty":"Intermediate"},{"id":518,"en":"Market-to-Book Ratio","ar":"نسبة السوق إلى الدفتر","definition_en":"Current stock price divided by book value per share, where “book value” equals common shareholders’ equity. (Also called Price-to-Book Ratio.)","definition_ar":"سعر السهم الحالي مقسوماً على قيمة الدفتر لكل حصة، إذ تساوي “قيمة الدفتر” حقوق الملكية لأصحاب الحصص العادية. (يسمى أيضاً نسبة السعر إلى الدفتر.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":519,"en":"Master Budget","ar":"موازنة رئيسية","definition_en":"A budget that consolidates all budgets into an overall plan and control document, for a budgeted period. (Also called a Comprehensive Budget.)","definition_ar":"موازنة، تُوحّد جميع الموازنات كخطة للكل و كوثيقة للضبط، للفترة التي أُعدت لها الموازنة. (يسمى أيضاً موازنة شاملة.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":520,"en":"Matching","ar":"مطابقة","definition_en":"The process of recognizing expenses in the same accounting period as that in which the related revenues are recognized.","definition_ar":"عملية الاعتراف بالمصاريف في نفس فترة المحاسبة التي فيها أعترف بالإيرادات ذات العلاقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":521,"en":"Material Requirements Planning (MRP)","ar":"تخطيط متطلبات المواد (MRP)","definition_en":"A system that translates a production schedule into requirements for each component needed to meet that schedule.","definition_ar":"نظام، يُترجم جدول الإنتاج إلى المتطلبات التي يحتاج لها كل مكوّن لتلبية ذلك الجدول.","topic":"Cost Management","difficulty":"Intermediate"},{"id":522,"en":"Materiality","ar":"أهمية نسبية","definition_en":"The concept that accounting should separately recognize only those events that are relatively important for understanding an entity’s statements.","definition_ar":"مفهوم، ينبغي به على المحاسبة الاعتراف فقط بالأحداث المنفصلة و المهمة نسبياً لفهم قوائم الكيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":523,"en":"Maturity Date","ar":"تاريخ الاستحقاق","definition_en":"The date on which a debt becomes due for payment.","definition_ar":"تاريخ، يُصبح فيه الدين مستحق الدفع.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":524,"en":"Maturity Matching","ar":"مطابقة الاستحقاق","definition_en":"The matching of asset and liability maturities; i.e., financing long-term assets with long-term sources and short-term needs with short-term sources.","definition_ar":"مطابقة استحقاقات الأصول على المطلوبات؛ أي، تمويل الأصول طويلة المدة بمصادر طويلة المدة و الاحتياجات قصيرة المدة بمصادر قصيرة المدة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":525,"en":"Maximum Possible Loss","ar":"أقصى خسارة ممكنة","definition_en":"The most pessimistic view of possible loss; when referring to insurance of a building, for example, the risk that the entire structure, its immediate surroundings, and all the building’s contents will be destroyed. (Also called Extreme or Catastrophic Loss.)","definition_ar":"أكثر وجهات النظر تشاؤماً عن خسارة ممكنة؛ فعندما يشار إلى تأمين مبنى، على سبيل المثال، تكون المخاطر في أنه سيدمر بأكمله من هيكل، و محيط ملاصق، و جميع محتويات المبنى. (يسمى أيضاً الخسارة القصوى أو الكارثية.)","topic":"Risk Management","difficulty":"Intermediate"},{"id":526,"en":"Merger","ar":"اندماج","definition_en":"The combining of two or more companies.","definition_ar":"تركيبة من شركتين أو أكثر.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":527,"en":"Mission","ar":"الرسالة","definition_en":"The purpose or reason for an organization’s existence.","definition_ar":"غرض أو سبب وجود الوحدة المنظمة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":528,"en":"Mix Variance","ar":"انحراف المزيج","definition_en":"A variance that results when actual proportions of the components of revenues or costs are different from the proportions used in arriving at the budgeted or planned revenue or cost, or the standard cost.","definition_ar":"انحراف، ينتج عندما تكون النسب الفعلية لمكونات الإيرادات أو التكاليف مختلفة عن النسب المستخدمة للوصول إلى الإيرادات أو التكاليف كما أُعدت في الموازنة أو خطط لها، أو التكلفة المعيارية.","topic":"Performance Management","difficulty":"Intermediate"},{"id":529,"en":"Mixed Cost","ar":"تكلفة المزيج","definition_en":"A cost composed of fixed and variable elements.","definition_ar":"تكلفة مكوّنة من عناصر ثابتة و متغيرة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":530,"en":"Modified Accelerated Cost Recovery System (MACRS)","ar":"نظام تغطية التكاليف المتسارع و المعدّل (MACRS)","definition_en":"The accelerated depreciation method used for U.S. income taxes.","definition_ar":"طريقة اهتلاك متسارعة، تُستخدم في ضريبة الدخل في الولايات المتحدة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":531,"en":"Monetary Items","ar":"بنود النقد","definition_en":"Money or a claim (an obligation) to receive (or pay) a sum of money, the amount of which is fixed or determinable without reference to future prices of specific goods and services.","definition_ar":"مال أو مطالبة (التزام) باستلام (أو دفع) حاصل جمع مال، بمبلغ ثابت أو قابل للتحديد بدون الإشارة إلى أسعار بضاعة و خدمات محددة في المستقبل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":532,"en":"Monopolistic Competition","ar":"منافسة احتكارية","definition_en":"A situation where there are a large number of independent sellers, each producing a differentiated product in a market with low barriers to entry.","definition_ar":"وضعية فيها عدد كبير من البائعين المستقلين، يُنتج كل منهم منتجاً متمايزاً في سوق ذي حواجز متدنية للدخول.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":533,"en":"Monopoly","ar":"احتكار","definition_en":"A market structure characterized by a single seller of a well defined product for which there are no good substitutes and by high barriers to the entry of any other firms into the market for that product.","definition_ar":"هيكل لسوق ذي خاصية البائع الفردي لمنتج معرّف جيداً ولا إبدالات جيدة له و فيه حواجز عالية لدخول المنشآت الأخرى إلى سوق هذا المنتج.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":534,"en":"Monte Carlo Technique","ar":"تقنية مونت كارلو","definition_en":"An analytical technique in which a large number of simulations are run to infer the most likely result, using random quantities for uncertain variables.","definition_ar":"تقنية تحليلية، يجري فيها عدد كبير من المحاكاة لاستنتاج النتائج الأكثر ترجيحاً، باستخدام كميات عشوائية من المتغيرات المنعدمة اليقين.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":535,"en":"Moral Philosophy","ar":"فلسفة معنوية","definition_en":"The branch of philosophy that examines what is right and what is wrong.","definition_ar":"فرع فلسفة، يختبر ما هو صح وما هو خطأ.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":536,"en":"Morality","ar":"معنوية","definition_en":"A system of principles that distinguish between right and wrong conduct (also called Ethics.)","definition_ar":"نظام من المبادئ، يميز ما بين تصرف صح و خطأ (يسمى أيضاً الأخلاقيات.)","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":537,"en":"Mortgage","ar":"رهن","definition_en":"A claim given by the borrower to the lender against the borrower’s property.","definition_ar":"مطالبة، يُعطيها المقترض إلى المقرض في مقابل ممتلكات المقترض.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":538,"en":"Moving Average","ar":"متوسط متحرك","definition_en":"A method of calculating central tendency over time in an attempt to identify long-term trends. The average is calculated over a specific time period (e.g. years). For each time period after the initial one, the earliest value is dropped from the calculation and the most recent one is added in, to make an average over the same length of time.","definition_ar":"طريقة لاحتساب مركز القابلية مع مرور الزمن كشروع للتعرّف على التوجهات طويلة المدة. و يحتسب المتوسط على امتداد فترة زمنية محددة. (مثل، السنوات). و لكل فترة زمنية بعد الفترة الأولي، تُسقط أقدم قيمة من الاحتساب و تُضاف أحدث قيمة إليه، لعمل متوسط خلال نفس المدة الزمنية.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":539,"en":"Multinational Company","ar":"شركة متعددة الجنسيات","definition_en":"Company operating in several countries.","definition_ar":"شركة، تُشغّل في عدة دول.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":540,"en":"Multiple Regression","ar":"انحدار متعدد","definition_en":"A statistical method used to model the relationship between one dependent (or response) variable and one or more independent (or explanatory) variables by fitting a linear equation to observed data. (Also called Multiple Linear Regression.)","definition_ar":"طريقة في الإحصاء، تُستخدم في نمذجة العلاقة بين متغير (أو استجابة) تابع واحد و متغير واحد أو أكثر مستقل (أو شرح) و ذلك بعمل معادلة خطية تليق بالبيانات الملحوظة. (يسمى أيضاً انحدار خطي متعدد.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":541,"en":"Mutually Exclusive Project","ar":"مشروع حصري متبادل","definition_en":"Competing investment projects in which accepting one project eliminates the possibility of undertaking the remaining projects.","definition_ar":"مشاريع استثمار متنافسة، يمكن أن يقضي قبول أحد تلك المشاريع على التعهد بباقي المشاريع.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":542,"en":"Negotiable CD","ar":"شهادة إيداع قابلة للتفاوض","definition_en":"A Certificate of Deposit with a very large denomination, usually $1 million or more. They are usually in bearer form, considered low risk and highly liquid. (Also called Jumbo CD.)","definition_ar":"شهادة إيداع ذات فئة كبيرة جداً، عادةً تبلغ 1$ مليون دولار أمريكي أو أكثر. و عادة تكون في نموذج لحامله، و تعتبر ذات مخاطر دنيا و سيولة عالية. (يسمى أيضاً شهادة إيداع جمبو.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":543,"en":"Negotiated Price","ar":"سعر بالتفاوض","definition_en":"In transfer pricing, the price charged by one segment of an organization to another for a product or service that is determined by negotiation between the segments.","definition_ar":"في تسعير التحويل، هو سعر يُثمّن به منتج أو خدمة من أحد مقاطع الوحدة المنظمة لمقطع آخر فيها و يحدد بالتفاوض بين المقطعين.","topic":"Performance Management","difficulty":"Intermediate"},{"id":544,"en":"Net Income","ar":"صافي الدخل","definition_en":"Income for a period after subtracting expenses from all sources for that period. (Also called Net Earnings.)","definition_ar":"دخل الفترة، بعد طرح المصاريف من جميع مصادر تلك الفترة. (يسمى أيضاً صافي المدخولات (Net Earnings).)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":545,"en":"Net Loss","ar":"صافي الخسارة","definition_en":"The negative amount that results when expenses are greater than revenues.","definition_ar":"مبلغ بالسالب، ينتج عندما تكون المصاريف أكبر من الإيرادات.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":546,"en":"Net Present Value (NPV)","ar":"صافي القيمة الحالية (NPV)","definition_en":"The difference between the present value of all cash inflows from a project or investment and the present value of all cash outflows required to obtain the investment, or to undertake the project at a given discount rate.","definition_ar":"الفرق بين القيمة الحالية لكافة التدفقات الواردة للنقد من مشروع أو استثمار و القيمة الحالية لكافة التدفقات الصادرة للنقد التي يتطلبها الحصول على الاستثمار، أو لتعهد مشروع عند معدل خصم معطى.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":547,"en":"Net Profit Margin","ar":"هامش صافي الربح","definition_en":"A financial ratio where net income is divided by sales. (Also called Net Profit Margin Percentage.)","definition_ar":"نسبة مالية، تكون بصافي الدخل مقسوماً على المبيعات. (يسمى أيضاً النسبة المئوية لهامش صافي الربح.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":548,"en":"Net Realizable Value","ar":"صافي القيمة القابلة لتتحقق","definition_en":"1. The estimated selling price in the ordinary course of business less the reasonably predictable cost of completion and disposal. 2. Accounts receivable less allowance for bad debts.","definition_ar":"1. تقدير سعر البيع في مساق الأعمال الاعتيادية ناقصاً منه تكلفة الاكتمال و التخلّص القابلة للتنبؤ بها بحد معقول. 2. الحسابات المدينة ناقصاً منها مسموحات الديون المعدومة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":549,"en":"Net Working Capital","ar":"صافي رأس المال العامل","definition_en":"Current assets less current liabilities.","definition_ar":"الأصول الجارية ناقص المطلوبات الجارية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":550,"en":"Net Working Capital Ratio","ar":"نسبة صافي رأس المال العامل","definition_en":"A liquidity financial ration that measures net working capital as a percent of total assets.","definition_ar":"مرزومة سيولة مالية، تقيس صافي رأس المال العامل كنسبة مئوية من مجموع الأصول.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":551,"en":"Network","ar":"شبكة","definition_en":"In data communications, a configuration in which two or more locations are physically connected for the purpose of exchanging data.","definition_ar":"في اتصالات البيانات، تكوين فيه موقعين أو أكثر متصلين مادياً بغرض استبدال البيانات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":552,"en":"Network Controls","ar":"ضوابط الشكبة","definition_en":"Internal controls to insure accurate and secure flows of data in computer and communication systems.","definition_ar":"ضوابط داخلية لتأمين تدفقات دقيقة و آمنة للبيانات في الحاسوب و أنظمة الاتصالات.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":553,"en":"Nominal","ar":"اسمي","definition_en":"A term signifying that a value has not been adjusted for inflation.","definition_ar":"مصطلح، يُشير إلى أن القيمة بدون تسوية للتضخم.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":554,"en":"Noncumulative Preferred Stock","ar":"أسهم ممتازة غير تراكمية","definition_en":"Preferred stock whose holders do not receive dividends in arrears.","definition_ar":"أسهم ممتازة، لا يستلم حامليها توزيع أرباح على المتأخرات.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":555,"en":"Non-Monetary Exchange","ar":"استبدال غير النقد","definition_en":"The exchange of goods or services between entities for which no monetary instruments are involved. (Also called Barter.)","definition_ar":"استبدال البضاعة أو الخدمات بين الكيانات، لا يتضمن أدوات النقد. (يسمى أيضاً مقايضة.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":556,"en":"Non-Price Competition","ar":"منافسة غير السعر","definition_en":"Methods firms use to attract customers other than price reductions, including advertising, free gifts, special packaging, etc.","definition_ar":"طرق، تستخدمها المنشآت لجذب الزبائن من غير تخفيض للسعر، تشمل الدعاية، و الهدايا المجانية، و التغليف الخاص، إلخ.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":557,"en":"Nonrecurring Items","ar":"بنود غير متكررة","definition_en":"One-time occurrences for an entity involving unusual income or expense.","definition_ar":"أمور، تحدث مرة واحدة في الكيان تتضمن الدخل أو المصاريف غير المعتادة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":558,"en":"Non-Value Added","ar":"بدون قيمة مضافة","definition_en":"An activity that increases a good’s costs without increasing its value to the consumer.","definition_ar":"نشاط، يزيد تكاليف السلعة بدون زيادة قيمتها للمستهلك.","topic":"Cost Management","difficulty":"Intermediate"},{"id":559,"en":"No-Par Stock","ar":"أسهم بدون وُجهيّة","definition_en":"The shares of a company that carry no nominal or par value.","definition_ar":"حصص في شركة، لا تحمل قيمة اسمية أو وُجهيّة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":560,"en":"Normal Cost","ar":"تكلفة عادية","definition_en":"A costing system whereby cost objects are assigned the sum of direct materials and labor resources consumed plus an allocation of overhead based on normal capacity.","definition_ar":"نظام لاحتساب التكاليف، يتم به تكليف مواد التكلفة بحاصل جمع المواد المباشرة و موارد العمالة المستهلكة زائد تخصيص الفوقية على أساس طاقة الإنتاج العادية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":561,"en":"Normal Profit","ar":"ربح عادي","definition_en":"The net earnings for an enterprise that recognizes that a reasonable return on capital (both debt and equity) is one of the costs of the enterprise.","definition_ar":"صافي مدخولات المؤسسة (enterprise)، يَعترف بأن العائد المعقول على رأس المال (سواء دين أو حقوق الملكية) هو إحدى تكاليف المؤسسة (enterprise).","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":562,"en":"Normal Spoilage","ar":"تلف عادي","definition_en":"Inherent product deterioration that is expected even under the best operating conditions. It is unavoidable in the short run.","definition_ar":"تَدَني كامن في المنتج، يُتوقّع حتى تحت أفضل حالات التشغيل. وهو غير قابل للتجنب في المدى القصير.","topic":"Cost Management","difficulty":"Intermediate"},{"id":563,"en":"Notes Payable","ar":"حسابات دائنة للإشعارات","definition_en":"A short-term debt instrument whereby the issuer promises repayment on or before a specified date.","definition_ar":"أداة دين قصيرة المدة، يَعدُ من يصدرها بإتمام الدفع في أو قبل التاريخ المحدد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":564,"en":"Notes to the Financial Statements","ar":"ملاحظات على القوائم المالية","definition_en":"Supplemental disclosures that describe a company’s major accounting policies and other relevant information.","definition_ar":"إفصاحات ملحقة، تصف سياسات المحاسبة الرئيسية في الشركة و غيرها من المعلومات ذات العلاقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":565,"en":"Objective Function","ar":"دالة الهدف","definition_en":"In Linear Programming, the variable to be maximized (profit) or minimized (cost).","definition_ar":"في البرمجة الخطية، هي المتغير الذي يُعظّم (ربح) أو يُقلل (تكلفة).","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":566,"en":"Objectivity","ar":"موضوعية","definition_en":"A trait of financial reporting that emphasizes the verifiable, factual nature of events or transactions and minimizes personal judgment in the measurement process.","definition_ar":"سمة في إعداد التقارير المالية، تشدد على الطبيعة الوقائعية، القابلة للتحقق منها للأحداث أو المعاملات، و تقلل من الحكم الشخصي عند عملية القياس.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":567,"en":"Obsolescence","ar":"اندثار","definition_en":"The loss in usefulness of an asset caused by technological or market changes.","definition_ar":"خسارة في الاستفادة من الأصل سببها تغيرات التكنولوجيا أو السوق.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":568,"en":"Off-Balance Sheet Financing","ar":"تمويل خارج الميزانية العمومية","definition_en":"Financing from sources other than debt and equity offerings that are not reflected on an entity’s balance sheet, such as joint ventures, partnerships, and operating leases.","definition_ar":"تمويل من مصادر أخرى غير الدين و طرح حقوق الملكية، لا ينعكس على الميزانية العمومية للكيان، كالمشاريع المشتركة، و الشراكات، و الإيجارات التشغيلية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":569,"en":"Oligopoly","ar":"احتكار القلة","definition_en":"A market situation in which a small number of sellers comprise the entire industry.","definition_ar":"وضعية في السوق، تتألف بها الصناعة بأكملها من عدد قليل من البائعين.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":570,"en":"Operating Budget","ar":"موازنة التشغيل","definition_en":"Detailed projection of all estimated revenue, expenses, and income based on forecasted sales revenue during a given period (usually one year). (Also called Operational Budget.)","definition_ar":"عرض التصورات التفصيلية لجميع تقديرات الإيراد، و المصاريف، و الدخل على أساس إيراد المبيعات المتوقع أثناء فترة معطاة (عادة سنة واحدة). (يسمى أيضاً الموازنة التشغيلية.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":571,"en":"Operating Cycle","ar":"دورة التشغيل","definition_en":"The average time between the acquisition of materials or services and the final cash realization from the sale of products.","definition_ar":"متوسط الزمن بين استحواذ المواد أو الخدمات و تحقق النقد النهائي من بيع المنتجات.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":572,"en":"Operating Expenses","ar":"مصاريف التشغيل","definition_en":"Expenses incurred in the course of ordinary activities of an entity.","definition_ar":"مصاريف، تُتكبد في مساق الأنشطة الاعتيادية للكيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":573,"en":"Operating Income","ar":"دخل التشغيل","definition_en":"Earnings before Interest and Taxes.","definition_ar":"مدخولات قبل الفوائد و الضرائب.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":574,"en":"Operating Lease","ar":"إيجار التشغيل","definition_en":"A lease that does not meet the criteria for capitalized a lease; accounted for as rental payments.","definition_ar":"إيجار لا يلبي مقاييس رسملة الإيجار؛ و يُحاسب كدفعات استئجارية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":575,"en":"Operating Leverage","ar":"مديونية التشغيل","definition_en":"The percent of fixed costs in a company’s cost structure.","definition_ar":"النسبة المئوية للتكاليف الثابتة في هيكل تكاليف الشركة.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":576,"en":"Operating Loss Carrybacks","ar":"تحميل عاجل لخسائر التشغيل","definition_en":"Reduction of prior years’ taxable income by a current net operating loss.","definition_ar":"تخفيض الدخل الخاضع للضريبة لسنوات سابقة بصافي خسائر التشغيل الحالية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":577,"en":"Operating Loss Carryforward","ar":"تحميل آجل لخسائر التشغيل","definition_en":"Reduction of future years’ taxable income by a current net operating loss.","definition_ar":"تخفيض الدخل الخاضع للضريبة لسنوات مقبلة بصافي خسائر التشغيل الحالية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":578,"en":"Operating Profit","ar":"ربح التشغيل","definition_en":"The profit from a firm’s core ongoing business operation.","definition_ar":"أرباح من تشغيل الأعمال الأساسية و المستمرة لمنشأة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":579,"en":"Operating Profit Margin","ar":"هامش ربح التشغيل","definition_en":"A financial ratio represented as operating profit divided by sales. (Also called Operating Profit Margin Percentage.)","definition_ar":"نسبة مالية، تتمثل في ربح التشغيل مقسوماً على المبيعات. (يسمى أيضاً النسبة المئوية لهامش ربح التشغيل.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":580,"en":"Operational Audit","ar":"تدقيق تشغيلي","definition_en":"A process of obtaining and evaluating evidence about operating procedures and events as compared with established criteria of good performance.","definition_ar":"عملية الحصول على أدلة عن إجراءات و أحداث التشغيل، و تقييمها بمقارنتها مع مقاييس أساسها الأداء الجيد.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":581,"en":"Operational Budget","ar":"موازنة تشغيلية","definition_en":"A plan for the revenues and expenses associated with operating activities of a given period. (Also called Current Budget.)","definition_ar":"خطة للإيرادات و المصاريف مرتبطة مع أنشطة التشغيل لفترة معطاة. (يسمى أيضاً الموازنة الحالية.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":582,"en":"Operational Risk","ar":"مخاطر تشغيلية","definition_en":"Risks resulting from breakdowns in internal procedures, people and systems.","definition_ar":"مخاطر تنتج من انهيارات في الإجراءات الداخلية، و الناس، و الأنظمة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":583,"en":"Operations","ar":"تشغيل","definition_en":"Activities of an entity that deal with producing, delivering and selling goods or services.","definition_ar":"أنشطة الكيان التي تتعامل مع إنتاج، و توصيل، وبيع البضاعة أو الخدمات.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":584,"en":"Opportunity Costs","ar":"تكاليف الفرصة","definition_en":"The value of the forgone alternatives.","definition_ar":"قيمة البدائل التي راحت.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":585,"en":"Option","ar":"خيار","definition_en":"A legal right to buy or sell something at a specific price within in a specified time.","definition_ar":"حق قانوني في شراء أو بيع شيء بسعر محدد ضمن حيز فترة محددة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":586,"en":"Ordering Cost","ar":"تكلفة إعداد طلبية","definition_en":"The cost of preparing a purchase order, and the special processing and receiving costs related to the number of orders processed.","definition_ar":"تكلفة تحضير طلبية شراء، و التكاليف الخاصة بالمعالجة و الاستلام ذات العلاقة بعدد الطلبيات المعالجة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":587,"en":"Organization Structure","ar":"هيكل التنظيم","definition_en":"The arrangement of responsibilities within an entity.","definition_ar":"ترتيب المسؤوليات ضمن حيز الكيان.","topic":"Performance Management","difficulty":"Intermediate"},{"id":588,"en":"Organizational Culture","ar":"ثقافة تنظيمية","definition_en":"The set of key values, beliefs, understanding and norms of an organization.","definition_ar":"مجموعة من القيم، و المعتقدات، و الفهم، و المقاييس الرئيسية لوحدة منظمة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":589,"en":"Organizational Goals","ar":"أهداف تنظيمية","definition_en":"A desired future state that the organization attempts to attain.","definition_ar":"حالة مرغوب بها في المستقبل، تشرع الوحدة المنظمة لتحرزها.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":590,"en":"Output Controls","ar":"ضوابط المخرجات","definition_en":"Output controls ensure that a complete and accurate audit trail of the results of processing is reported to appropriate individuals for review.","definition_ar":"ضوابط مخرجات، تُوكّد على أن خط سير التدقيق مكتمل و دقيق لنتائج العمليات و تقدّم تقارير لمن يتناسب من الأفراد لمراجعته.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":591,"en":"Outsourcing","ar":"تعهيد خارجي","definition_en":"The process of purchasing goods and services from outside vendors rather than producing the same goods or providing the same services within the company.","definition_ar":"عملية شراء البضاعة و الخدمات من موردين خارجيين بدلًا من إنتاج البضاعة نفسها و تقديم الخدمات نفسها ضمن حيز الشركة.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":592,"en":"Outstanding Shares","ar":"حصص معلّقة","definition_en":"Shares of stock that are owned by shareholders rather than by the corporation.","definition_ar":"حصص أسهم، يملكها أصحاب الحصص بدلًا من الشركة العامة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":593,"en":"Overdraft","ar":"سحب على المكشوف","definition_en":"A facility (usually at a bank or other financial institution) enabling an account holder to borrow up to an agreed amount, often for an agreed time.","definition_ar":"تسهيل، (عادة من بنك أو مؤسسة (institution) مالية) يُمكّن صاحب الحساب من الاقتراض حتى مبلغ متفق عليه، و مراراً يكون لزمن متفق عليه.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":594,"en":"Overhead","ar":"فوقية","definition_en":"Indirect costs.","definition_ar":"تكاليف غير مباشرة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":595,"en":"Overhead Allocations","ar":"تخصيص الفوقية","definition_en":"Methods used to assign overhead costs to products, activities, or processes","definition_ar":"طرق، تُستخدم في تكليف التكاليف الفوقية على المنتجات، أو الأنشطة، أو العمليات","topic":"Cost Management","difficulty":"Intermediate"},{"id":596,"en":"Overhead Budget","ar":"موازنة الفوقية","definition_en":"The estimated or planned expenditures of an entity for overhead costs (costs other than those directly related to products or services).","definition_ar":"نفقات مُقدّرة أو مُخطط لها في الكيان للتكاليف الفوقية (من غير التكاليف ذات علاقة المباشرة بالمنتجات أو الخدمات).","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":597,"en":"Overhead Rate","ar":"معدل الفوقية","definition_en":"Ratio of overhead costs for a specific period related to the amount of some measurable causal factor during the same period. (Also called Burden Rate.)","definition_ar":"نسبة التكاليف الفوقية لفترة محددة، تتعلق بمبلغ العامل السببي القابل للقياس أثناء الفترة نفسها. (يسمى أيضاً معدل العبء.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":598,"en":"Owners’ Equity","ar":"مالكي حقوق الملكية","definition_en":"Claims of the owners to the firm’s assets.","definition_ar":"مطالبات المالكين بأصول المنشأة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":599,"en":"Paid-In Capital","ar":"رأس المال المدفوع","definition_en":"The amount paid by investors in exchange for stock. (Also called Contributed Capital.)","definition_ar":"مبلغ، يدفعه المستثمرون كاستبدال للأسهم. (يسمى أيضاً رأس المال المساهم به.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":600,"en":"Par Value","ar":"قيمة وُجهيّة","definition_en":"1. The dollar amount printed on the face of some stock certificates. 2. The face value of a bond.","definition_ar":"1. مبلغ بالدولارات مطبوع على وجه بعض شهادات الأسهم. 2. القيمة الوُجهيّة لصك.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":601,"en":"Participative Budgeting","ar":"إعداد الموازنة بالمشاركة","definition_en":"A type of budgeting that allows managers to participate in the preparation of budgets. (Also called Bottom-Up.)","definition_ar":"نوع من أنواع إعداد الموازنة، يسمح للمدراء بالمشاركة في تحضير الموازنات. (يسمى أيضاً من القاع للأعلى.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":602,"en":"Payback Period","ar":"فترة الاسترجاع","definition_en":"The period of time necessary to recover the cash cost of an investment from the cash inflows attributable to the investment.","definition_ar":"فترة من الزمن ضرورية لتغطية تكلفة النقد في الاستثمار، و تعزى التدفقات الواردة للنقد على أنها من الاستثمار.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":603,"en":"Payroll Cost","ar":"تكلفة كشوف الرواتب","definition_en":"1. Payments to employees for labor services. 2. Taxes and tax-like payments an employer incurs as a legal condition of employment such as unemployment insurance paid to state and federal governments.","definition_ar":"1. دفعات الموظفين لخدمات العمالة. 2. دفعات الضرائب و شبه الضرائب، يتكبدها صاحب العمل كشرط قانوني للتوظيف كتأمين البطالة الذي يُدفع لحكومات الولاية و الحكومة الفيدرالية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":604,"en":"Penetration Pricing","ar":"تسعير الاختراق","definition_en":"Pricing technique of setting a relatively low initial price to attract new customers (a price usually lower than the market price.)","definition_ar":"تقنية تسعير، تضع سعر أولي متدني نسبياً لجذب زبائن جدد (سعر يكون عادة أدنى من سعر السوق.)","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":605,"en":"Penetration Testing","ar":"فحص الاختراق","definition_en":"An authorized test to break into an organization’s information system in order to identify control weaknesses.","definition_ar":"فحص مُصرّح له باقتحام نظام معلومات الوحدة المنظمة من أجل معرفة نقاط ضعف الضوابط.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":606,"en":"Pension","ar":"معاش","definition_en":"An amount given to a person usually after retirement.","definition_ar":"مبلغ، يُعطى للشخص عادة بعد التقاعد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":607,"en":"Percentage-of-Completion Method","ar":"طريقة النسبة المئوية للإنجاز","definition_en":"A method of accounting for long-term construction contracts where revenue and gross profit are recognized each period based upon the progress of the construction.","definition_ar":"طريقة في المحاسبة لعقود أعمال البناء طويلة المدة، يُعترف بها بالإيراد و الربح الإجمالي عن كل فترة على أساس التقدّم في أعمال البناء.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":608,"en":"Performance","ar":"أداء","definition_en":"A general term applied to part or all of the conduct or activities of an entity over a period of time, often with reference to some standard.","definition_ar":"مصطلح عام، يُطبّق على جزء من أو جميع تصرفات أو أنشطة الكيان على امتداد فترة من الزمن، مراراً يشير إلى بعض المعايير.","topic":"Performance Management","difficulty":"Intermediate"},{"id":609,"en":"Performance Evaluation","ar":"تقييم الأداء","definition_en":"A management process of reviewing an employee’s performance over a period of time, comparing that performance to expectations or standards, and communicating the results to the employee.","definition_ar":"عملية إدارية لمراجعة أداء الموظف على امتداد فترة من الزمن، إذ يُقارن الأداء بالتوقعات أو بالمعايير، و يتم التواصل مع الموظف بالنتائج.","topic":"Performance Management","difficulty":"Intermediate"},{"id":610,"en":"Performance Measurement","ar":"قياس الأداء","definition_en":"A quantification of the effectiveness and efficiency with which the objectives of a responsibility center have been accomplished.","definition_ar":"قياس كمي للفاعلية والفعالية، تتم به غايات مركز المسؤولية.","topic":"Performance Management","difficulty":"Intermediate"},{"id":611,"en":"Period Cost","ar":"تكلفة الفترة","definition_en":"An expenditure or loss that is charged to the current period rather than as a cost of the products produced in that period.","definition_ar":"نفقات أو خسائر، تُحمّل على الفترة الحالية بدلًا من أن تكون تكلفة المنتجات المنتجة في تلك الفترة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":612,"en":"Periodic Inventory System","ar":"نظام المخزون الدوري","definition_en":"A method of recordkeeping that involves updating the accounting records at the end of the accounting period.","definition_ar":"طريقة لحفظ السجلات، تتضمن تحديث سجلات المحاسبة عند نهاية فترة المحاسبة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":613,"en":"Permanent Differences","ar":"فروقات دائمة","definition_en":"Difference between accounting income and tax income that will not reverse in later years.","definition_ar":"فرق بين دخل المحاسبة و دخل الضريبة الذي لن يُعكس في سنوات لاحقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":614,"en":"Perpetual Inventory System","ar":"نظام المخزون الدائم","definition_en":"A method of recordkeeping that involves updating the accounting records at the time of every purchase, sale, and return.","definition_ar":"طريقة لحفظ السجلات، تتضمن تحديث سجلات المحاسبة عند كل بيع، و شراء، و عائد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":615,"en":"PEST Analysis","ar":"(PEST) تحليل","definition_en":"A method of analyzing external factors, including Political, Economic, Social and Technological.","definition_ar":"طريقة لتحليل العوامل الخارجية، تشمل السياسية، و الاقتصادية، و الاجتماعية، و التكنولوجية.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":616,"en":"Phishing","ar":"تصيّد","definition_en":"An email from someone who falsely claims to be an established, legitimate company.","definition_ar":"رسالة إلكترونية من شخص ما يدّعي زوراً أنه شركة مؤسسة، و مشروعة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":617,"en":"Physical Inventory","ar":"مخزون عيني","definition_en":"A physical count of all inventories on hand.","definition_ar":"عد عيني لجميع المخزون الذي في اليد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":618,"en":"Plant","ar":"معمل","definition_en":"Land, buildings, machinery, equipment, furniture and other fixed assets used to produce products.","definition_ar":"الأرض، و المباني، و الآلات، و المعدات، و الأثاث وغيرها من الأصول الثابتة المستخدمة في إنتاج المنتجات.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":619,"en":"Plant-Wide Overhead","ar":"فوقية على اتساع المعمل","definition_en":"A single overhead rate for an entire plant used to allocate overhead costs to products produced in the plant.","definition_ar":"معدل الفوقية المنفرد لمعمل بأكمله، يُستخدم في تخصيص التكاليف الفوقية على المنتجات المنتجة في المعمل.","topic":"Cost Management","difficulty":"Intermediate"},{"id":620,"en":"Political Risk","ar":"مخاطر السياسة","definition_en":"The risk of loss when investing in a given country caused by changes in a country’s political structure or policies, such as tax laws, tariffs, expropriation of assets, or repatriation of profits restrictions.","definition_ar":"مخاطر الخسارة عند الاستثمار في دولة بعينها بسبب تغيرات في الهيكل السياسي، أو السياسات، كقوانين الضرائب، أو التعرفات، أو مصادرة الأصول، أو قيود على عودة الأرباح للوطن.","topic":"Risk Management","difficulty":"Intermediate"},{"id":621,"en":"Porter’s Five Forces","ar":"قوى بورتر الخمس","definition_en":"A method of analyzing external factors. Three “horizontal” forces: the threat of substitute products or services, the threat of established rivals, and the threat of new entrants; and two “vertical” forces: bargaining power of suppliers, and bargaining power of customers.","definition_ar":"طريقة لتحليل العوامل الخارجية. ثلاثة قوى “أفقية”: تهديد بإبدال المنتجات أو الخدمات، و تهديد من غرماء المؤسسين، و تهديد من الداخلين الجدد؛ و اثنين من القوى”عمودية”: قوة المفاصلة عند الموردين، و قوة المفاصلة عند الزبائن.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":622,"en":"Portfolio","ar":"محفظة","definition_en":"A group of investments held by an institution or individual.","definition_ar":"مجموعة استثمارات، تمسكها مؤسسة (institution) أو فرد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":623,"en":"Post-Audit","ar":"بعد التدقيق","definition_en":"A set of procedures for evaluating the results of a capital budgeting project.","definition_ar":"مجموعة إجراءات لتقييم نتائج مشروع إعداد موازنة رأس المال.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":624,"en":"Post-Retirement Benefits","ar":"منافع بعد التقاعد","definition_en":"Payments to which former employees may be entitled once they are no longer employed, including pension benefits, death benefits, health benefits, and life insurance.","definition_ar":"دُفعات، يمكن أن يكون لموظفين سابقين أحقية فيها بمجرد أن لا يعودوا موظفين، تشمل منافع المعاش، و منافع الوفاة، و منافع الصحة، و تأمين الحياة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":625,"en":"Practical Capacity","ar":"طاقة الإنتاج العملية","definition_en":"Measure of capacity that is the maximum level at which the plant or department can operate efficiently.","definition_ar":"قياس طاقة الإنتاج التي هي أقصى مستوى للتشغيل بفعالية في معمل أو دائرة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":626,"en":"Predictive Analytics","ar":"تحليل تنبؤي","definition_en":"Set of techniques used to make predictions about unknown future events.","definition_ar":"مجموعة من التقنيات، تُستخدم في عمل التنبؤات عن أحداث غير معروفة في المستقبل.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":627,"en":"Preferred Stock","ar":"أسهم ممتازة","definition_en":"Capital stock that provides a fixed dividend paid before any dividends are paid to common shareholders. It takes precedence over common stock in the event of liquidation.","definition_ar":"أسهم رأس المال، تُوفر توزيع أرباح ثابت يُدفع قبل دفع أي توزيع أرباح لأصحاب حصص الأسهم العادية. و تأخذ الأسبقية على الأسهم العادية إذا حدثت تصفية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":628,"en":"Premium","ar":"علاوة","definition_en":"The extra amount paid for a security over and above its intrinsic or par value.","definition_ar":"مبلغ إضافي، يُدفع في ورقة مالية و هو يعلو و يفوق قيمتها الجوهرية أو الوُجهيّة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":629,"en":"Premium on Bonds Payable","ar":"علاوة على الحسابات الدائنة للصكوك","definition_en":"The difference between the face value of the bonds and its selling price when the selling price is greater than the face value.","definition_ar":"الفرق بين القيمة الوُجهيّة للصكوك و سعر بيعها عندما يكون سعر البيع أكبر من القيمة الوُجهيّة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":630,"en":"Premium Pricing","ar":"تسعير العلاوة","definition_en":"The practice of setting a price artificially high in order to encourage a perception of exclusivity or status appeal.","definition_ar":"مزاولة وضع سعر عالٍ اصطناعياً من أجل تشجيع المنظور الحصري أو الوضع المستميل.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":631,"en":"Prepaid Expenses","ar":"مصاريف مدفوعة مقدماً","definition_en":"Payments made for services to be received after the date of payment.","definition_ar":"دفعات، تتم لخدمات ستستلم بعد تاريخ الدفع.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":632,"en":"Prescriptive Analytics","ar":"تحليل توصيفي","definition_en":"Set of techniques used to discover the best course of action for a given situation.","definition_ar":"مجموعة من التقنيات، تستخدم لاستكشاف أفضل مساقات العمل في وضعية معطاة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":633,"en":"Present Value","ar":"قيمة حالية","definition_en":"The value today (or at some specific date) of an amount or amounts to be paid or received later (or at other, different dates), discounted at some discount rate.","definition_ar":"قيمة اليوم (أو في تاريخ ما محدد) لمبلغ أو مبالغ ستدفع أو ستستلم لاحقاً (أو في، تواريخ أخرى مختلفة)، مخصومةً بمعدل الخصم.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":634,"en":"Prevention Costs","ar":"تكاليف الوقاية","definition_en":"Costs incurred by an entity to prevent defects in the products or services it produces. Examples include inspection, design, and quality training.","definition_ar":"تكاليف، يتكبدها الكيان لمنع عيوب في المنتجات أو الخدمات التي ينتجها. و تشمل الأمثلة التفتيش، و التصميم، و نوعية التدريب.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":635,"en":"Price Elasticity of Demand","ar":"مرونة سعر الطلب","definition_en":"The percentage change in the quantity of a product demanded divided by the percent change in its price. It indicates the degree of consumer response to a variation in price.","definition_ar":"النسبة المئوية للتغير في كمية المنتج المطلوب مقسوماً على النسبة المئوية للتغير في سعره. مما يشير لدرجة استجابة الزبون لتغير في السعر.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":636,"en":"Price Variance","ar":"انحراف السعر","definition_en":"The difference between actual price and budgeted price multiplied by the actual quantity of input. (Also called Rate Variance or Sales Price Variance.)","definition_ar":"الفرق بين السعر الفعلي و سعر الموازنة مضروباً في الكمية الفعلية للمدخلات. (يسمى أيضاً معدل الانحراف أو انحراف سعر المبيعات)","topic":"Performance Management","difficulty":"Intermediate"},{"id":637,"en":"Price/Earnings (P/E) Ratio","ar":"نسبة السعر الدخل (P/E)","definition_en":"Current Market Price per share divided by Earnings per share.","definition_ar":"سعر السوق الحالي لكل حصة مقسوماً على الدخل لكل حصة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":638,"en":"Price-to-Book Ratio","ar":"نسبة السعر إلى الدفتر","definition_en":"Current Market Price per share divided by Net Book Value per share. (Also called Market-to-Book Ratio.)","definition_ar":"سعر السوق الحالي لكل حصة مقسوماً على صافي قيمة الدفتر لكل حصة. (يسمى أيضاً نسبة السوق إلى الدفتر.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":639,"en":"Pricing","ar":"تسعير","definition_en":"The process of determining the amount to charge customers for products or services.","definition_ar":"عملية تحديد مبلغ ما كثمن للزبائن على المنتجات أو الخدمات.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":640,"en":"Prime Cost","ar":"تكلفة رئيسية","definition_en":"The cost of direct materials and direct labor.","definition_ar":"تكلفة المواد المباشرة و العمالة المباشرة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":641,"en":"Pro Forma Statements","ar":"قوائم صورية","definition_en":"1. Financial statements that have one or more assumptions or hypothetical situations built into the data. 2. Budgeted balance sheets and income statements are sometimes referred to as pro forma statements.","definition_ar":"1. قوائم مالية فيها واحد أو أكثر من الافتراضات أو الوضعيات الفرضية المبنية في البيانات. 2. موازنة الميزانيات العمومية و قوائم الدخل، يُشار إليها في بعض الأوقات بقوائم صورية.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":642,"en":"Probability","ar":"احتمالية","definition_en":"The likelihood or chance of occurrence of an event.","definition_ar":"ترجيح أو فرص حدوث حدث ما.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":643,"en":"Probability Distribution","ar":"توزيع الاحتمالية","definition_en":"A collection of data that shows all the values that the random variable can take and the likelihood that each will occur.","definition_ar":"حصيلة بيانات، تستعرض جميع القيم الممكن أخذها كمتغير عشوائي و ما هو مرجح لحدوث كل منها.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":644,"en":"Process Analysis","ar":"تحليل العمليات","definition_en":"The review of business processes including definition, monitoring, measurement, and reporting with the goal of improving processes to meet customer requirements profitably.","definition_ar":"مراجعة عمليات الأعمال، تشمل التّعريف، و الرّصد، و القياس، و إعداد التقارير بهدف تحسين العمليات كي تلبي متطلبات الزبائن بربحية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":645,"en":"Process Costing","ar":"احتساب تكاليف العمليات","definition_en":"A method of allocating manufacturing cost to mass- produced identical or similar products to determine an average cost per unit. Each unit receives the same manufacturing input as every other unit. Refineries, paper mills, and food processing companies are examples that use process costing.","definition_ar":"طريقة لتخصيص تكلفة تصنيع منتجات متطابقة أو متشابهة، تُنتج أفواجاً، لتحديد متوسط تكلفة كل وحدة. و كل وحدة، تستلم نفس مدخلات التصنيع كأي وحدة أخرى. مصافي التكرير، و معامل الورق، و شركات معالجة الغذاء هي أمثلة على استخدام احتساب تكاليف العمليات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":646,"en":"Processing Controls","ar":"ضوابط المعالجة","definition_en":"Controls on the processing stage of an information system, including Run-to-Run controls, Operator Intervention controls, and Audit Trail controls.","definition_ar":"ضوابط في مرحلة المعالجة لنظام معلومات، تشمل ضوابط من تشغيل إلي تشغيل، و ضوابط تَدخُّل المشغّل، و ضوابط خط سير التدقيق.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":647,"en":"Procurement Policies","ar":"سياسات الاشتراء","definition_en":"Rules and regulations to govern the process of acquiring goods and services needed by an organization in order to function efficiently.","definition_ar":"قواعد و لوائح، تَحكُم عملية استحواذ البضاعة و الخدمات التي تحتاج إليها الوحدة المنظمة من أجل مسارات عمل ذات فعالية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":648,"en":"Product Cost","ar":"تكلفة المنتج","definition_en":"The direct material, direct labor, and production overhead cost of a product.","definition_ar":"تكاليف المواد المباشرة، و العمالة المباشرة، و التكلفة الفوقية لإنتاج المنتج.","topic":"Cost Management","difficulty":"Intermediate"},{"id":649,"en":"Product Life-Cycle","ar":"دورة حياة المنتج","definition_en":"The time span between the initial concept of a product or service and the time when the entity no longer produces the product. Stages are Introduction, Growth, Maturity, & Decline.","definition_ar":"مدة زمنية بين المفهوم الأولي للمنتج أو الخدمة و الوقت الذي عنده لا يعاود الكيان إنتاج المنتج. و المراحل هي المقدمة، و النمو، و النضج، و التراجع.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":650,"en":"Product Line","ar":"خط المنتج","definition_en":"A grouping of similar products.","definition_ar":"تجميع المنتجات المشابهة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":651,"en":"Product Mix","ar":"مزيج المنتج","definition_en":"The array of products offered for sale by a company.","definition_ar":"صفيفة من منتجات الشركة المطروحة للبيع.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":652,"en":"Production Budget","ar":"موازنة الإنتاج","definition_en":"The planned cost of producing goods during a given period.","definition_ar":"تكلفة مخطط لها لإنتاج بضاعة أثناء فترة معطاة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":653,"en":"Production Costs","ar":"تكاليف الإنتاج","definition_en":"The material, labor, and overhead cost of producing products and services. Excludes distribution and selling costs. (Also called Manufacturing Cost.)","definition_ar":"تكلفة المواد، و العمل، و الفوقية لإنتاج المنتجات و الخدمات. و يستبعد منها تكاليف التوزيع و البيع. (يسمى أيضاً تكلفة التصنيع.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":654,"en":"Production Volume Variance","ar":"انحراف حجم الإنتاج","definition_en":"The difference between budgeted fixed overhead and applied fixed overhead.","definition_ar":"الفرق بين الفوقية الثابتة من الموازنة و الفوقية الثابتة من التطبيق.","topic":"Performance Management","difficulty":"Intermediate"},{"id":655,"en":"Productivity","ar":"إنتاجية","definition_en":"The relationship between output and inputs; i.e., the effectiveness of using particular inputs (e.g., labor) to produce an output.","definition_ar":"علاقة بين المخرجات و المدخلات؛ أي، الفاعلية في استخدام مدخلات معينة (مثل، العمالة) لإنتاج مُخرج ما.","topic":"Performance Management","difficulty":"Intermediate"},{"id":656,"en":"Profit Center","ar":"مركز ربح","definition_en":"A responsibility center whose financial performance is measured by the difference between its revenue and its expenses or cost.","definition_ar":"مركز مسؤولية، يُقاس أداؤه المالي بالفرق بين إيراده و مصاريفه أو تكلفته.","topic":"Performance Management","difficulty":"Intermediate"},{"id":657,"en":"Profit Margin","ar":"هامش الربح","definition_en":"The profit margin on sales; net income as a percent of sales revenue.","definition_ar":"هامش الربح على المبيعات؛ هو صافي الدخل كنسبة مئوية من إيراد المبيعات.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":658,"en":"Profit Plan","ar":"خطة الربح","definition_en":"A schedule of planned or expected revenues, expenses, assets, and liabilities. A profit plan provides guidelines for future operations and appraisal of performance. (Also called Budget.)","definition_ar":"جدول للإيرادات، و المصاريف، و الأصول، و المطلوبات حسب ما هو مخطط أو متوقع. و توفّر خطة الربح إرشادات لمستقبل التشغيل و تقويم الأداء. (يسمى أيضاً الموازنة.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":659,"en":"Profitability Analysis","ar":"تحليل الربحية","definition_en":"An analysis performed to determine whether a specific product, group of products, or an entire entity is making a profit.","definition_ar":"تحليل، يُؤدى لتحديد ما إذا كان المحدد من منتج، أو مجموعة منتجات، أو كيان بأكمله يَجني أرباحاً.","topic":"Performance Management","difficulty":"Intermediate"},{"id":660,"en":"Profitability Index","ar":"مؤشر الربحية","definition_en":"A measure used in capital budgeting to rank projects, calculated as the present value of the future cash flows from an investment divided by the initial investment. (Also called the benefit-cost ratio.)","definition_ar":"قياس، يُستخدم في إعداد موازنة رأس المال و عمل رتب للمشروعات، و يُحتسب من القيمة الحالية لتدفقات النقد في المستقبل من الاستثمار مقسوماً على الاستثمار الأولي. (يسمى أيضاً نسبة المنفعة للتكلفة.)","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":661,"en":"Program Budget","ar":"موازنة البرنامج","definition_en":"A budget that is structured to show the expenses (and often revenues) of the principal programs that the entity will undertake.","definition_ar":"موازنة، تُهيكَل لتستعرض مصاريف (و مراراً الإيرادات) سيتعهدها الكيان لأصل دين برنامج ما.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":662,"en":"Progress Payment","ar":"دفعات قيد التقدّم","definition_en":"A payment of an interim billing based upon partial completion of a contract.","definition_ar":"دفع أذون وقتية على أساس اكتمال جزئي من العقد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":663,"en":"Project Budget","ar":"موازنة مشروع","definition_en":"A budget of costs classified by resources & function for a specific project over the project’s life, which may span several operating budget time periods.","definition_ar":"موازنة تكاليف، تُصنّف موارد و مسارات عمل مشروع محدد خلال مدة المشروع، الذي يمكن أن تستغرق موازنة تشغيله عدة فترات زمنية.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":664,"en":"Promissory Note","ar":"كمبيالة","definition_en":"A signed statement promising to pay to a specified person or the bearer a particular sum of money on a fixed date or on demand.","definition_ar":"بيان مُوقّع فيه وعد لشخص محدد أو لحامله بدفع حاصل جمع مال معين في تاريخ ثابت أو عند الطلب.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":665,"en":"Property, Plant, and Equipment (PP&E)","ar":"ممتلكات، و معمل، و معدات (PP&E)","definition_en":"A balance sheet classification for fixed assets used in business operations. Property, plant, and equipment items are normally grouped and reported at acquisition cost using separate disclosure of accumulated depreciation or depletion. (Also called Plant Assets, Operational Assets, or Fixed Assets.)","definition_ar":"تصنيف الميزانية العمومية للأصول الثابتة المستخدمة في تشغيل الأعمال. و عادةً تُجمّع بنود الممتلكات، و المعمل، و المعدات و يُعد بها تقرير حسب تكلفة الاستحواذ باستخدام إفصاح منفصل للاهتلاك المتراكم أو النفاذ. (يسمى أيضاً أصول المعمل، أو أصول تشغيلية، أو أصول ثابتة.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":666,"en":"Prorate","ar":"توزيع بالنسب","definition_en":"To allocate; to charge an indirect cost to the several cost objects that are assumed to have caused this cost.","definition_ar":"تخصيص؛ بتثمين تكلفة غير مباشرة لعدة مواد تكلفة أخذت على عاتقها سبب تلك التكلفة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":667,"en":"Protectionism","ar":"حمائية","definition_en":"Steps taken by countries to protect their domestic industries from foreign competition.","definition_ar":"خطوات تتخذها الدول لحماية صناعاتها الوطنية من المنافسة الأجنبية.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":668,"en":"Provision","ar":"تدابير","definition_en":"Estimated liability or expense when the exact amount is not known.","definition_ar":"تقدير المطلوبات أو المصاريف عندما لا يعرف المبلغ بالضبط.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":669,"en":"Proxy","ar":"مفوّض","definition_en":"Authorization given by one person to another so the second person can act for the first. Often used by shareholders to authorize management to vote shares of stock.","definition_ar":"تصريح، يُعطى من شخص لآخر ليتسنى للشخص الثاني التصرف عن الأول. مراراً، يَستخدمه أصحاب الحصص عندما تُصرّح الإدارة للتصويت بحسب حصص الأسهم.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":670,"en":"Public Company","ar":"شركة عامة","definition_en":"A company that has issued securities through an offering & which are now traded on the open market. (Also called publicly-held or publicly-traded company.)","definition_ar":"شركة، أصدرت أوراق مالية من خلال الطرح، و هي الآن متداولة في سوق مفتوح. (يسمى أيضاً ملكية عامة أو شركة تداول عام.)","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":671,"en":"Public Company Accounting Oversight Board (PCAOB)","ar":"مجلس مراقبة محاسبة الشركات العامة (PCAOB)","definition_en":"A board established by the U.S. Sarbanes-Oxley Act of 2002 which regulates the auditing profession and sets standards for audits of public companies.","definition_ar":"مجلس، تَأسس بقانون ساربينز أوكسلي سنة 2002 في الولايات المتحدة ليُخضع للوائح مهنة التدقيق و ليضع معايير التدقيق للشركات العامة.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":672,"en":"Purchase Returns and Allowances","ar":"مسموحات و عائدات المشتريات","definition_en":"Amounts that decrease the cost of inventory purchases due to returned or damaged merchandise.","definition_ar":"مبالغ، تُنقص من تكلفة مشتريات المخزون جرّاء عائدات أو خراب البضائع.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":673,"en":"Pure Competition","ar":"منافسة نقيّة","definition_en":"A model of industrial structure characterized by a large number of small firms producing a homogeneous product in an industry (market) that permits complete freedom of entry and exit.","definition_ar":"نموذج لهيكل صناعي بخاصية العدد الكبير من المنشآت الصغيرة، تُنتج منتجاً متجانساً في الصناعة (السوق) مما يسمح بالدخول و الخروج من السوق بحرية تامة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":674,"en":"Put Option","ar":"خيار البيع","definition_en":"An option to sell a particular asset within a specified period of time for a specified price.","definition_ar":"خيار لبيع أصل معين ضمن حيز فترة من الزمن محددة و بسعر محدد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":675,"en":"Qualitative Factors","ar":"عوامل نوعية","definition_en":"Factors that are relevant to a decision but which cannot be expressed numerically.","definition_ar":"عوامل ذات علاقة بقرار ما و لكن لا يمكن التعبير عنها عددياً.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":676,"en":"Quality","ar":"نوعية","definition_en":"The extent to which a product or service conforms to specifications or provides customers the characteristics that were promised.","definition_ar":"مدى التوافق مع مواصفات المنتج أو الخدمة أو توفير الخصائص التي وُعد بها الزبائن.","topic":"Cost Management","difficulty":"Intermediate"},{"id":677,"en":"Quality Assurance","ar":"تأكيد النوعية","definition_en":"The function responsible for providing assurance that products or services are consistently maintained at a high level of quality.","definition_ar":"مسار العمل المسؤول عن توفير تأكيد متسق عن حفظ مستوى عالٍ من نوعية المنتجات أو الخدمات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":678,"en":"Quality Control","ar":"ضوابط النوعية","definition_en":"A process, such as statistical sampling, that monitors the quality of operations.","definition_ar":"عملية، كأخذ العينات الإحصائية، لرصد نوعية التشغيل.","topic":"Cost Management","difficulty":"Intermediate"},{"id":679,"en":"Quality of Earnings","ar":"نوعية المدخولات","definition_en":"Refers to how well a reported earnings number communicates the firm’s true performance.","definition_ar":"تشير لصحة رقم المدخولات الذي في التقرير للتواصل به عن حقيقة أداء المنشأة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":680,"en":"Quantity Discount","ar":"خصم الكمية","definition_en":"An allowance given by a seller to a buyer because of the size of an individual purchase transaction or the total size during a specified period.","definition_ar":"مسموحات، يُعطيها البائع للمشتري بسبب مقاس أحد معاملات الشراء أو بسبب مجموع مقاسات عدة معاملات أثناء فترة محددة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":681,"en":"Quick Ratio","ar":"نسبة سريعة","definition_en":"A ratio that measures an entity’s ability to pay off short- term obligations using the most liquid current assets (excluding inventory). (Also called Acid-Test Ratio.)","definition_ar":"نسبة لقياس مقدرة الكيان على دفع الالتزامات القصيرة المدة باستخدام أكثر الأصول الجارية سيولة (باستبعاد المخزون). (يسمى أيضاً نسبة السيولة السريعة.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":682,"en":"Quotas","ar":"كوتا","definition_en":"Limits on the amount of a good produced, imported into the country, exported, or offered for sale.","definition_ar":"تَحدُّ من مبلغ البضاعة المنتجة، أو المستوردة إلى الدولة، أو المصدرة، أو المطروحة للبيع.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":683,"en":"Random Variable","ar":"متغير عشوائي","definition_en":"A quantity, resulting from measurement of a random process, that varies, but whose statistical distribution can be determined.","definition_ar":"كمية، تنتج من قياس عملية عشوائية، و تتغير، و لكن يمكن تحديد توزيعها الإحصائي.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":684,"en":"Rate of Return","ar":"معدل العائد","definition_en":"A measure of the cash flows from an investment compared to the amount of the investment.","definition_ar":"قياس تدفقات النقد من الاستثمار مقارنة بمبلغ الاستثمار.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":685,"en":"Ratio Analysis","ar":"تحليل النسب","definition_en":"The calculation of significant financial and other ratios and the comparison of these ratios with those of prior years, industry averages, or standards.","definition_ar":"احتساب نسب مالية و غيرها من النسب ذات الأهمية، و تُقارن النسب مع تلك في السنوات السابقة، أو بمتوسطات الصناعة، أو المعايير.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":686,"en":"Real Option","ar":"خيار حقيقي","definition_en":"An alternative or choice that becomes available with a business investment opportunity. For example, by investing in a particular project, a company may have the real option of expanding, downsizing, or abandoning other projects in the future. A value can be calculated using option pricing models.","definition_ar":"بديل أو اختيار، يصبح متاحاً مع فرص استثمار الأعمال. على سبيل المثال، بالاستثمار في مشروع معين، يمكن للشركة أن يكون لديها خيار حقيقي بالتوسع، أو التقلص، أو التخلي عن مشاريع أخرى في المستقبل. و يمكن احتساب القيمة باستخدام نماذج تسعير الخيار.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":687,"en":"Realize","ar":"محقق","definition_en":"Converting non-cash resources and rights into money, used in accounting and financial reporting to refer to sales of assets for cash or claims to cash.","definition_ar":"تحويل الموارد الغير نقدية و الحقوق إلى مال، يستخدم في إعداد تقارير المحاسبة والمالية للإشارة إلى مبيعات الأصول نقداً أو المطالبات بالنقد.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":688,"en":"Receivable","ar":"حساب مدين","definition_en":"An amount owed to an entity, whether or not it is currently due.","definition_ar":"مبلغ مدين للكيان، سواء كان يستحق حاليا أم لا.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":689,"en":"Reciprocal Allocation Method","ar":"طريقة التخصيص التبادلي","definition_en":"A method for allocating service department costs by including the mutual services rendered among all departments.","definition_ar":"طريقة لتخصيص تكاليف دائرة الخدمات بأن تشمل الخدمات المتبادلة التي أسديت لكافة الدوائر.","topic":"Cost Management","difficulty":"Intermediate"},{"id":690,"en":"Recognition","ar":"اعتراف","definition_en":"The process of formally recording an item in an entity’s financial statements.","definition_ar":"عملية التسجيل الرسمي لبند في القوائم المالية للكيان.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":691,"en":"Reconciliation","ar":"مصالحة","definition_en":"A schedule or calculation showing how one amount is derived from another amount.","definition_ar":"جدول أو احتساب، يستعرض كيف يُستمد مبلغ من مبلغ آخر.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":692,"en":"Record Retention Schedule","ar":"جدول الاحتفاظ بالسجلات","definition_en":"A policy that defines how long data should be kept before it is destroyed.","definition_ar":"سياسة، تُعرّف بطول المدة التي ينبغي فيها المحافظة على البيانات قبل تدميرها.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":693,"en":"Recourse","ar":"حق الرجوع","definition_en":"The rights of a lender if a borrower does not repay as promised.","definition_ar":"حقوق المقرض إذا المقترض لم يتم الدفع حسب الوعد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":694,"en":"Reengineering","ar":"إعادة الهندسة","definition_en":"A technique used to make improvements within an organization, focusing on identifying and abandoning outdated rules and fundamental assumptions. The end result is a new work method to achieve organizational goals within production, support, or decision-making processes.","definition_ar":"تقنية، تُستخدم في عمل تحسينات ضمن حيز الوحدة المنظمة، بالتركيز على التعريف و التخلي عن القواعد و الافتراضات الأساسية القديمة. النتيجة النهائية هي طريقة عمل جديدة لإنجاز الأهداف التنظيمية ضمن حيز عمليات الإنتاج، أو المساندة، أو صنع القرار.","topic":"Cost Management","difficulty":"Intermediate"},{"id":695,"en":"Regression Analysis","ar":"تحليل الانحدار","definition_en":"A statistical analysis tool that quantifies the relationship between a dependent variable and one or more independent variables.","definition_ar":"أداة تحليل إحصائي، تقيس كمياً العلاقة بين متغير تابع و متغير مستقل واحداً أو أكثر.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":696,"en":"Regression Equation","ar":"معادلة الانحدار","definition_en":"A statistical technique used to explain or predict the behavior of a dependent variable, taking the form of Y = a + bx + c, where Y is the dependent variable that the equation tries to predict, x is the independent variable that is being used to predict Y, a is the Y-intercept of the line, and c is a value called the regression residual.","definition_ar":"تقنية إحصائية، تُستخدم لشرح أو للتنبؤ بسلوك متغير تابع، و تأخذ الشكل Y = a + bx + c، إذ Y هو المتغير التابع الذي تحاول المعادلة التنبؤ به، و x هو المتغير المستقل الذي يستخدم للتنبؤ بـ Y، و a هو التقاطع مع الخط c، و هي قيمة تسمى متبقي الانحدار.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":697,"en":"Reinvestment Rate","ar":"معدل إعادة الاستثمار","definition_en":"The rate of return at which cash flows from an investment are expected to be reinvested.","definition_ar":"معدل عائد، يُتوقّع عنده إعادة استثمار تدفقات النقد من الاستثمار.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":698,"en":"Relative Sales Value Method","ar":"طريقة قيمة المبيعات النسبية","definition_en":"A method used to allocate joint costs in proportion to the sales value of joint products produced.","definition_ar":"طريقة، تُستخدم في تخصيص التكاليف المشتركة كنسب من قيمة مبيعات المنتجات المشتركة التي تنتج.","topic":"Cost Management","difficulty":"Intermediate"},{"id":699,"en":"Relativist","ar":"نسبي","definition_en":"A moral philosophy that states that morality is relative to one’s culture.","definition_ar":"فلسفة معنوية، يرد فيها أن المعنويات تكون نسبية حسب ثقافة المرء.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":700,"en":"Relevance","ar":"ملائمة","definition_en":"The capacity of information to make a difference in a decision by helping users to form predictions about the outcomes of past, present, and future events or to confirm or correct prior expectations.","definition_ar":"الطاقة الإنتاجية للمعلومات لعمل فرق في القرارات، تساعد المستخدمين على التنبّؤ بنتائج لأحداث في الماضي، و الحاضر، و المستقبل أو على تثبيت أو تصحيح توقعات سابقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":701,"en":"Relevant Cost","ar":"تكلفة ذات علاقة","definition_en":"A cost that should be considered in choosing among alternatives. Only those costs yet to be incurred (future costs) that differ among the alternatives (differential costs) are relevant in decision making.","definition_ar":"تكلفة، ينبغي النظر بها عند الاختيار من بين البدائل. و فقط التكاليف التي ستتكبد (تكاليف المستقبل)، تختلف بين البدائل (تكاليف تفاضلية) و هي ذات علاقة بصنع القرار.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":702,"en":"Relevant Range","ar":"مدى ذو العلاقة","definition_en":"The range of economic activity within which estimates and predictions are valid.","definition_ar":"مدى النشاط الاقتصادي الذي ضمن حيزه يسري مفعول التقديرات والتنبؤات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":703,"en":"Reliability","ar":"اعتمادية","definition_en":"The quality of information that assures that information is reasonably free from error and bias and faithfully represents what it purports to represent.","definition_ar":"نوعية المعلومات، تؤكد على خلو المعلومات بحد معقول من الخطأ و التحيّز و أنها تُمثل بإخلاص ما ترمي لتمثيله.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":704,"en":"Reorder Point","ar":"نقطة إعادة الطلبية","definition_en":"The quantity level of an inventory item that triggers an order to replenish the item.","definition_ar":"مستوى كمية المخزون الذي يقدح زناد طلبية بندٍ ما لسد نقص هذا البند.","topic":"Cost Management","difficulty":"Intermediate"},{"id":705,"en":"Reorganization","ar":"إعادة التنظيم","definition_en":"1. A financial restructuring of an organization, such as bankruptcy. 2. A restructuring of a firm’s operations in order to focus on core activities and outsource others.","definition_ar":"1. إعادة الهيكلة المالية لوحدة منظمة، كالإفلاس. 2. إعادة هيكلة العمليات في المنشأة من أجل التركيز على الأنشطة الأساسية و التعهيد الخارجي لغيرها.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":706,"en":"Repair","ar":"تصليح","definition_en":"The activity of putting assets back into normal or expected operating condition without an increase in the asset’s previously estimated service life.","definition_ar":"نشاط، يعيد وضع الأصول إلى حالة التشغيل العادية أو المتوقعة بدون زيادة في عمر خدمة الأصل المقدّرة مسبقاً.","topic":"Cost Management","difficulty":"Intermediate"},{"id":707,"en":"Replacement Cost","ar":"تكلفة الإحلال","definition_en":"The cost to replace currently owned assets.","definition_ar":"تكلفة إحلال أصول مملوكة حالياً.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":708,"en":"Reporting Currency","ar":"عملة إعداد التقارير","definition_en":"The currency in which an entity prepares its financial statements.","definition_ar":"عملة، يُحضّر بها الكيان قوائمه المالية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":709,"en":"Repurchase Agreement","ar":"اتفاق إعادة الشراء","definition_en":"A contract in which the seller of securities, such as Treasury Bills, agrees to buy them back at a specified time and price. (Also called Repo or Buyback.)","definition_ar":"عقد فيه بائع الأوراق المالية، كأذون الخزانة، يوافق على إعادة شرائهم في وقت و سعر محددين. (يسمى أيضاً (Repo) أو إعادة الشراء.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":710,"en":"Required Rate of Return","ar":"معدل العائد المطلوب","definition_en":"The minimum acceptable rate of return on an investment. (Also called Hurdle Rate.)","definition_ar":"أدنى معدل عائد مقبول على الاستثمار. (يسمى أيضاً معدل حدي.)","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":711,"en":"Required Reserves","ar":"احتياطيات مطلوبة","definition_en":"The minimum amount of funds that a bank is required by law to keep on hand in order to back-up its deposits.","definition_ar":"أدنى مبلغ من الأموال بالقانون، يُتطلب من البنك المحافظة عليه من أجل دعم ودائعه.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":712,"en":"Research and Development Cost","ar":"تكاليف البحث و التطوير","definition_en":"Outlays made in an attempt to discover new knowledge (research) or to use the results of research to develop new or improved products or processes (development).","definition_ar":"استنفاقات، تتم عند الشروع في اكتشاف معرفة جديدة (بحث) أو لاستخدام نتائج البحث في تطوير منتجات أو عمليات جديدة أو محسّنة (تطوير).","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":713,"en":"Reserve","ar":"احتياطي","definition_en":"A term used primarily to segregate part of retained earnings, such as for a reserve for contingencies.","definition_ar":"مصطلح، يُستخدم في المقام الأول عند فصل جزء من الدخل المحتجز، كاحتياطي للعوارض.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":714,"en":"Residual Income","ar":"دخل متبقي","definition_en":"A means of measuring performance of an investment center that stresses profit responsibility and the financial management efficiency of the investment center manager. Residual income is typically calculated as the difference between investment center profits and a charge for capital resources committed to the unit.","definition_ar":"وسيلة لقياس أداء مركز الاستثمار، تحثّ مدير مركز الاستثمار على مسؤولية الربح و فعالية الإدارة المالية. و نموذجياً، يحتسب الدخل المتبقي بالفرق بين أرباح مركز الاستثمار و ثمن الموارد الرأسمالية المخصصة له كوحدة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":715,"en":"Residual Risk","ar":"مخاطر متبقية","definition_en":"The risk remaining after controls have been put in place to mitigate the inherent risk; or, the exposure to loss after all known risks have been mitigated.","definition_ar":"الباقي من المخاطر بعد وضع الضوابط في مكانها لتخفيف المخاطر الكامنة؛ أو، هي التّعرض للخسارة بعد تخفيف جميع المخاطر المعروفة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":716,"en":"Resource Allocation","ar":"تخصيص الموارد","definition_en":"A plan for using available resources, such as human resources, especially in the near term, to achieve goals for the future; the allocation of resources among the various projects or business units.","definition_ar":"خطة لاستخدام الموارد المتاحة، على سبيل المثال الموارد البشرية، بالأخص في مدة قريبة، لإنجاز أهداف للمستقبل؛ أي تخصيص الموارد بين مختلف المشاريع أو وحدات الأعمال.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":717,"en":"Resource Driver","ar":"محرك الموارد","definition_en":"A measure of the quantity of resources consumed by an activity (e.g., floor space occupied by the activity).","definition_ar":"قياس لكمية الموارد المستهلكة من النشاط (مثل، مساحة الطابق الذي يشغله النشاط).","topic":"Cost Management","difficulty":"Intermediate"},{"id":718,"en":"Responsibility Accounting","ar":"محاسبة المسؤولية","definition_en":"A system of accounting that assigns revenues, costs, and/or capital to units of an enterprise (responsibility centers).","definition_ar":"نظام محاسبة، يُكلّف الإيرادات، و التكاليف، و/أو رأس المال على وحدات المؤسسة (enterprise) (مراكز المسؤولية).","topic":"Performance Management","difficulty":"Intermediate"},{"id":719,"en":"Responsibility Budget","ar":"موازنة المسؤولية","definition_en":"A budget that sets forth approved plans structured in terms of the units responsible for carrying them out. It is a control device in that it is a statement of performance expected of each responsibility center manager against which actual performance can be compared.","definition_ar":"موازنة، تضع خطط مهيكلة و موافق عليها مقدماً بأحكام الوحدات المسؤولة عن الاضطلاع بالخطط. و هي جهاز ضبط إذ قائمة الأداء المتوقع من كل مدير لمركز مسؤولية يمكن بالمقابل مقارنتها مع أدائه الفعلي.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":720,"en":"Responsibility Center","ar":"مركز مسؤولية","definition_en":"An organizational unit headed by a manager who is responsible for its activities.","definition_ar":"وحدة تنظيمية على رأسها مدير مسؤول عن أنشطتها.","topic":"Performance Management","difficulty":"Intermediate"},{"id":721,"en":"Restructuring","ar":"إعادة الهيكلة","definition_en":"A significant modification made to the debt, operations, or structure of a company.","definition_ar":"تعديل ذو أهمية، يتم على ديون، أو عمليات، أو هيكل الشركة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":722,"en":"Retained Earnings","ar":"دخل محتجز","definition_en":"Net income over the life of a corporation less dividends.","definition_ar":"صافي الدخل على مدى عمر شركة عامة مطروحاً منه توزيعات الأرباح.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":723,"en":"Return","ar":"عائد","definition_en":"The change in the value of an investment over an evaluation period, including any cash flows received pertaining to the investment during that period.","definition_ar":"تغير في قيمة الاستثمار خلال فترة التقييم، يشمل أية تدفقات نقد استلمت فيما يخص الاستثمار أثناء تلك الفترة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":724,"en":"Return on Assets (ROA)","ar":"عائد على الأصول (ROA)","definition_en":"A measure of how effective an entity is at earning a return on the assets employed in its business.","definition_ar":"قياس مدى فاعلية الكيان في جني عائد على الأصول التي وظّفت لأعماله.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":725,"en":"Return on Common Equity","ar":"عائد على حقوق الملكية العادية","definition_en":"A measure that indicates the rate of return on the shareholders’ investment. (Also called return on owners’ equity.)","definition_ar":"قياس، يُشير إلى معدل العائد على استثمار أصحاب الحصص. (يسمى أيضاً عائد على حقوق الملكية للمالكين.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":726,"en":"Return on Invested Capital","ar":"عائد على رأس المال المستثمر","definition_en":"A measure of how effectively a company uses the money (debt or equity) invested in its operations.","definition_ar":"قياس لمدى فاعلية استخدام الشركة للمال (ديون أو حقوق ملكية) المستثمر في عملياتها.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":727,"en":"Return on Investment (ROI)","ar":"عائد على الاستثمار (ROI)","definition_en":"The ratio of income earned on the investment to the investment made to earn that income.","definition_ar":"نسبة الدخل المجني من الاستثمار إلى الاستثمار الذي تم لِجني ذلك الدخل.","topic":"Performance Management","difficulty":"Intermediate"},{"id":728,"en":"Revenue","ar":"إيرادات","definition_en":"Inflows or other enhancements of assets of an entity or settlements of its liabilities (or a combination of both) during a period from delivering or producing goods, rendering services, or other activities that constitute the entity’s ongoing major or central operations.","definition_ar":"تدفقات واردة أو تعزيزات أخرى لأصول الكيان أو تسديد لمطلوباته (أو تركيبة من كلاهما) أثناء فترة توصيل أو إنتاج البضاعة، أو إسداء الخدمات، أو من أنشطة أخرى تتألف منها أغلب عمليات الكيان المستمرة أو المركزية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":729,"en":"Revenue Center","ar":"مركز إيراد","definition_en":"A responsibility center in which management control is focused on the revenue that the center earns.","definition_ar":"مركز مسؤولية، تُركّز فيه ضوابط الإدارة على الإيراد الذي يجنيه المركز.","topic":"Performance Management","difficulty":"Intermediate"},{"id":730,"en":"Revenue Recognition","ar":"اعتراف بالإيرادات","definition_en":"An accounting principle under generally accepted accounting principles (GAAP) that determines the specific conditions under which revenue is recorded in the financial statements.","definition_ar":"مبدأ في المحاسبة بموجب مبادئ المحاسبة المقبولة عموما (GAAP)، يُحدد شروط محددة بموجبها يُسجّل الإيراد في القوائم المالية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":731,"en":"Revenue-Recognition Principle","ar":"مبدأ الاعتراف بالإيرادات","definition_en":"The principle that revenue should be recognized when it is earned & its collection is reasonably assured.","definition_ar":"مبدأ أن الإيرادات ينبغي الاعتراف بها عند جنيها وعند التأكيد بحد معقول على تحصيلها.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":732,"en":"Rights","ar":"حقوق","definition_en":"An offer made by a company to its shareholders to enable them to buy new shares in the company at a discount from the market price.","definition_ar":"طرح جديد تقدمه الشركة لأصحاب حصصها لتمكينهم من شراء حصص في الشركة بخصم عن سعر السوق.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":733,"en":"Risk","ar":"مخاطر","definition_en":"A measure of the variability of the return on investment","definition_ar":"قياس لمدى تغير العائد على الاستثمار","topic":"Risk Management","difficulty":"Intermediate"},{"id":734,"en":"Risk Analytics","ar":"تحليل المخاطر","definition_en":"The process of defining and analyzing the dangers to firms posed by potential natural and human- caused adverse events; quantitative risk analysis estimates the probabilities of adverse events and the likely extent of the losses; qualitative risk analysis defines the threats, determines the extent of vulnerabilities, and devises countermeasures should an adverse event occur.","definition_ar":"عملية تعريف و تحليل الخطر في المنشآت الذي ينجم عن أحداث مغايرة بإمكانيات سببها الطبيعة أو البشر؛ و يُقدِّر التحليل الكمي للمخاطر احتمالات الأحداث المغايرة و مدى ترجيح الخسائر؛ أما التحليل النوعي للمخاطر فهو يعرّف التهديدات، و يحدد مدى قابلية التّأثر بها، و يُجهّزُ القياسات المضادة في حال حدوث الحدث المغاير.","topic":"Risk Management","difficulty":"Intermediate"},{"id":735,"en":"Risk Assessment","ar":"تقييم المخاطر","definition_en":"1. In capital budgeting, methods used to identify, and quantify the relative risk of a project. 2. In auditing, a systematic process for exercising and integrating professional judgments about potential adverse conditions and events.","definition_ar":"1. في إعداد موازنات رأس المال، تستخدم للمخاطر طرق نسبية لتعريفها و قياسها كمّيا في المشروع. 2. و في التدقيق، هي عملية نظامية لممارسة و تكامل الحكم المهني على الحالات و الأحداث ذات الإمكانيات المغايرة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":736,"en":"Risk Premium","ar":"علاوة المخاطر","definition_en":"The return in excess of the risk-free rate of return that an investment is expected to yield; a form of compensation for investors who take on the extra risk.","definition_ar":"فائض عائد على عائد معدل خلو المخاطر المتوقع تحصيله من الاستثمار؛ كشكل من أشكال التعويض للمستثمرين الذين يتحملون مخاطر إضافية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":737,"en":"Risk Response","ar":"الاستجابة للمخاطر","definition_en":"Steps taken to deal with variance types of risk; four different strategies: avoidance, mitigation, acceptance, or transference. (Also called Risk Treatment.)","definition_ar":"خطوات، تتخذ للتعامل مع أنواع مختلفة من المخاطر؛ وهي أربع استراتيجيات مختلفة: التجنب، أو التخفيف، أو القبول، أو التحويل. (يسمى أيضاً معالجة المخاطر.)","topic":"Risk Management","difficulty":"Intermediate"},{"id":738,"en":"Risk Transfer","ar":"تحويل المخاطر","definition_en":"Shifting risk from one party to another (e.g. insurance).","definition_ar":"نقل المخاطر من طرف إلى آخر (مثل، التأمين).","topic":"Risk Management","difficulty":"Intermediate"},{"id":739,"en":"Risk-Adjusted Return","ar":"عائد مع تسوية المخاطر","definition_en":"In capital budgeting, a rate of return that is adjusted for the expected risk of the proposed project. The net present value of a project whose risk is expected to be greater than average is found by using a higher than average discount rate. (Also called Risk- Adjusted Discount Rate.)","definition_ar":"في إعداد موازنة رأس المال، هو معدل العائد بعد تسوية المخاطر المتوقعة في مشروع مقترح. و صافي القيمة الحالية لمشروع من المتوقع أن تكون مخاطره أكبر من المتوسط يتم إيجاده باستخدام معدل خصم أعلى من المتوسط. (يسمى أيضاً معدل الخصم مع تسوية المخاطر.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":740,"en":"Robotic Process Automation (RPA)","ar":"أتمتة العمليات بالروبوت (RPA)","definition_en":"Automating rules-based routine processes using robotic software and artificial intelligence (AI), reducing costs and streamlining operations.","definition_ar":"أتمتة عمليات روتينية على أساس القواعد، تستخدم برمجيات روبوتية و الذكاء الاصطناعي (AI)، لتخفيض التكاليف و انسيابية التشغيل.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":741,"en":"Rolling Budget","ar":"موازنة اللّف","definition_en":"A moving projection of financial operations for a series of weeks, months, or quarters immediately ahead. At the end of each period, the portion of the projection then lapsed is removed and a new projection for a period of similar length is added to the series. (Also called Continuous Budget.)","definition_ar":"عرض تصوّرات متحرك لعمليات مالية في مسلسل من أسابيع، أو شهور، أو أرباع التالية على الفور. وعند نهاية كل فترة، تُزال الجزئية التي مضت من عرض التصورات ليضاف للمسلسل عرض تصوّرات جديد لفترة ذات مدة مشابهة. (يسمى أيضاً موازنة مستمرة.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":742,"en":"Safety Stock","ar":"مخزون الأمان","definition_en":"A quantity of inventory held to meet unanticipated demand during the time between placement of an order and its receipt into inventory, or unanticipated delays in receiving the replenishment.","definition_ar":"كمية مخزون، يُمسك عليها لتلبية طلب لم يكن منتظر أثناء الفترة الواقعة بين إعداد الطلبية و استلامها في المخزون، أو لتأخيرات لم تكن منتظرة في استلام سد النقص.","topic":"Cost Management","difficulty":"Intermediate"},{"id":743,"en":"Sales Budget","ar":"موازنة المبيعات","definition_en":"A projection of sales for a given period of time.","definition_ar":"عرض تصورات المبيعات في فترة من الزمن معطاة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":744,"en":"Sales Discount","ar":"خصم المبيعات","definition_en":"A reduction in the sales price of a product.","definition_ar":"تخفيض في سعر بيع المنتج.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":745,"en":"Sales on Installment","ar":"مبيعات بالتقسيط","definition_en":"Arrangements in which the buyer takes possession of the property immediately but does not receive the deed and title until a series of payments (installments) have been made.","definition_ar":"ترتيبات، يأخذ بها المشتري حيازة الممتلكات فوراً و لكنه لا يستلم الحجّة و حق الملكية حتى يتم الدفعات المتسلسلة (الأقساط).","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":746,"en":"Sales-Mix Variance","ar":"انحراف مزيج المبيعات","definition_en":"The difference between budgeted and actual sales caused by a difference between the budgeted and actual proportions of products with different profit margins.","definition_ar":"الفرق بين مبيعات الموازنة و المبيعات الفعلية بسبب فرق بين نسب الموازنة و النسب الفعلية للمنتجات مع فرق هوامش الربح.","topic":"Performance Management","difficulty":"Intermediate"},{"id":747,"en":"Sales-Volume Variance","ar":"انحراف حجم المبيعات","definition_en":"The difference between the flexible budget units and the static budget units multiplied by the budgeted unit contribution margin.","definition_ar":"الفرق بين وحدات الموازنة المرنة و وحدات الموازنة الساكنة مضروباً في هامش المساهمة من وحدة الموازنة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":748,"en":"Salvage Value","ar":"قيمة الإنقاذ","definition_en":"The expected value of an asset at the end of its useful life.","definition_ar":"قيمة متوقعة من الأصل عند نهاية عمر الاستفادة منه.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":749,"en":"Sarbanes-Oxley","ar":"ساربينز أوكسلي","definition_en":"A U.S. law enacted in 2002 to specify the requirements of corporate governance, including accounting issues. It addresses the regulation of the accounting profession, the standards for audit committees of public companies, the certifications management must make, and standards of internal control that companies must meet.","definition_ar":"سُنّ كقانون في الولايات المتحدة سنة 2002 ليحدد متطلبات حوكمة الشركات العامة، كما يشمل مسائل في المحاسبة. و هو معني بإخضاع مهنة المحاسبة للوائح، و بمعايير لجان التدقيق في الشركات العامة، و بالشهادات التي يجب على الإدارة عملها، و بمعايير الضوابط الداخلية التي يجب على الشركات تلبيتها.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":750,"en":"Scenario Analysis","ar":"تحليل السيناريو","definition_en":"The process of estimating the expected value of a portfolio, assuming changes in key factors that would affect security values; more broadly, the process of analyzing possible future events by considering alternative possible outcomes.","definition_ar":"عملية تقدير القيمة المتوقعة من محفظة، بافتراض تغيرات في العوامل الرئيسية التي يمكن أن تؤثر في قيم الأوراق المالية؛ و بصورة أعم، عملية تحليل أحداث المستقبل الممكنة بالنظر في نتائج البديل الممكنة.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":751,"en":"Scenario Planning","ar":"تخطيط السيناريو","definition_en":"A planning technique where the revenues and/ or costs from a few (typically three) cases are compared.","definition_ar":"تقنية تخطيط، تُقارن فيها الإيرادات و/أو التكاليف من بعض (نموذجياً ثلاث) الحالات.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":752,"en":"Seasonal Trend","ar":"توجّه موسمي","definition_en":"A consistent rise or drop in business activity that occurs due to predictable changes in the calendar.","definition_ar":"اتساق في ارتفاع أو انخفاض نشاط الأعمال، يحدث جرّاء تغيرات قابلة للتنبؤ بها من الرزنامة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":753,"en":"Secondary Offering","ar":"طرح ثانوي","definition_en":"The issuance of new stock for public sale from a company that has already made its initial public offering. (Also called Subsequent Offering.)","definition_ar":"إصدار أسهم جديدة للبيع العام من شركة قامت بالطرح العام الأوّلي بالفعل. (يسمى أيضاً طرح لاحق.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":754,"en":"Securities and Exchange Commission (SEC)","ar":"لجنة الأوراق المالية وصرف العملات (SEC)","definition_en":"The U.S. federal agency empowered to regulate U.S. financial markets in order to protect investors. All publicly-traded companies have to comply with SEC rules and regulations, including the filing of annual, quarterly, and other disclosure reports.","definition_ar":"وكالة فيدرالية في الولايات المتحدة ذات تمكين يُخضِع للوائح الأسواق المالية في الولايات المتحدة من أجل حماية المستثمرين. و على جميع شركات التداول العام أن تمتثل لقواعد و لوائح لجنة الأوراق المالية وصرف العملات (SEC)، التي تشمل إرسال ملفات تقارير الإفصاح السنوية، و الربعية، و غيرها.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":755,"en":"Segment","ar":"مقطع","definition_en":"One of two or more divisions, product departments, plants, or other subdivisions of an entity reporting directly to a home office, usually identified with responsibility for profit and/or producing a product or service.","definition_ar":"واحد من اثنين أو أكثر من الأقسام، أو دوائر المنتجات، أو المعامل، أو أقسام الفروع في الكيان، يُعد تقارير مباشرة لمكتب رئيسي، و عادة يُعرف بمسؤوليته عن ربح و/أو إنتاج منتج أو خدمة ما.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":756,"en":"Segregation of Duties","ar":"فصل بين الواجبات","definition_en":"A basic key internal control used to ensure that errors or irregularities are prevented or detected on a timely basis by employees in the normal course of business. It requires that no single individual should have control over two or more phases of a transaction or operation.","definition_ar":"ضابط داخلي رئيسي و أساسي، يُستخدم في توكيد أن الأخطاء أو التجاوزات قد منعت أو اكتشفت في وقتها من قبل الموظفين في مساق الأعمال العادية. و يتطلب أن لا ينبغي على فرد بمفرده أن يضبط مرحلتين أو أكثر من مراحل معاملة أو تشغيل.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":757,"en":"Selling and Administrative Budget","ar":"موازنة المبيعات و إدارة الموارد","definition_en":"A budget for costs related to selling or marketing (e.g., sales representatives’ salaries, commissions, traveling expense, and advertising) & for the general administration of the corporation (e.g., salaries of top officers, rent, and other general office expense).","definition_ar":"موازنة للتكاليف المتعلقة بالبيع أو التسويق (مثل، رواتب مندوبي المبيعات، و العمولات، و مصاريف السفر، و الدعاية) و عامةً لإدارة موارد الشركة العامة (مثل، رواتب المسؤولين في القمة، و الاستئجار، و غيرها من مصاريف المكتب عامة).","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":758,"en":"Selling Costs","ar":"تكاليف البيع","definition_en":"Any expense or class of expense incurred in selling or marketing.","definition_ar":"أية مصاريف أو تصنيف للمصاريف، تُتكبد في البيع أو التسويق.","topic":"Cost Management","difficulty":"Intermediate"},{"id":759,"en":"Sensitivity Analysis","ar":"تحليل الحساسية","definition_en":"A technique that identifies and analyzes alternative outcomes of an investment resulting from the alteration of one or more of the variables in the analysis (Also known as What-if analysis).","definition_ar":"تقنية لتعريف و تحليل نتائج بديل الاستثمار التي تنتج من تبديل واحد أو أكثر من متغيرات التحليل (يُعرف أيضاً بتحليل ماذا لو).","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":760,"en":"Separable Costs","ar":"تكاليف قابلة للفصل","definition_en":"For products produced in a joint process, the costs incurred beyond the split-off point that are assignable to one or more individual products.","definition_ar":"لمنتجات، تُنتج في عملية مشتركة تُتكبد تكاليف من بعد نقطة الانقسام و هي قابلة لتكليفها لواحد أو أكثر من المنتجات الفردية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":761,"en":"Service Department","ar":"دائرة الخدمات","definition_en":"A unit (department) within an entity that provides services to other departments of the entity.","definition_ar":"وحدة (دائرة) ضمن حيز كيان، تُوفّر خدمات لدوائر أخرى في الكيان.","topic":"Cost Management","difficulty":"Intermediate"},{"id":762,"en":"Shareholder","ar":"أصحاب الحصص","definition_en":"The owner of shares in a company.","definition_ar":"مالك لحصة في الشركة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":763,"en":"Shareholders’ Equity","ar":"حقوق الملكية لأصحاب الحصص","definition_en":"The owner’s equity in a corporation. (Also called Stockholders’ Equity.)","definition_ar":"حقوق ملكية المالك في شركة عامة. (يسمى أيضاً حقوق ملكية المساهمين.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":764,"en":"Short Position","ar":"مركز قصير","definition_en":"The purchase of a security with the expectation that the security will fall in value.","definition_ar":"شراء أوراق مالية من المتوقع أن قيمتها ستنخفض.","topic":"Risk Management","difficulty":"Intermediate"},{"id":765,"en":"Short Run","ar":"مدى قصير","definition_en":"A time period of insufficient length to allow decision makers to adjust fully to a change in market conditions. In the short run, producers may be able to increase output by using more labor or raw materials, but they will not have time to expand the size of their plants.","definition_ar":"فترة زمنية ذات مدة غير كافية تسمح لصنّاع القرار بالتسوية مع تغير حالات السوق تماماً. في المدى القصير، يمكن للمنتجين أن يقدروا على زيادة المخرجات باستخدام مزيد من العمالة أو مواد الخام، و لكن لن يكون لديهم وقت لتوسعة مقاس المعمل.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":766,"en":"Short-Term Credit","ar":"ائتمان قصير المدة","definition_en":"Credit extended to an entity by a financial institution (Bank Loan), investors (Commercial Paper) or suppliers (Trade Credit).","definition_ar":"ائتمان، يُمدُّ به الكيان من مؤسسة (firm) مالية (قرض بنك)، أو مستثمرين (ورقة تجارية)، أو موردين (ائتمان تجاري).","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":767,"en":"Shrinkage","ar":"انكماش","definition_en":"The loss of raw materials, work-in-process, or finished goods in terms of weight or volume due to the nature of the product or the methods employed for production, transportation, and storage.","definition_ar":"خسارة في مواد الخام، أو عملية قيد العمل، أو بضاعة تامة بأحكام الوزن أو الحجم جرّاء طبيعة المنتج أو الطرق المستخدمة في الإنتاج، و النقل، و التخزين.","topic":"Cost Management","difficulty":"Intermediate"},{"id":768,"en":"Sight Draft","ar":"حوالة الاطلاع","definition_en":"A draft which is payable on demand.","definition_ar":"حوالة قابلة للدفع عند الطلب.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":769,"en":"Simple Regression","ar":"انحدار بسيط","definition_en":"A regression model that uses only one independent variable to estimate the dependent variable.","definition_ar":"نموذج انحدار، يستخدم متغير مستقل واحد فقط لتقدير المتغير التابع.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":770,"en":"Simulation","ar":"محاكاة","definition_en":"A method of studying an operational problem, whereby a model of the system or process is subjected to a series of recalculations of possible outcomes to reflect varying assumptions.","definition_ar":"طريقة لدراسة مشكلة تشغيلية، يخضع بها نموذج النظام أو العملية لسلسلة من الاحتسابات المعادة للنتائج الممكنة، لكي تعكس الافتراضات المتغيرة.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":771,"en":"Situation Analysis","ar":"تحليل الوضعية","definition_en":"A method that managers use to analyze an organization’s internal and external environment to understand the organization’s capabilities, customers, and business environment.","definition_ar":"طريقة، يستخدمها المديرون لتحليل البيئة الداخلية و الخارجية للوحدة المنظمة و ذلك لفهم قدرات، و زبائن، وبيئة أعمال الوحدة المنظمة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":772,"en":"Slack","ar":"تراخي","definition_en":"In budgeting, the difference between the costs or expenses actually required in the operation of a responsibility center and the costs or expenses that have been proposed or approved in the budget.","definition_ar":"في إعداد الموازنة، الفرق بين التكاليف أو المصاريف التي فعلياً يتطلبها تشغيل مركز المسؤولية و التكاليف أو المصاريف المقترحة أو الموافق عليها في الموازنة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":773,"en":"Smart Contract","ar":"عقد ذكي","definition_en":"Computer protocol used to digitally facilitate, verify, or enforce the negotiation or performance of a contract without the need for a third party.","definition_ar":"بروتوكول في الحاسوب، يُستخدم رقمياً للتفاوض أو لأداء عقد ما من تسهيل، أو تحقّق، أو إنفاذ بدون حاجة إلى طرف ثالث.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":774,"en":"Software","ar":"برمجيات","definition_en":"A collection of computer programs and related data that provide the instructions telling a computer what to do and how to do it.","definition_ar":"حصيلة برامج الحاسوب و البيانات ذات العلاقة، تُوفّر تعليمات تقول للحاسوب ماذا يفعل و كيف يفعل.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":775,"en":"Solvency","ar":"ملاءة","definition_en":"The ability to pay all debt obligations as they become due.","definition_ar":"مقدرة على دفع جميع التزامات الدين عندما تصبح مستحقة.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":776,"en":"Special Purpose Entity","ar":"كيان لغرض خاص","definition_en":"Entities created by corporations, usually as subsidiaries but sometimes as partnerships or trusts, for a single, well-defined, and narrow purpose, usually the acquisition and financing of specific assets. (Also known as Special Purpose Vehicles.)","definition_ar":"كيانات، تخلقها الشركات العامة، عادة كشركات تابعة و لكن في بعض الأحيان كشراكات أو أمانات، لغرض فردي، و معرّف جيداً، و ضيق النطاق، عادة للاستحواذ و لتمويل أصول محددة. (يعرف أيضاً بمركبات الغرض الخاص.)","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":777,"en":"Specific Identification","ar":"تعريف محدد","definition_en":"The inventory cost flow method in which the actual cost of the specific goods sold is recorded as cost of goods sold.","definition_ar":"طريقة لتدفق تكاليف المخزون، تسجل بها التكلفة الفعلية لبضاعة محددة و مباعة كتكلفة البضاعة المباعة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":778,"en":"Spending Variance","ar":"انحراف الإنفاق","definition_en":"Actual amount of overhead incurred less the expected amount based on the flexible budget for actual inputs.","definition_ar":"المبلغ الفعلي للفوقية المتكبدة ناقصاً منه المبلغ المتوقع على أساس الموازنة المرنة بمدخلات فعلية.","topic":"Performance Management","difficulty":"Intermediate"},{"id":779,"en":"Spin-Off","ar":"منبثقة","definition_en":"A new independent company created by divesting part of a parent company’s assets and operations, and distributing shares in the new company to the parent company’s shareholders.","definition_ar":"شركة مستقلة جديدة، تُخلق بتجريد الشركة الأم من جزء من أصولها و عملياتها، و تُوزّع حصص الشركة الجديدة على أصحاب الحصص في الشركة الأم.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":780,"en":"Split-Off Point","ar":"نقطة الانقسام","definition_en":"The point of production beyond which the cost of separate products can be measured. Up to this point, the products were either joint products or byproducts.","definition_ar":"نقطة في الإنتاج من بعدها يمكن قياس تكلفة المنتجات المنفصلة. و حتى هذه النقطة، تكون المنتجات إما منتجات مشتركة أو منتجات جانبية.","topic":"Cost Management","difficulty":"Intermediate"},{"id":781,"en":"Split-Up","ar":"انقسام","definition_en":"Reorganizing a corporation whereby all capital stock and assets are exchanged for the stock of two or more newly established companies, resulting in the liquidation of the parent corporation.","definition_ar":"إعادة تنظيم الشركة العامة، تُستبدل به جميع أسهم رأس المال و الأصول بأسهم من شركتين أو أكثر من الشركات التي تأسست حديثاً، فتنتج تصفية للشركة العامة الأم.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":782,"en":"Spot Rate","ar":"سعر فوري","definition_en":"The exchange rate for immediate delivery of currencies or commodities exchanged; the rate of interest or price being charged currently.","definition_ar":"سعر الصرف بتوصيل العملات أو السلع المستبدلة فوراً؛ و يكون التثمين بمعدل أو سعر الفائدة حالياً.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":783,"en":"Spreadsheet","ar":"(Spreadsheet) ورقة انتشار","definition_en":"A work sheet organized in the form of a matrix with rows and columns","definition_ar":"ورقة عمل منظمة في شكل مصفوفة من صفوف و أعمدة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":784,"en":"Standard Cost","ar":"تكلفة معيارية","definition_en":"The anticipated cost of producing a unit of output; a predetermined cost to be assigned to products produced. Standard cost implies a norm, or what costs should be.","definition_ar":"تكلفة منتظرة لإنتاج وحدة من المخرجات؛ بتحديد مسبق لتكلفة تكلّف على المنتجات المنتجة. و تنطوي التكلفة المعيارية على المقياس، أو ما ينبغي أن تكون التكاليف عليه.","topic":"Performance Management","difficulty":"Intermediate"},{"id":785,"en":"Standard Deviation","ar":"انحراف معياري","definition_en":"A statistical measure of the spread or dispersion of a set of data, calculated as: the square root of the arithmetic mean of the squares of the deviation of each of the class frequencies from the arithmetic mean of the frequency distribution.","definition_ar":"قياس إحصائي لانتشار أو تشتت مجموعة من البيانات، التي تحتسب على أنها: الجذر التربيعي للوسط الحسابي لمربعات الانحراف لتكرارات كل تصنيف من الوسط الحسابي لتوزيع التكرار.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":786,"en":"Start-Up Costs","ar":"تكاليف المبادأة","definition_en":"The costs of preparing to operate facilities which can include costs of designing, tooling, recruiting, and training the labor force before production starts; moving; preparation of facilities; and related general and administrative costs.","definition_ar":"تكاليف التحضير لتشغيل المرافق، يمكن أن تشمل تكاليف التصميم، و توفير الأدوات، و التوظيف، و تدريب قوى العمل قبل أن يبدأ الإنتاج؛ و الحركة؛ و تحضير المرافق؛ و التكاليف العامة و إدارة الموارد ذات العلاقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":787,"en":"Statement of Cash Flow","ar":"قائمة تدفق النقد","definition_en":"A statement that classifies cash receipts and payments according to whether they are the result of operating, investing, or financing activities.","definition_ar":"قائمة، تُصنّف النقد كمقبوضات و دفعات وفقاً لكونه من نتائج أنشطة تشغيل، أو استثمار، أو تمويل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":788,"en":"Statement of Changes in Shareholders’ Equity","ar":"قائمة التغيرات في حقوق ملكية أصحاب الحصص","definition_en":"An accounting statement presenting the individual components of Shareholders’ Equity at various points in time and the changes that occurred within the individual components.","definition_ar":"قائمة في المحاسبة، تُقدم المكوّنات الفردية لحقوق ملكية أصحاب الحصص في نقاط مختلفة من الزمن مع التغيرات التي حدثت ضمن حيز المكوّنات الفردية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":789,"en":"Statement of Earnings (Income Statement)","ar":"قائمة المدخولات (قائمة الدخل)","definition_en":"A financial statement that reports revenues, expenses, gains, and losses for an accounting period, usually compared with amounts in one or more earlier periods.","definition_ar":"قائمة مالية، تُقر بالإيرادات، و المصاريف، و المكاسب، و الخسائر لفترة المحاسبة، و عادة تُقارن بمبالغ في فترات سابقة واحدة أو أكثر.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":790,"en":"Statement of Financial Position (Balance Sheet)","ar":"قائمة المركز المالي (الميزانية العمومية)","definition_en":"The statement of financial position that discloses the assets, liabilities, and equity accounts of an entity at a particular date. Comparable information from one or more prior periods may be included.","definition_ar":"قائمة المركز المالي، تُفصح عن حسابات الأصول، و المطلوبات، و حقوق الملكية للكيان في تاريخ معين. و يمكن أن تشمل معلومات قابلة للمقارنة من فترات سابقة واحدة أو أكثر.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":791,"en":"Statement on Management Accounting (SMA)","ar":"قائمة المحاسبة الإدارية (SMA)","definition_en":"Practice-based monographs on critical issues that affect the profession of management accounting, published by IMA.","definition_ar":"مونوجرافات على أساس مزاولة مهنة المحاسبة الإدارية مع تأثير المسائل الحرجة، نشرتها الآي.أم.أيه. (IMA).","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":792,"en":"Static Budget","ar":"موازنة ساكنة","definition_en":"A static budget is a budget that does not change as volume changes.","definition_ar":"الموازنة الساكنة هي موازنة لا تتغير بتغير الحجم.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":793,"en":"Step-Down Method","ar":"طريقة التنحي","definition_en":"The method of allocating service department costs that begins by allocating one service department’s costs to production departments and to all other service departments. A second service department’s costs, including costs allocated from the first, are then allocated to production departments and to all other service departments except the first one, etc. The costs of all service departments are ultimately allocated to production departments.","definition_ar":"طريقة لتخصيص تكاليف دائرة الخدمات، تبدأ بتخصيص تكاليف أحد دوائر الخدمات على دوائر الإنتاج و على جميع دوائر الخدمات الأخرى. تكاليف دائرة الخدمات الثانية، تشمل التكاليف المخصصة من الأولى، و تخصص على دوائر الإنتاج و على جميع دوائر الخدمات الأخرى عدا الدائرة الأولى، إلخ. في نهاية المطاف، تخصص تكاليف جميع دوائر الخدمات على دوائر الإنتاج.","topic":"Cost Management","difficulty":"Intermediate"},{"id":794,"en":"Stock Dividends","ar":"توزيع أرباح أسهم","definition_en":"The payment of a dividend to shareholders in the form of stock instead of cash.","definition_ar":"دفع توزيع الأرباح لأصحاب الحصص على شكل أسهم بدلًا من النقد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":795,"en":"Stock Option","ar":"خيار الأسهم","definition_en":"The right to purchase or sell a specified number of shares of stock in a company for a specified price at a specified time.","definition_ar":"حق في شراء أو بيع عدد محدد من حصص الأسهم في شركة بسعر محدد و لزمن محدد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":796,"en":"Stock Split","ar":"انقسام الأسهم","definition_en":"An increase in the number of common shares outstanding resulting from the issuance of additional shares to existing shareholders without requiring payment from the shareholders.","definition_ar":"زيادة عدد الحصص العادية المعلّقة، تنتج من إصدار حصص إضافية لأصحاب الحصص الحاليين بدون أن يتطلب ذلك دفعات من أصحاب الحصص.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":797,"en":"Stock-Out Costs","ar":"تكاليف نفاذ المخزون","definition_en":"The contribution margin or other measure of profits not earned because a seller has run out of inventory and is unable to fill a customer’s order.","definition_ar":"هامش المساهمة أو أي قياس آخر للأرباح التي لم تجنى لأن البائع نفذ المخزون لديه و أصبح غير قادر على تلبية طلبيات الزبائن.","topic":"Cost Management","difficulty":"Intermediate"},{"id":798,"en":"Storage Controls","ar":"ضوابط التخزين","definition_en":"Internal controls for computer data and business information; e.g. off-site storage, locked rooms, passwords, backups, etc.","definition_ar":"ضوابط داخلية لبيانات الحاسوب و معلومات الأعمال؛ مثل، التخزين خارج الموقع، و الغرف المقفلة، و كلمات السر، و التخزين الاحتياطي، إلخ.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":799,"en":"Straight-Line Method","ar":"طريقة الخط المستقيم","definition_en":"A method of depreciating assets in which an equal amount of depreciation is taken each year over the estimated economic life of the asset.","definition_ar":"طريقة لاهتلاك الأصول، يُأخذ بها مبلغ متساوٍ للاهتلاك لكل سنة من سنوات العمر الاقتصادي المُقدّر للأصل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":800,"en":"Strategic Business Unit (SBU)","ar":"وحدة الأعمال الإستراتيجية (SBU)","definition_en":"A business unit within the overall corporate entity which is distinguishable from other business units because it serves a defined external market where management can conduct strategic planning in relation to products and markets.","definition_ar":"وحدة أعمال ضمن حيز كيان الشركة العامة ككل، قابلة لتمييزها عن غيرها من وحدات الأعمال لأنها تخدم سوقاً خارجياً معرّفاً يمكن للإدارة القيام بالتخطيط الإستراتيجي فيه فيما يتعلق بالمنتجات و الأسواق.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":801,"en":"Strategic Planning","ar":"التخطيط الإستراتيجي","definition_en":"A process used to make decisions about the long- term goals and strategies of an organization.","definition_ar":"عملية، تُستخدم لصنع قرارات لأهداف و إستراتيجيات الوحدة المنظمة الطويلة المدة .","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":802,"en":"Strategic Risk","ar":"مخاطر إستراتيجية","definition_en":"The possible impact on earnings or capital arising from adverse business decisions, improper implementation of decisions, or lack of responsiveness to industry changes.","definition_ar":"أثر مُمكن على المدخولات أو رأس المال، ينجم عن قرارات الأعمال المغايرة، أو التنفيذ الغير لائق للقرارات، أو نقص الاستجابة لتغيرات الصناعة.","topic":"Risk Management","difficulty":"Intermediate"},{"id":803,"en":"Strike Price","ar":"سعر التنفيذ","definition_en":"Price at which a call option or put option may be exercised (carrying out the terms of agreement). (Also called Exercise Price.)","definition_ar":"سعر، يمكن عنده ممارسة خيار الشراء أو خيار البيع (اضطلاعاً بأحكام الاتفاق). (يسمى أيضاً سعر الممارسة (Exercise Price).)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":804,"en":"Subsidiary","ar":"شركة تابعة","definition_en":"A corporation that is controlled, directly or indirectly, by another corporation. The usual condition for control is ownership of a majority of the outstanding voting stock.","definition_ar":"شركة عامة تضبطها، مباشرةً أو غير مباشرةً، شركة عامة أخرى. و الشرط المعتاد للضبط هو ملكية أغلبية أسهم التصويت المعلّقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":805,"en":"Sunk Costs","ar":"تكاليف غارقة","definition_en":"A past cost which cannot now be changed and therefore should not enter into current decisions for increasing or decreasing present profit levels.","definition_ar":"تكلفة، مضت ولا يمكن تغييرها الآن لذا ينبغي ألا تدخل في القرارات الحالية التي تزيد أو تنقص من مستويات الربح الحالية.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":806,"en":"Supply","ar":"عرض","definition_en":"The total amount of a good or service available for purchase. One of the two key determinants of price along with demand.","definition_ar":"مجموع مبلغ البضاعة أو الخدمة المتاحة للشراء. أحد المحددين الرئيسيين للسعر إلى جانب الطلب.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":807,"en":"Sustainable Equity Growth","ar":"نمو حقوق الملكية المستدام","definition_en":"The maximum growth rate that a firm can sustain without having to increase financial leverage.","definition_ar":"الأقصى من معدل النمو الذي يمكن للمنشأة استدامته بدون أن يكون عليها زيادة المديونية المالية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":808,"en":"Sustainable Growth Rate","ar":"معدل النمو المستدام","definition_en":"Maximum growth rate a firm can sustain without increasing financial leverage.","definition_ar":"أقصى معدل نمو، يمكن للمنشأة استدامته بدون زيادة المديونية المالية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":809,"en":"Swaps","ar":"مبادلات","definition_en":"An arrangement whereby two companies lend to each other on different terms; e.g., one at a fixed interest rate and the other at a variable interest rate.","definition_ar":"ترتيب، تُقرض به شركتان كل منهما الأخرى بأحكام مختلفة، مثل، إحداهما بمعدل فائدة ثابت، و الأخرى بمعدل فائدة متغير.","topic":"Risk Management","difficulty":"Intermediate"},{"id":810,"en":"SWOT Analysis","ar":"تحليل سوات (SWOT)","definition_en":"A method of analyzing internal (Strengths and Weaknesses) and external (Opportunities and Threats) as part of strategic planning.","definition_ar":"طريقة تحليل داخلية (قوة و ضعف) و خارجية (فرص و تهديد) كجزء من التخطيط الاستراتيجي.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":811,"en":"System","ar":"نظام","definition_en":"In data processing, a collection of people, machines, and methods organized to accomplish a set of specific functions.","definition_ar":"في معالجة البيانات، حصيلة ناس، و آلات، و طرق، تُنظّم لتتم مجموعة مسارات عمل محددة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":812,"en":"Systematic Risk","ar":"مخاطر نظامية","definition_en":"The portion of stock price (or portfolio) movement that is attributable to the movement of the market as a whole. (Also called Market Risk.)","definition_ar":"جزئية من حركة سعر السهم (أو المحفظة)، تُعزى لمجمل حركة السوق. (يسمى أيضاً مخاطر السوق.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":813,"en":"System Development Life Cycle (SDLC)","ar":"دورة حياة تطوير النظام (SDLC)","definition_en":"A process used to design and implement a new system, including analysis, design, testing, implementation, and maintenance.","definition_ar":"عملية، تستخدم في تصميم و تنفيذ نظام جديد، تشمل التحليل، و التصميم، و الفحص، و التنفيذ، و الصيانة.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":814,"en":"Systems Development","ar":"تطوير الأنظمة","definition_en":"A process used to determine the needs of an information system and then designing and implementing the system to meet those needs.","definition_ar":"عملية، تستخدم في تحديد احتياجات نظام المعلومات يلي ذلك تصميم و تنفيذ النظام لتلبية تلك الاحتياجات.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":815,"en":"Tactical Planning","ar":"تخطيط تكتيكي","definition_en":"A plan for achieving the entity’s objectives covering a relatively short time period, usually one year.","definition_ar":"خطة لإنجاز غايات الكيان، تُغطي نسبياً فترة زمنية قصيرة، عادةً سنة واحدة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":816,"en":"Target Costing","ar":"احتساب تكاليف القصد","definition_en":"A cost management tool used to reduce the overall cost of a product over its entire life cycle. The target is a predetermined cost that should result in an acceptable price to customers as well as an acceptable return to the organization.","definition_ar":"أداة لإدارة التكاليف، تستخدم في خفض تكلفة المنتج ككل خلال دورة حياة المنتج بأكملها. و القصد هو تكلفة ذات تحديد مسبق، ينبغي أن ينتج عنها سعر مقبول للزبائن فضلًا عن العائد المقبول للوحدة المنظمة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":817,"en":"Target Pricing","ar":"تسعير القصد","definition_en":"Setting a selling price for a product or service based on the value of the product or service to the customer, constrained by competitor’s prices of similar items.","definition_ar":"وضع سعر لبيع منتج أو خدمة على أساس قيمة المنتج أو الخدمة للزبون، ما يعيقه أسعار المنافسين لبنود مشابهة.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":818,"en":"Tariffs","ar":"تعرُفات","definition_en":"Taxes levied on goods imported into a country.","definition_ar":"ضرائب، تُجبى على البضاعة المستوردة إلى دولة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":819,"en":"Taxation","ar":"ضرائب","definition_en":"The act of a government imposing a levy on individuals or corporations.","definition_ar":"قانون من الحكومة، يفرض مكوس على الأفراد أو الشركات العامة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":820,"en":"Teleology","ar":"غائية","definition_en":"A moral philosophy that identifies an action as morally good or not depending on the end achieved (as opposed to deontology.)","definition_ar":"فلسفة معنوية، تُعرّف الفعل معنوياً أنه جيد أو أنه لا يتبع النهاية المنجزة (مما يتعارض مع غير الغائية (deontology).)","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":821,"en":"Temporary Differences","ar":"فروقات مؤقتة","definition_en":"Difference between accounting income and tax income that will reverse in later years.","definition_ar":"فرق بين دخل المحاسبة و دخل الضريبة الذي سيعكس في سنوات لاحقة.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":822,"en":"Theory of Constraints","ar":"نظرية المعيقات","definition_en":"A method of optimizing a process when faced with limiting factors and bottlenecks.","definition_ar":"طريقة للارتقاء بالعملية عندما تواجه عوامل مُحدِّدة و عنق زجاجة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":823,"en":"Throughput Contribution","ar":"مساهمة مُغربَلة","definition_en":"Revenue less direct material costs of goods sold.","definition_ar":"الإيرادات ناقص تكاليف المواد المباشرة للبضاعة المباعة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":824,"en":"Throughput Costing","ar":"احتساب التكاليف المُغربَلة","definition_en":"An inventory costing method that treats all costs except those related to variable direct materials as costs of the accounting period in which they are incurred. The variable direct material costs are the only ones included in inventory values. (Also called Super- Variable Costing.)","definition_ar":"طريقة لاحتساب تكاليف المخزون، تتعامل مع جميع التكاليف عدا المتعلقة بالمواد المباشرة المتغيرة كتكاليف تُتكبد في فترة المحاسبة. و تشمل قيم المخزون تكاليف المواد المباشرة المتغيرة فقط وحدها. (يسمى أيضاً احتساب التكاليف السوبر متغيرة.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":825,"en":"Time Drafts","ar":"حوالات لأجل","definition_en":"A financial instrument that is payable at a specified point in the future.","definition_ar":"أداة مالية قابلة للدفع عند نقطة محددة في المستقبل.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":826,"en":"Time Series Analysis","ar":"تحليل متسلسلة زمنية","definition_en":"Method for analyzing a data series indexed in time order, and used to predict future values based on the previously observed values.","definition_ar":"طريقة لتحليل متسلسلة بيانات مفهرسة بنسق زمني، تُستخدم للتنبؤ بقيم المستقبل على أساس قيم لوحظت مسبقاً.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":827,"en":"Time Value of Money","ar":"قيمة المال مع الوقت","definition_en":"The concept that money now is worth more than in the future, even after adjusting for inflation, because the money now can earn interest until the time the money in the future would be received.","definition_ar":"مفهوم أن مقدار المال الآن هو أكبر من مقدار المال في المستقبل، حتى بعد تسوية التضخم، لأن المال الآن يمكن أن يجني فوائد حتى وقت استلام المال في المستقبل.","topic":"Investment Decisions","difficulty":"Intermediate"},{"id":828,"en":"Times Interest Earned","ar":"مرات جني الفوائد","definition_en":"The ratio of earnings before interest, income taxes, and extraordinary items (EBIT) to annual interest expense. A measure of the entity’s ability to make interest payments when they are due; i.e., the number of times interest is covered by earnings. (Also called Interest Coverage.)","definition_ar":"نسبة المدخولات قبل الفوائد، و ضريبة الدخل، و البنود الاستثنائية (EBIT) إلى مصاريف الفوائد السنوية. و قياس لمقدرة الكيان على الوفاء بدفعات الفوائد عندما تستحق؛ أي، عدد مرات تغطية الفوائد بالمدخولات. (يسمى أيضاً تغطية الفوائد.)","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":829,"en":"Top-Down Approach","ar":"نهج من القمة للأسفل","definition_en":"An approach to auditing internal controls whereby specific risk factors are identified to determine the scope and evidence required in the assessment of internal control. (Also called Risk-based Approach.)","definition_ar":"نهج لتدقيق الضوابط الداخلية، تُعرّف به عوامل محددة في المخاطر لتحديد متطلبات تقييم الضوابط الداخلية من نطاق و أدلة. (يسمى أيضاً نهج على أساس المخاطر.)","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":830,"en":"Tracking Stock","ar":"أسهم التتبع","definition_en":"A class of common stock that is tied to the performance of a particular division within the corporation; a way of divesting a business line without losing complete control.","definition_ar":"تصنيف للأسهم العادية، يكون مربوطاً بأداء قسم محدد ضمن حيز الشركة العامة؛ كطريقة لتجريد خط من خطوط الأعمال بدون فقدان الضبط الكامل.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":831,"en":"Trade Credit","ar":"ائتمان تجاري","definition_en":"Buying goods and services on account; a form of short-term financing.","definition_ar":"شراء بضاعة أو خدمات على الحساب؛ كشكل من أشكال التمويل قصير المدة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":832,"en":"Trade Discount","ar":"خصم تجاري","definition_en":"A reduction in the stated selling price based on quantities ordered or purchased.","definition_ar":"تخفيض على ما ورد كسعر للبيع على أساس كميات الطلبية أو الشراء.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":833,"en":"Trading Securities","ar":"أوراق مالية متداولة","definition_en":"Investments in debt and equity securities that the company has purchased to sell in the short term.","definition_ar":"استثمارات في الأوراق المالية كديون أو حقوق ملكية، تشتريها الشركة لتبيعها في مدة قصير.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":834,"en":"Transaction Controls","ar":"ضوابط المعاملات","definition_en":"Internal controls within information systems to review individual transactions for accuracy, completeness, and validity.","definition_ar":"ضوابط داخلية ضمن حيز أنظمة المعلومات لمراجعة معاملات فردية من حيث الدقة، و الاكتمال، و سريان المفعول.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":835,"en":"Transaction Gains or Losses","ar":"خسائر أو مكاسب المعاملات","definition_en":"Gains or losses that result from a change in exchange rates between the functional currency and the currency in which a foreign currency transaction is denominated.","definition_ar":"مكاسب أو خسائر، تنتج من تغير في أسعار الصرف بين العملة الوظيفية و العملة التي تسيطر على معاملة العملة الأجنبية.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":836,"en":"Transaction Processing","ar":"معالجة المعاملات","definition_en":"The component of an information system that converts economic events into financial transactions, records financial transactions in the accounting records, and distributes financial information to operating personnel.","definition_ar":"مكوّن من مكونات نظام المعلومات، يُحوّل الأحداث الاقتصادية إلى معاملات مالية، و يسجل المعاملات المالية في سجلات المحاسبة، و يوزع المعلومات المالية على موظفي التشغيل.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":837,"en":"Transfer Pricing","ar":"تسعير التحويل","definition_en":"Price at which goods and services are transferred from one profit center to another.","definition_ar":"سعر تُحوّل به البضاعة و الخدمات من مركز ربح إلى آخر.","topic":"Performance Management","difficulty":"Intermediate"},{"id":838,"en":"Translation Adjustments","ar":"تسويات التحويل","definition_en":"Adjustments that result when an entity’s financial statements are translated from the entity’s functional currency into the reporting currency.","definition_ar":"تسويات، تَنتج عندما تُحوّل القوائم المالية للكيان من العملة الوظيفية في الكيان إلى عملة إعداد التقارير.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":839,"en":"Transmission","ar":"إرسال","definition_en":"In communications, the mechanism by which the message is transferred from the sender to the intended recipients.","definition_ar":"آلية في الاتصالات، لتحويل الرسالة من المُرسل إلى المستقبلين المنشودين.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":840,"en":"Treasury Bills (T-Bills)","ar":"أذونات الخزانة (T-Bills)","definition_en":"Short term securities issued by the U.S. Treasury with minimum denominations of $10,000 and maturities of three months, six months and one year. They are issued at a discount to face value.","definition_ar":"أوراق مالية لمدة قصيرة، تصدرها خزانة الولايات المتحدة بفئات دنيا من 10,000$ دولار و باستحقاقات في ثلاثة أشهر، و ستة أشهر، و سنة واحدة. و تُصدر بخصم من القيمة الوُجهيّة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":841,"en":"Treasury Bonds","ar":"صكوك الخزانة","definition_en":"Long term securities issued by the U.S. Treasury with minimum denominations of $1,000 and maturities of ten years or more.","definition_ar":"أوراق مالية لمدة طويلة، تصدرها خزانة الولايات المتحدة بفئات دنيا من 1,000$ دولار و باستحقاقات في عشر سنوات أو أكثر.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":842,"en":"Treasury Notes","ar":"إشعارات الخزانة","definition_en":"Medium term securities issued by the U.S. Treasury with minimum denominations from $1,000 and maturities of two to ten years.","definition_ar":"أوراق مالية مدتها متوسطة، تصدرها خزانة الولايات المتحدة بفئات دنيا من 1,000$ دولار و باستحقاقات من سنتين إلى عشر سنوات.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":843,"en":"Treasury Stock","ar":"أسهم الخزانة","definition_en":"Fully-paid capital stock reacquired by the issuing company through gift, purchase, or otherwise, and available for resale or cancellation.","definition_ar":"أسهم رأس المال المدفوعة تماماً، يعاد استحواذها من قبل الشركة المصدرة لها من خلال الإهداء، أو الشراء، أو غير ذلك، و تصبح متاحة لإعادة البيع أو إلغائها.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":844,"en":"Trial Balance","ar":"ميزان المراجعة","definition_en":"A list of all of the accounts in the general ledger with their respective debit or credit balances at a given point in time.","definition_ar":"قائمة بجميع الحسابات التي في الأستاذ العام مع الأرصدة المدينة أو الدائنة الخاصة بكل منها عند نقطة معطاة من الزمن.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":845,"en":"Trojan Horse","ar":"حصان طروادة","definition_en":"A computer program that appears to perform a useful and innocent function, however, it is actually a malicious program that is harmful when executed.","definition_ar":"برامج حاسوب، يظهر أن مسار عملها بريء و مفيد، لكن، فعلياً هي برامج خبيثة و ضارة عند التنفيذ.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":846,"en":"Uncollectible Accounts Receivable","ar":"حسابات مدينة غير قابلة للتحصيل","definition_en":"An Account Receivable that has been reviewed and a determination made that the amount due will not be collected.","definition_ar":"حساب مدين تم مراجعته و البت تحديداً بأن المبلغ المستحق لن يحصّل.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":847,"en":"Unearned Revenue","ar":"إيرادات لم تُجنى","definition_en":"A liability that represents the amount of goods or services that a company owes its customers. The cash has been collected, but the revenue has not been earned.","definition_ar":"مطلوبات، تُمثل مبلغ البضاعة أو الخدمات الذي تدين به الشركة لزبائنها. تم تحصيل النقد، لكن الإيراد لم يُجنى.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":848,"en":"Unexpected Loss","ar":"خسائر غير متوقعة","definition_en":"Loss in excess of the expected average loss.","definition_ar":"خسائر فائضة عن متوسط الخسائر المتوقع.","topic":"Risk Management","difficulty":"Intermediate"},{"id":849,"en":"Unfavorable Variance","ar":"انحراف غير مواتي","definition_en":"The amount by which actual cost exceeds standard or budgeted cost, or the amount by which actual revenue is less than standard or budgeted revenue.","definition_ar":"مبلغ، تتجاوز به التكلفة الفعلية التكلفة المعيارية أو تكلفة الموازنة، أو مبلغ يقل به الإيراد الفعلي عن الإيراد المعياري أو إيراد الموازنة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":850,"en":"Unit Contribution","ar":"مساهمة الوحدة","definition_en":"The difference between the selling price and the variable cost of one unit of a product.","definition_ar":"الفرق بين سعر البيع و التكلفة المتغيرة لوحدة واحدة من المنتج.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":851,"en":"Unit Cost","ar":"تكلفة الوحدة","definition_en":"The cost of one unit of a product or of one unit of a cost element of a product. It is usually obtained by dividing a total cost by the total number of units.","definition_ar":"تكلفة وحدة واحدة من منتَج أو وحدة واحدة من عنصر تكلفة منتج. و عادةً يحصل عليها بتقسيم مجموع التكاليف على مجموع عدد الوحدات.","topic":"Cost Management","difficulty":"Intermediate"},{"id":852,"en":"Unrealized Gain or Loss","ar":"خسائر أو مكاسب غير متحققة","definition_en":"An increase or decrease in the market value of a company’s investments in securities that have not been sold.","definition_ar":"زيادة أو نقصان في قيمة السوق لاستثمارات الشركة من الأوراق المالية التي لم تباع.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":853,"en":"Unstructured Data","ar":"بيانات غير مهيكلة","definition_en":"Data that is not organized in a predefined manner.","definition_ar":"بيانات، لم تُنظّم على غرار ما هو سابق التعريف.","topic":"Technology & Analytics","difficulty":"Intermediate"},{"id":854,"en":"Unsystematic Risk","ar":"مخاطر غير نظامية","definition_en":"The risk of price change due to the unique circumstances of a specific security or enterprise, as opposed to the overall market. This risk can be virtually eliminated from a portfolio through diversification. (Also called Company Risk.)","definition_ar":"مخاطر تغيّر السعر جرّاء ظروف فريدة لأوراق مالية أو لمؤسسة (enterprise) محددة، مما يتعارض مع السوق العام. تلك المخاطر يمكن القضاء عليها افتراضياً من المحفظة من خلال التنويع. (يسمى أيضاً مخاطر الشركة.)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":855,"en":"Upstream Costs","ar":"تكاليف تمهيدية","definition_en":"Costs incurred prior to the time a product is manufactured, including research and development and design.","definition_ar":"تكاليف، تُتكبد قبل وقت تصنيع المنتج، تشمل البحث، و التطوير، و التصميم.","topic":"Cost Management","difficulty":"Intermediate"},{"id":856,"en":"Utilitarianism","ar":"استنفاعية","definition_en":"A form of teleology in which an action is right or wrong depending on whether it promotes happiness or not.","definition_ar":"شكل من أشكال الغائية يكون به الفعل صح أم خطأ تبعاً لما إذا كان يُروّج للسعادة أو لا.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":857,"en":"Utility","ar":"استنفاع","definition_en":"The relative satisfaction or need gratification derived from a good or service.","definition_ar":"رضا نسبي أو إرضاء حاجة مستمدة من بضاعة أو خدمة.","topic":"Economics & General Business","difficulty":"Intermediate"},{"id":858,"en":"Valuation","ar":"تقدير القيمة","definition_en":"The process of determining the value of an asset, a security, or an entire entity.","definition_ar":"عملية تحديد قيمة أصل، أو ورقة مالية، أو كيان بأكمله.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":859,"en":"Value","ar":"قيمة","definition_en":"Attributed worth, expressed in money and applied to a particular asset, to services rendered, to a group of assets, or to an entire business unit, such as the value of a plant or business enterprise.","definition_ar":"مقدار يُعزى، و يُعبّر عنه بالمال، و يُطبّق على أصل معين، أو على خدمات مُسداة، أو على مجموعة من الأصول، أو على وحدة أعمال بأكملها، كقيمة المعمل أو المؤسسة (enterprise).","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":860,"en":"Value at Risk (VAR)","ar":"قيمة عند المخاطر (VAR)","definition_en":"The worst loss that might be expected from holding a security or portfolio over a given period of time, given a specified level of probability.","definition_ar":"أسوء خسارة، يمكن توقعها من الإمساك على ورقة مالية أو محفظة خلال فترة من الزمن معطاة، و في مستوى احتمالية محدد و معطى.","topic":"Risk Management","difficulty":"Intermediate"},{"id":861,"en":"Value Chain","ar":"سلسلة القيمة","definition_en":"The basic business functions that increase the usefulness to the customer of a product or service. For a manufacturing entity, the functions typically include Research & Development, Design, Production, Marketing, Distribution, and Customer Service.","definition_ar":"مسارات العمل الأساسية في الأعمال، تزداد بها استفادة الزبون من منتج أو خدمة. و نموذجياً في كيان للتصنيع، تشمل مسارات العمل البحث و التطوير، و التصميم، و الإنتاج، و التسويق، والتوزيع، و خدمة الزبائن.","topic":"Cost Management","difficulty":"Intermediate"},{"id":862,"en":"Value Engineering","ar":"هندسة القيمة","definition_en":"An evaluation of the activities in the Value Chain to reduce costs without sacrificing customer satisfaction.","definition_ar":"تقييم النشاطات في سلسلة القيمة لتخفيض التكاليف بدون التضحية برضا الزبائن.","topic":"Cost Management","difficulty":"Intermediate"},{"id":863,"en":"Value-Added","ar":"القيمة المضافة","definition_en":"Activities and processes that add value or usefulness to consumers of a product or service.","definition_ar":"أنشطة و عمليات، تضيف قيمة أو منفعة للزبائن من المنتج أو الخدمة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":864,"en":"Value-Based Pricing","ar":"تسعير القيمة المضافة","definition_en":"A pricing strategy where the selling price of a good or service is based primarily on the customer’s perceived value of the good or service.","definition_ar":"إستراتيجية تسعير، يكون بها سعر البيع لبضاعة أو خدمة على أساس القيمة المدركة من الزبون للبضاعة أو الخدمة في المقام الأول.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":865,"en":"Variable Cost","ar":"تكلفة متغيرة","definition_en":"An operating expense that varies directly, and proportionately, with sales or production volume, facility utilization, or some other measure of activity.","definition_ar":"مصاريف تشغيل، تتغيرُ مباشرةً، و تناسبياً، مع حجم المبيعات أو الإنتاج، أو الاستنفاع بالمرفق، أو مع حجم قياس نشاط آخر.","topic":"Cost Management","difficulty":"Intermediate"},{"id":866,"en":"Variable Costing","ar":"احتساب التكاليف المتغيرة","definition_en":"Method of inventory costing that includes all direct manufacturing costs and variable indirect manufacturing costs as inventory (fixed indirect manufacturing costs are excluded). (Also called Direct Costing.)","definition_ar":"طريقة لاحتساب تكاليف المخزون، تشمل جميع تكاليف التصنيع المباشرة و تكاليف التصنيع الغير مباشرة المتغيرة للمخزون (تستبعد تكاليف التصنيع غير المباشرة الثابتة). (يسمى أيضاً احتساب التكاليف المباشرة.)","topic":"Cost Management","difficulty":"Intermediate"},{"id":867,"en":"Variable Overhead Efficiency Variance","ar":"انحراف فعالية الفوقية المتغيرة","definition_en":"Cost driver inputs actually used less the inputs that should have been used multiplied by the budgeted rate.","definition_ar":"مدخلات محرك التكلفة المستخدمة فعلياً ناقص المدخلات التي كان ينبغي استخدامها تُضرب بمعدل الموازنة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":868,"en":"Variable Overhead Expenses","ar":"مصاريف فوقية متغيرة","definition_en":"The portion of overhead costs that increase (decrease) as the number of units produced increase (decrease).","definition_ar":"جزئية تكاليف فوقية، تزيد (تنقص) مع ازدياد (تناقص) عدد الوحدات المنتجة.","topic":"Cost Management","difficulty":"Intermediate"},{"id":869,"en":"Variable Overhead Spending Variance","ar":"انحراف إنفاق الفوقية المتغيرة","definition_en":"Actual amount of overhead incurred less the expected amount based on the flexible budget.","definition_ar":"مبلغ الفوقية الفعلي المتكبد ناقصاً منه المبلغ المتوقع على أساس الموازنة المرنة.","topic":"Performance Management","difficulty":"Intermediate"},{"id":870,"en":"Variance","ar":"انحراف","definition_en":"The difference between actual results and standard budgeted results.","definition_ar":"الفرق بين النتائج الفعلية و نتائج الموازنة المعيارية.","topic":"Performance Management","difficulty":"Intermediate"},{"id":871,"en":"Verifiability","ar":"قابلية التحقق","definition_en":"The ability, through agreement among measures, to ensure that information represents what it purports to represent or that the chosen method of measurement has been used without error or bias.","definition_ar":"مقدرة، من خلال الاتفاق بين الإجراءات، على توكيد أن المعلومات تمثل ما ترمي إلى تمثيله أو أن طريقة القياس المختارة قد استخدمت بدون خطأ أو تحيز.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":872,"en":"Vertical Analysis","ar":"تحليل عمودي","definition_en":"Compares each amount on a financial statement with a base amount selected from the same year; e.g., advertising as a percent of sales.","definition_ar":"يقارن كل مبلغ في القائمة المالية بمبلغ أساس، يُختار من نفس السنة؛ مثل، الدعاية كنسبة مئوية من المبيعات.","topic":"Financial Statement Analysis","difficulty":"Intermediate"},{"id":873,"en":"Virtue","ar":"فضيلة","definition_en":"Moral excellence, behavior showing high moral standards.","definition_ar":"تَميُّز معنوي، يستعرض سلوك المعايير المعنوية الرفيعة.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":874,"en":"Virus","ar":"فيروس","definition_en":"A self-replicating computer program that infects the host computer by spreading copies of itself into other executable programs.","definition_ar":"برامج حاسوب، تُكرر ذاتها ثم تصيب الحاسوب المضيف بنشر نسخها الذاتية في البرامج التنفيذية الأخرى.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":875,"en":"Vision","ar":"رؤية","definition_en":"A statement describing the aspirations of the organization.","definition_ar":"بيان، يصف تطلعات الوحدة المنظمة.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"},{"id":876,"en":"Vulnerability Testing","ar":"فحص قابلية التأثر","definition_en":"A software testing technique performed to identify and evaluate the risks in a system to reduce the probability of unauthorized access.","definition_ar":"تقنية لفحص البرمجيات، تُؤدّى لمعرفة و تقييم مخاطر النظام لتخفيض احتمالية الدخول غير المصرح به.","topic":"Internal Controls","difficulty":"Intermediate"},{"id":877,"en":"Warrant","ar":"مذكرة","definition_en":"A certificate entitling the holder to buy a specified number of shares for a specified time for a specified price.","definition_ar":"شهادة بأحقيّة مُمسكها بشراء عدد محدد من الحصص في زمن محدد و بسعر محدد.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":878,"en":"Warranty","ar":"ضمانة","definition_en":"A promise by a seller to correct, for a stated period of time, deficiencies in products sold.","definition_ar":"وعد من البائع بتصحيح التقصير في المنتجات المباعة، يَردُ بفترة من الزمن.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":879,"en":"Weighted Average Cost of Capital (WACC)","ar":"متوسط مرجح لتكلفة رأس المال (WACC)","definition_en":"An average representing the required return on all of a company’s securities. Each source of capital, such as stocks, bonds, and other debt, is weighted in the calculation according to its percentage of the company’s capital structure.","definition_ar":"متوسط، يُمثّل العائد الذي تتطلبه جميع الأوراق المالية للشركة. يوزن كل مصدر من مصادر رأس المال، كالأسهم، و الصكوك، و الديون الأخرى، وفقاً لاحتساب نسبته المئوية من هيكل رأس مال الشركة.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":880,"en":"Weighted Moving Average","ar":"متوسط متحرك مرجّح","definition_en":"A method of calculating central tendency over time in an attempt to identify long-term trends. For each time period after the initial one, the earliest value is dropped from the calculation and the most recent one is added in, to make an average over the same length of time. More recent data points are weighted higher than earlier data points.","definition_ar":"طريقة لاحتساب مركز القابلية مع مرور الزمن كشروع للتعرّف على التوجهات طويلة المدة. و لكل فترة زمنية بعد الفترة الأولي، تُسقط أقدم قيمة من الاحتساب و تُضاف أحدث قيمة إليه، لعمل متوسط خلال نفس المدة الزمنية. فتصبح نقاط البيانات الأحدث أعلى وزناً من نقاط البيانات الأقدم.","topic":"Decision Analysis","difficulty":"Intermediate"},{"id":881,"en":"Whistleblower","ar":"(Whistleblower) مُطلق الصّفارة","definition_en":"Person who tells the public or someone in authority about alleged dishonest or illegal activities occurring within an organization.","definition_ar":"شخص أو شخص ما ذو سلطة، يُخبر عامة الناس عن أنشطة بلا أمانة أو بلا شرعية حدثت ضمن حيز الوحدة المنظمة.","topic":"Professional Ethics","difficulty":"Intermediate"},{"id":882,"en":"Working Capital","ar":"رأس المال العامل","definition_en":"Current Assets less Current Liabilities. (Also called Net Working Capital.)","definition_ar":"الأصول الجارية ناقصاً منها المطلوبات الجارية. (يسمى أيضاً صافي رأس المال العامل)","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":883,"en":"Work-in-Process Inventory","ar":"مخزون قيد تشغيل العمل","definition_en":"The costs incurred to date on products for which production has begun but has not been completed.","definition_ar":"تكاليف مُتكبّدة حتى تاريخه على منتجات بدأ إنتاجها ولكنها لم تكتمل.","topic":"Cost Management","difficulty":"Intermediate"},{"id":884,"en":"Write-Off","ar":"شطب","definition_en":"Charging the cost of an asset to expense or to a loss account.","definition_ar":"تحميل تكلفة أحد الأصول على حساب أحد المصاريف أو الخسائر.","topic":"External Financial Reporting","difficulty":"Intermediate"},{"id":885,"en":"Yield","ar":"محصّلة","definition_en":"Income as a percentage of price.","definition_ar":"الدخل كنسبة مئوية من السعر.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":886,"en":"Yield Variance","ar":"انحراف المحصّلة","definition_en":"The difference between the actual quantity of material used for a given amount of product and the standard quantity of the material required for that amount of product, priced at the standard cost per unit of material.","definition_ar":"الفرق بين كمية المواد الفعلية المستخدمة في منتج بمبلغ معطى و كمية المواد المعيارية التي يتطلبها ذلك المبلغ من المنتج، بتسعير التكلفة المعيارية لكل وحدة من المواد.","topic":"Performance Management","difficulty":"Intermediate"},{"id":887,"en":"Zero Balance Account","ar":"حساب مُصفّر الرصيد","definition_en":"A disbursement (checking) account that has a zero balance. As checks are submitted for payment, funds are transferred from another account to exactly cover the amount of the checks, generally on a daily basis.","definition_ar":"حساب صرف (شيكات) ذو رصيد صفري. إذ تُسلّم الشيكات لإتمام الدفع، و تُحوّل الأموال من حساب آخر لتغطية مبلغ الشيكات بالضبط، عموماً على أسس يومية.","topic":"Corporate Finance","difficulty":"Intermediate"},{"id":888,"en":"Zero-Based Budgeting","ar":"إعداد موازنة على أساس الصفر","definition_en":"Preparing a budget from the ground up, as though the budget were being prepared for the first time. Alternative means of conducting activities and alternative budget amounts are evaluated.","definition_ar":"تحضير موازنة من الأرض لفوق، و كأنّ الموازنة تُحضّر لأول مرة. يُقيّم بها بدائل الوسائل للقيام بالأنشطة و مبالغ الموازنة للبدائل.","topic":"Planning, Budgeting & Forecasting","difficulty":"Intermediate"}];
